{"command":"mkdir -p /workspace/internal/logutil /workspace/cmd/gomplate && cd /workspace && cat > internal/logutil/log.go <<'EOF'
// Package logutil configures the process-wide structured logger.
package logutil

import (
	"context"
	"encoding"
	"fmt"
	"io"
	"log"
	"log/slog"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
	"unicode"

	"golang.org/x/term"
)

const (
	ansiReset       = "\x1b[0m"
	ansiFaint       = "\x1b[2m"
	ansiBrightRed   = "\x1b[91m"
	ansiBrightGreen = "\x1b[92m"
	ansiBrightYel   = "\x1b[93m"
	ansiRedFaint    = "\x1b[91;2m"
)

// pre-initialization: the default slog logger is used, backed by the
// standard log package without any prefix.
func init() {
	log.SetFlags(0)
}

// Init configures the default logger based on the verbose flag and the
// GOMPLATE_LOG_FORMAT environment variable.
func Init(w io.Writer, verbose bool) {
	level := slog.LevelWarn
	if verbose {
		level = slog.LevelDebug
	}

	format := os.Getenv("GOMPLATE_LOG_FORMAT")
	if format == "" {
		if isTerminal(w) {
			format = "console"
		} else {
			format = "json"
		}
	}

	var h slog.Handler
	switch format {
	case "console":
		h = newConsoleHandler(w, &consoleOptions{Level: level, NoColor: !isTerminal(w)})
	case "simple":
		h = newConsoleHandler(w, &consoleOptions{
			Level:   level,
			NoColor: !isTerminal(w),
			ReplaceAttr: func(_ []string, a slog.Attr) slog.Attr {
				switch a.Key {
				case slog.TimeKey, slog.LevelKey:
					return slog.String(a.Key, "")
				}
				return a
			},
		})
	case "logfmt":
		h = slog.NewTextHandler(w, &slog.HandlerOptions{Level: level})
	default:
		h = slog.NewJSONHandler(w, &slog.HandlerOptions{Level: level})
	}
	slog.SetDefault(slog.New(h))
}

func isTerminal(w io.Writer) bool {
	if f, ok := w.(*os.File); ok {
		return term.IsTerminal(int(f.Fd()))
	}
	return false
}

type consoleOptions struct {
	Level       slog.Leveler
	NoColor     bool
	ReplaceAttr func(groups []string, a slog.Attr) slog.Attr
}

type consoleHandler struct {
	mu          *sync.Mutex
	w           io.Writer
	level       slog.Leveler
	noColor     bool
	replaceAttr func([]string, slog.Attr) slog.Attr
	attrsPrefix string
	groupPrefix string
	groups      []string
}

func newConsoleHandler(w io.Writer, opts *consoleOptions) *consoleHandler {
	h := &consoleHandler{mu: &sync.Mutex{}, w: w, level: slog.LevelInfo}
	if opts.Level != nil {
		h.level = opts.Level
	}
	h.noColor = opts.NoColor
	h.replaceAttr = opts.ReplaceAttr
	return h
}

func (h *consoleHandler) clone() *consoleHandler {
	return &consoleHandler{
		mu: h.mu, w: h.w, level: h.level, noColor: h.noColor,
		replaceAttr: h.replaceAttr, attrsPrefix: h.attrsPrefix,
		groupPrefix: h.groupPrefix, groups: h.groups,
	}
}

func (h *consoleHandler) Enabled(_ context.Context, l slog.Level) bool {
	return l >= h.level.Level()
}

func (h *consoleHandler) WithGroup(name string) slog.Handler {
	if name == "" {
		return h
	}
	h2 := h.clone()
	h2.groupPrefix += name + "."
	h2.groups = append(h2.groups, name)
	return h2
}

func (h *consoleHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	if len(attrs) == 0 {
		return h
	}
	h2 := h.clone()
	var sb strings.Builder
	for _, a := range attrs {
		h.appendAttr(&sb, a, h.groupPrefix, h.groups)
	}
	h2.attrsPrefix = h.attrsPrefix + sb.String()
	return h2
}

func (h *consoleHandler) Handle(_ context.Context, r slog.Record) error {
	var sb strings.Builder
	rep := h.replaceAttr

	if !r.Time.IsZero() {
		val := r.Time.Round(0)
		if rep == nil {
			h.appendTime(&sb, val)
			sb.WriteByte(' ')
		} else if a := rep(nil, slog.Time(slog.TimeKey, val)); a.Key != "" {
			if a.Value.Kind() == slog.KindTime {
				h.appendTime(&sb, a.Value.Time())
			} else {
				h.appendValue(&sb, a.Value, false)
			}
			sb.WriteByte(' ')
		}
	}

	if rep == nil {
		h.appendLevel(&sb, r.Level)
		sb.WriteByte(' ')
	} else if a := rep(nil, slog.Any(slog.LevelKey, r.Level)); a.Key != "" {
		h.appendValue(&sb, a.Value, false)
		sb.WriteByte(' ')
	}

	if rep == nil {
		sb.WriteString(r.Message)
		sb.WriteByte(' ')
	} else if a := rep(nil, slog.String(slog.MessageKey, r.Message)); a.Key != "" {
		h.appendValue(&sb, a.Value, false)
		sb.WriteByte(' ')
	}

	if len(h.attrsPrefix) > 0 {
		sb.WriteString(h.attrsPrefix)
	}

	r.Attrs(func(a slog.Attr) bool {
		h.appendAttr(&sb, a, h.groupPrefix, h.groups)
		return true
	})

	out := sb.String()
	if len(out) == 0 {
		return nil
	}
	out = out[:len(out)-1] + "\n"

	h.mu.Lock()
	defer h.mu.Unlock()
	_, err := io.WriteString(h.w, out)
	return err
}

func (h *consoleHandler) color(sb *strings.Builder, code string) {
	if !h.noColor {
		sb.WriteString(code)
	}
}

func (h *consoleHandler) appendTime(sb *strings.Builder, t time.Time) {
	h.color(sb, ansiFaint)
	sb.WriteString(t.Format("15:04:05"))
	h.color(sb, ansiReset)
}

func (h *consoleHandler) appendLevel(sb *strings.Builder, l slog.Level) {
	delta := func(base slog.Level) {
		if d := l - base; d != 0 {
			sb.WriteString(fmt.Sprintf("%+d", d))
		}
	}
	switch {
	case l < slog.LevelInfo:
		sb.WriteString("DBG")
		delta(slog.LevelDebug)
	case l < slog.LevelWarn:
		h.color(sb, ansiBrightGreen)
		sb.WriteString("INF")
		delta(slog.LevelInfo)
		h.color(sb, ansiReset)
	case l < slog.LevelError:
		h.color(sb, ansiBrightYel)
		sb.WriteString("WRN")
		delta(slog.LevelWarn)
		h.color(sb, ansiReset)
	default:
		h.color(sb, ansiBrightRed)
		sb.WriteString("ERR")
		delta(slog.LevelError)
		h.color(sb, ansiReset)
	}
}

func (h *consoleHandler) appendAttr(sb *strings.Builder, a slog.Attr, groupsPrefix string, groups []string) {
	a.Value = a.Value.Resolve()
	if rep := h.replaceAttr; rep != nil && a.Value.Kind() != slog.KindGroup {
		a = rep(groups, a)
		a.Value = a.Value.Resolve()
	}
	if a.Equal(slog.Attr{}) {
		return
	}
	switch a.Value.Kind() {
	case slog.KindGroup:
		if a.Key != "" {
			groupsPrefix += a.Key + "."
			groups = append(groups, a.Key)
		}
		for _, ga := range a.Value.Group() {
			h.appendAttr(sb, ga, groupsPrefix, groups)
		}
	default:
		if err, ok := a.Value.Any().(error); ok && a.Key == "err" {
			h.color(sb, ansiRedFaint)
			sb.WriteString(groupsPrefix + a.Key + "=")
			h.color(sb, ansiReset)
			h.color(sb, ansiBrightRed)
			appendString(sb, err.Error(), true)
			h.color(sb, ansiReset)
		} else {
			h.color(sb, ansiFaint)
			sb.WriteString(groupsPrefix + a.Key + "=")
			h.color(sb, ansiReset)
			h.appendValue(sb, a.Value, true)
		}
		sb.WriteByte(' ')
	}
}

func (h *consoleHandler) appendValue(sb *strings.Builder, v slog.Value, quote bool) {
	switch v.Kind() {
	case slog.KindString:
		appendString(sb, v.String(), quote)
	case slog.KindInt64:
		sb.WriteString(strconv.FormatInt(v.Int64(), 10))
	case slog.KindUint64:
		sb.WriteString(strconv.FormatUint(v.Uint64(), 10))
	case slog.KindFloat64:
		sb.WriteString(strconv.FormatFloat(v.Float64(), 'g', -1, 64))
	case slog.KindBool:
		sb.WriteString(strconv.FormatBool(v.Bool()))
	case slog.KindDuration:
		appendString(sb, v.Duration().String(), quote)
	case slog.KindTime:
		appendString(sb, v.Time().Format("2006-01-02T15:04:05.000Z07:00"), quote)
	case slog.KindAny:
		switch cv := v.Any().(type) {
		case slog.Level:
			h.appendLevel(sb, cv)
		case encoding.TextMarshaler:
			data, err := cv.MarshalText()
			if err != nil {
				break
			}
			appendString(sb, string(data), quote)
		case error:
			appendString(sb, cv.Error(), quote)
		default:
			appendString(sb, fmt.Sprintf("%+v", cv), quote)
		}
	}
}

func appendString(sb *strings.Builder, s string, quote bool) {
	if quote && needsQuoting(s) {
		sb.WriteString(strconv.Quote(s))
	} else {
		sb.WriteString(s)
	}
}

func needsQuoting(s string) bool {
	if len(s) == 0 {
		return true
	}
	for _, r := range s {
		if unicode.IsSpace(r) || r == '"' || r == '=' || !unicode.IsPrint(r) {
			return true
		}
	}
	return false
}
EOF
