}

// Main - the entrypoint for the CLI
func Main(ctx context.Context, args []string, stdin io.Reader, stdout, stderr io.Writer) error {
	ctx, cancel := signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)
	defer cancel()

	cmd := NewGomplateCmd(stdin, stdout, stderr)
	cmd.SetArgs(args)

	if err := cmd.ExecuteContext(ctx); err != nil {
		slog.Error("", "err", err)
		return err
	}
	return nil
}

// NewGomplateCmd - the root cobra command
func NewGomplateCmd(stdin io.Reader, stdout, stderr io.Writer) *cobra.Command {
	var cfg *config.Config
	var verbose bool

	rootCmd := &cobra.Command{
		Use:     "gomplate",
		Short:   "Process text files with Go templates",
		Version: Version,
		Args:    cobra.NoArgs,
		PreRunE: func(cmd *cobra.Command, args []string) error {
			var err error
			cfg, err = loadConfig(cmd, args)
			if err != nil {
				return err
			}
			cfg.Stdin = stdin
			cfg.Stdout = stdout
			cfg.Stderr = stderr

			verbose, _ = cmd.Flags().GetBool("verbose")
			logutil.Init(stderr, verbose)

			if cfgFile := usedConfigFile(cmd); cfgFile != "" {
				slog.Debug("using config file", "cfgFile", cfgFile)
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			slog.Debug("starting gomplate")
			slog.Debug("config is:\n"+cfg.String(), "version", Version, "build", BuildCommit)

			if cfg.Experimental {
				slog.SetDefault(slog.Default().With("experimental", true))
				slog.Info("experimental functions and features enabled!")
			}

			err := gomplate.Run(ctx, cfg)
			if err != nil {
				return err
			}
			if len(cfg.PostExec) > 0 {
				slog.Debug("running post-exec command", "args", cfg.PostExec)
				return postRunExec(ctx, cfg)
			}
			return nil
		},
