	rootCmd.SetErr(stderr)
	rootCmd.SetIn(stdin)
	rootCmd.SetVersionTemplate(`{{with .Name}}{{printf "%s " .}}{{end}}{{printf "version %s" .Version}}
`)
	// errors are printed by cobra with the "Error:" prefix, followed by the
	// usage - we reproduce that here, since SilenceErrors is set
	rootCmd.SilenceErrors = false

	initFlags(rootCmd)
	return rootCmd
}
