	cmd.Flags().StringArrayP("file", "f", []string{"-"}, "Template `file` to process. Omit to use standard input, or use --in or --input-dir")
	cmd.Flags().StringP("in", "i", "", "Template string to process (alternative to --file and --input-dir)")
	cmd.Flags().String("input-dir", "", "`directory` which is examined recursively for templates (alternative to --file and --in)")

	cmd.Flags().StringSlice("exclude", []string{}, "glob of files to not parse")
	cmd.Flags().StringSlice("exclude-processing", []string{}, "glob of files to be copied without parsing")
	cmd.Flags().StringSlice("include", []string{}, "glob of files to parse")

	cmd.Flags().StringArrayP("out", "o", []string{"-"}, "output `file` name. Omit to use standard output.")
	cmd.Flags().StringSliceP("template", "t", []string{}, "Additional template file(s)")
	cmd.Flags().String("output-dir", ".", "`directory` to store the processed templates. Only used for --input-dir")
	cmd.Flags().String("output-map", "", "Template string to map the input file to an output path")
	cmd.Flags().String("chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")

	cmd.Flags().Bool("exec-pipe", false, "pipe the output to the post-run exec command")

	cmd.Flags().String("left-delim", ldDefault, "override the default left-`delimiter` [$GOMPLATE_LEFT_DELIM]")
	cmd.Flags().String("right-delim", rdDefault, "override the default right-`delimiter` [$GOMPLATE_RIGHT_DELIM]")
	cmd.Flags().String("missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>")

	cmd.Flags().Bool("experimental", false, "enable experimental features [$GOMPLATE_EXPERIMENTAL]")

	cmd.Flags().BoolP("verbose", "V", false, "output extra information about what gomplate is doing")

	cmd.Flags().String("config", defaultConfigFile, "config file (overridden by commandline flags)")
}

func envOr(name, def string) string {
	if v := os.Getenv(name); v != "" {
		return v
	}
	return def
}

// usedConfigFile - returns the config file path if one was actually read
func usedConfigFile(cmd *cobra.Command) string {
	v, _ := cmd.Flags().GetString("usedConfigFile")
	_ = v
	return cfgFileUsed
}

var cfgFileUsed string

// loadConfig - read the config file (if present), and merge with the
// command-line flags & environment
func loadConfig(cmd *cobra.Command, args []string) (*config.Config, error) {
	flags := cmd.Flags()

	cfg, err := readConfigFile(cmd)
	if err != nil {
		return nil, err
	}

	cfg, err = cfg.ParseEnv()
	if err != nil {
		return nil, err
	}

	fcfg, err := cobraConfig(cmd, args)
	if err != nil {
		return nil, err
	}

	cfg = cfg.MergeFrom(fcfg)

	// apply the datasource headers to any datasources/contexts
	hdrs, err := parseHeaderArgs(flagStrings(flags, "datasource-header"))
	if err != nil {
		return nil, err
	}
	for k, v := range hdrs {
		if d, ok := cfg.DataSources[k]; ok {
			d.Header = v
			cfg.DataSources[k] = d
		}
		if c, ok := cfg.Context[k]; ok {
			c.Header = v
			cfg.Context[k] = c
		}
	}

	return cfg, nil
}

func readConfigFile(cmd *cobra.Command) (*config.Config, error) {
	cfgFileUsed = ""
	flags := cmd.Flags()
	cfgFile, _ := flags.GetString("config")
	cfgFlag := flags.Lookup("config")
	explicit := cfgFlag != nil && cfgFlag.Changed
	if !explicit {
		if v, ok := os.LookupEnv("GOMPLATE_CONFIG"); ok {
			cfgFile = v
			explicit = true
		}
	}

	cfg := &config.Config{}
	if cfgFile == "" {
		return cfg, nil
	}

	cwd, err := os.Getwd()
	if err != nil {
		return nil, fmt.Errorf("couldn't get working directory: %w", err)
	}
	rel := filepath.ToSlash(filepath.Join(cwd, cfgFile))
	rel = strings.TrimPrefix(rel, "/")
	fsys := os.DirFS("/")

	f, err := fsys.Open(rel)
	if err != nil {
		if !explicit && (os.IsNotExist(err) || isNotExist(err)) {
			return cfg, nil
		}
		return nil, fmt.Errorf("config file requested, but couldn't be opened: %w", err)
	}
	defer f.Close()

	cfg, err = config.Parse(f)
	if err != nil {
		return nil, fmt.Errorf("parsing config file %q: %w", cfgFile, err)
	}
	cfgFileUsed = cfgFile
	return cfg, nil
}

func isNotExist(err error) bool {
	var pe *fs.PathError
	if ok := asPathError(err, &pe); ok {
		return os.IsNotExist(pe.Err)
	}
	return false
}

func asPathError(err error, target **fs.PathError) bool {
	pe, ok := err.(*fs.PathError)
	if ok {
		*target = pe
	}
	return ok
}

func flagStrings(flags *pflag.FlagSet, name string) []string {
	f := flags.Lookup(name)
	if f == nil {
		return nil
	}
	switch v := f.Value.(type) {
	case pflag.SliceValue:
		return v.GetSlice()
	}
	return nil
}

// cobraConfig - build a config from the command-line flags
func cobraConfig(cmd *cobra.Command, args []string) (*config.Config, error) {
	flags := cmd.Flags()
	cfg := &config.Config{}
	var err error

	cfg.Input, _ = flags.GetString("in")
	cfg.InputDir, _ = flags.GetString("input-dir")
	cfg.InputFiles = flagStrings(flags, "file")

	includes, _ := flags.GetStringSlice("include")
	excludes, _ := flags.GetStringSlice("exclude")
	cfg.ExcludeGlob = processIncludes(includes, excludes)
	cfg.ExcludeProcessing, _ = flags.GetStringSlice("exclude-processing")

	if flags.Changed("output-dir") {
		cfg.OutputDir, _ = flags.GetString("output-dir")
	}
	cfg.OutputMap, _ = flags.GetString("output-map")
	cfg.OutputFiles = flagStrings(flags, "out")
	cfg.OutMode, _ = flags.GetString("chmod")

	if flags.Changed("left-delim") {
		cfg.LDelim, _ = flags.GetString("left-delim")
	}
	if flags.Changed("right-delim") {
		cfg.RDelim, _ = flags.GetString("right-delim")
	}
	if flags.Changed("missing-key") {
		cfg.MissingKey, _ = flags.GetString("missing-key")
	}
	cfg.ExecPipe, _ = flags.GetBool("exec-pipe")
	if flags.Changed("experimental") {
		cfg.Experimental, _ = flags.GetBool("experimental")
	}

	if dash := cmd.ArgsLenAtDash(); dash >= 0 && dash < len(args) {
		cfg.PostExec = args[dash:]
	}

	cfg.Templates, err = parseTemplateArgs(flagStrings(flags, "template"))
	if err != nil {
		return nil, err
	}

	cfg.DataSources, err = parseDatasourceArgs(flagStrings(flags, "datasource"))
	if err != nil {
		return nil, err
	}
	cfg.Context, err = parseDatasourceArgs(flagStrings(flags, "context"))
	if err != nil {
		return nil, err
	}

	cfg.Plugins, err = parsePluginArgs(flagStrings(flags, "plugin"))
	if err != nil {
		return nil, err
	}

	return cfg, nil
}

func processIncludes(includes, excludes []string) []string {
	if len(includes) == 0 && len(excludes) == 0 {
		return nil
	}
	out := []string{}
	// if any includes are provided, we exclude everything else first
	if len(includes) > 0 {
		out = append(out, "*")
		for _, i := range includes {
			out = append(out, "!"+i)
		}
	}
	out = append(out, excludes...)
	return out
}

func parseDatasourceArgs(args []string) (map[string]config.DataSource, error) {
	if len(args) == 0 {
		return nil, nil
	}
	out := map[string]config.DataSource{}
	for _, v := range args {
		alias, ds, err := parseDatasourceArg(v)
		if err != nil {
			return nil, err
		}
		out[alias] = ds
	}
	return out, nil
}

func parseDatasourceArg(value string) (alias string, ds config.DataSource, err error) {
	alias, u, _ := strings.Cut(value, "=")
	if u == "" {
		u = value
		alias = strings.SplitN(value, ".", 2)[0]
		if path.Base(u) != u {
			err = fmt.Errorf("invalid argument (%s): must provide an alias with files not in working directory", value)
			return alias, ds, err
		}
	}
	ds.URL, err = urlhelpers.ParseSourceURL(u)
	return alias, ds, err
}

func parseTemplateArgs(args []string) (map[string]config.DataSource, error) {
	if len(args) == 0 {
		return nil, nil
	}
	out := map[string]config.DataSource{}
	for _, v := range args {
		alias, u, _ := strings.Cut(v, "=")
		if u == "" {
			u = alias
		}
		pu, err := urlhelpers.ParseSourceURL(u)
		if err != nil {
			return nil, err
		}
		out[alias] = config.DataSource{URL: pu}
	}
	return out, nil
}

func parseHeaderArgs(args []string) (map[string]http.Header, error) {
	if len(args) == 0 {
		return nil, nil
	}
	out := map[string]http.Header{}
	for _, v := range args {
		alias, hdr, err := parseHeaderArg(v)
		if err != nil {
			return nil, err
		}
		if out[alias] == nil {
			out[alias] = http.Header{}
		}
		for k, vals := range hdr {
			for _, val := range vals {
				out[alias].Add(k, val)
			}
		}
	}
	return out, nil
}

func parseHeaderArg(value string) (alias string, hdr http.Header, err error) {
	parts := strings.SplitN(value, "=", 2)
	if len(parts) != 2 {
		return "", nil, fmt.Errorf("invalid datasource-header option '%s'", value)
	}
	alias = parts[0]
	hparts := strings.SplitN(parts[1], ":", 2)
	if len(hparts) != 2 {
		return "", nil, fmt.Errorf("invalid HTTP Header format '%s'", parts[1])
	}
	hdr = http.Header{}
	hdr.Add(strings.TrimSpace(hparts[0]), strings.TrimSpace(hparts[1]))
	return alias, hdr, nil
}

func parsePluginArgs(args []string) (map[string]config.PluginConfig, error) {
	if len(args) == 0 {
		return nil, nil
	}
	out := map[string]config.PluginConfig{}
	for _, v := range args {
		parts := strings.SplitN(v, "=", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("plugin requires both name and path")
		}
		out[parts[0]] = config.PluginConfig{Cmd: parts[1]}
	}
	return out, nil
}

