// Package parsers contains the parsers and serialisers for the various
// structured data formats that gomplate understands.
package parsers

import (
	"bytes"
	"encoding/csv"
	"fmt"
	"io"
	"strings"

	"github.com/BurntSushi/toml"
	"gopkg.in/yaml.v3"
)

// JSON - Unmarshal a JSON object
func JSON(in string) (map[string]interface{}, error) {
	obj := make(map[string]interface{})
	err := unmarshalObj(obj, in, yaml.Unmarshal)
	return obj, err
}

// JSONArray - Unmarshal a JSON array
func JSONArray(in string) ([]interface{}, error) {
	obj := make([]interface{}, 1)
	err := unmarshalArray(obj, in, yaml.Unmarshal)
	return obj, err
}

// YAML - Unmarshal a YAML object
func YAML(in string) (map[string]interface{}, error) {
	obj := make(map[string]interface{})
	err := yaml.Unmarshal([]byte(in), &obj)
	if err != nil {
		return nil, err
	}
	return stringifyMapKeys(obj).(map[string]interface{}), nil
}

// YAMLArray - Unmarshal a YAML array
func YAMLArray(in string) ([]interface{}, error) {
	obj := make([]interface{}, 1)
	err := yaml.Unmarshal([]byte(in), &obj)
	if err != nil {
		return nil, err
	}
	return stringifyMapKeys(obj).([]interface{}), nil
}

// TOML - Unmarshal a TOML object
func TOML(in string) (interface{}, error) {
	obj := make(map[string]interface{})
	err := unmarshalObj(obj, in, tomlUnmarshal)
	return obj, err
}

func tomlUnmarshal(data []byte, v interface{}) error {
	return toml.Unmarshal(data, v)
}

func unmarshalObj(obj map[string]interface{}, in string, f func([]byte, interface{}) error) error {
	err := f([]byte(in), &obj)
	if err != nil {
		return fmt.Errorf("unable to unmarshal object %s: %w", in, err)
	}
	// yaml.v3 may produce non-string keys for nested maps
	for k, v := range obj {
		obj[k] = stringifyMapKeys(v)
	}
	return nil
}

func unmarshalArray(obj []interface{}, in string, f func([]byte, interface{}) error) error {
	err := f([]byte(in), &obj)
	if err != nil {
		return fmt.Errorf("unable to unmarshal array %s: %w", in, err)
	}
	for i, v := range obj {
		obj[i] = stringifyMapKeys(v)
	}
	return nil
}

// stringifyMapKeys recursively converts map[interface{}]interface{} into
// map[string]interface{}, so that the data is usable in templates
func stringifyMapKeys(in interface{}) interface{} {
	switch in := in.(type) {
	case []interface{}:
		for i, v := range in {
			in[i] = stringifyMapKeys(v)
		}
		return in
	case map[string]interface{}:
		for k, v := range in {
			in[k] = stringifyMapKeys(v)
		}
		return in
	case map[interface{}]interface{}:
		res := make(map[string]interface{}, len(in))
		for k, v := range in {
			res[fmt.Sprintf("%v", k)] = stringifyMapKeys(v)
		}
		return res
	default:
		return in
	}
}

// CSV - parse CSV data. The delimiter may be given as an optional first
// argument.
func CSV(args ...string) ([][]string, error) {
	in, delim, err := parseCSVArgs(args...)
	if err != nil {
		return nil, err
	}
	c := csv.NewReader(strings.NewReader(in))
	c.Comma = rune(delim[0])
	return c.ReadAll()
}

// CSVByRow - parse CSV data into a list of maps keyed by header
func CSVByRow(args ...string) (rows []map[string]string, err error) {
	in, delim, hdr, err := parseCSVHeaderArgs(args...)
	if err != nil {
		return nil, err
	}
	c := csv.NewReader(strings.NewReader(in))
	c.Comma = rune(delim[0])
	records, err := c.ReadAll()
	if err != nil {
		return nil, err
	}
	if hdr == nil {
		if len(records) == 0 {
			return nil, nil
		}
		hdr = records[0]
		records = records[1:]
	}
	for _, record := range records {
		m := make(map[string]string)
		for i, v := range record {
			if i < len(hdr) {
				m[hdr[i]] = v
			}
		}
		rows = append(rows, m)
	}
	return rows, nil
}

// CSVByColumn - parse CSV data into a map of columns keyed by header
func CSVByColumn(args ...string) (cols map[string][]string, err error) {
	in, delim, hdr, err := parseCSVHeaderArgs(args...)
	if err != nil {
		return nil, err
	}
	c := csv.NewReader(strings.NewReader(in))
	c.Comma = rune(delim[0])
	records, err := c.ReadAll()
	if err != nil {
		return nil, err
	}
	if hdr == nil {
		if len(records) == 0 {
			return nil, nil
		}
		hdr = records[0]
		records = records[1:]
	}
	cols = make(map[string][]string)
	for _, record := range records {
		for i, v := range record {
			if i < len(hdr) {
				cols[hdr[i]] = append(cols[hdr[i]], v)
			}
		}
	}
	return cols, nil
}

func parseCSVArgs(args ...string) (in, delim string, err error) {
	delim = ","
	switch len(args) {
	case 1:
		in = args[0]
	case 2:
		delim = args[0]
		in = args[1]
	default:
		return "", "", fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}
	return in, delim, nil
}

func parseCSVHeaderArgs(args ...string) (in, delim string, hdr []string, err error) {
	delim = ","
	switch len(args) {
	case 1:
		in = args[0]
	case 2:
		if len(args[0]) == 1 {
			delim = args[0]
			in = args[1]
		} else if args[0] == "" {
			in = args[1]
		} else {
			hdr = strings.Split(args[0], ",")
			in = args[1]
		}
	case 3:
		delim = args[0]
		hdr = strings.Split(args[1], delim)
		in = args[2]
	default:
		return "", "", nil, fmt.Errorf("wrong number of args: wanted 1, 2, or 3, got %d", len(args))
	}
	return in, delim, hdr, nil
}

// ToCSV - serialise a 2-dimensional array to CSV
func ToCSV(args ...interface{}) (string, error) {
	delim := ","
	var in interface{}
	switch len(args) {
	case 1:
		in = args[0]
	case 2:
		d, ok := args[0].(string)
		if !ok {
			return "", fmt.Errorf("can't parse ToCSV delimiter (%v) - must be string (is a %T)", args[0], args[0])
		}
		delim = d
		in = args[1]
	default:
		return "", fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}

	records, err := toRecords(in)
	if err != nil {
		return "", err
	}

	b := &bytes.Buffer{}
	c := csv.NewWriter(b)
	c.Comma = rune(delim[0])
	// We output RFC4180 CSV, so force this to CRLF
	c.UseCRLF = true
	err = c.WriteAll(records)
	if err != nil {
		return "", err
	}
	return b.String(), nil
}

func toRecords(in interface{}) ([][]string, error) {
	switch v := in.(type) {
	case [][]string:
		return v, nil
	case [][]interface{}:
		out := make([][]string, len(v))
		for i, row := range v {
			out[i] = make([]string, len(row))
			for j, cell := range row {
				out[i][j] = fmt.Sprintf("%v", cell)
			}
		}
		return out, nil
	case []interface{}:
		out := make([][]string, len(v))
		for i, row := range v {
			switch r := row.(type) {
			case []string:
				out[i] = r
			case []interface{}:
				out[i] = make([]string, len(r))
				for j, cell := range r {
					out[i][j] = fmt.Sprintf("%v", cell)
				}
			default:
				return nil, fmt.Errorf("can't parse ToCSV input - must be a two-dimensional array (like [][]string or [][]any) (was %T)", in)
			}
		}
		return out, nil
	}
	return nil, fmt.Errorf("can't parse ToCSV input - must be a two-dimensional array (like [][]string or [][]any) (was %T)", in)
}

// ToYAML - serialise to YAML
func ToYAML(in interface{}) (string, error) {
	buf := &bytes.Buffer{}
	enc := yaml.NewEncoder(buf)
	enc.SetIndent(2)
	err := enc.Encode(in)
	if err != nil {
		return "", fmt.Errorf("unable to marshal %s: %w", in, err)
	}
	return buf.String(), nil
}

// ToTOML - serialise to TOML
func ToTOML(in interface{}) (string, error) {
	buf := &bytes.Buffer{}
	err := toml.NewEncoder(buf).Encode(in)
	if err != nil {
		return "", fmt.Errorf("unable to marshal %s: %w", in, err)
	}
	return buf.String(), nil
}

// DotEnv - parse a .env file
func DotEnv(in string) (map[string]interface{}, error) {
	env, err := parseDotEnv([]byte(in))
	if err != nil {
		return nil, err
	}
	out := make(map[string]interface{}, len(env))
	for k, v := range env {
		out[k] = v
	}
	return out, nil
}

