package parsers

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"sort"
	"strconv"
	"unicode/utf8"
)

// ToJSON - serialise to JSON
func ToJSON(in interface{}) (string, error) {
	buf := &bytes.Buffer{}
	err := marshalJSON(buf, in, "", "", false)
	if err != nil {
		return "", fmt.Errorf("unable to marshal JSON: %w", err)
	}
	return buf.String(), nil
}

// ToJSONPretty - serialise to indented JSON
func ToJSONPretty(indent string, in interface{}) (string, error) {
	buf := &bytes.Buffer{}
	err := marshalJSON(buf, in, "", indent, true)
	if err != nil {
		return "", fmt.Errorf("unable to marshal JSON: %w", err)
	}
	return buf.String(), nil
}

// marshalJSON writes a JSON encoding of v, with a few differences to the
// standard library's encoder: floats are always written with a fractional
// part (or exponent), and NaN/Inf are encoded as null.
func marshalJSON(buf *bytes.Buffer, v interface{}, prefix, indent string, pretty bool) error {
	if v == nil {
		buf.WriteString("null")
		return nil
	}
	switch t := v.(type) {
	case json.Marshaler:
		b, err := t.MarshalJSON()
		if err != nil {
			return err
		}
		return writeRaw(buf, b, prefix, indent, pretty)
	case string:
		writeJSONString(buf, t)
		return nil
	case bool:
		buf.WriteString(strconv.FormatBool(t))
		return nil
	case float64:
		writeFloat(buf, t, 64)
		return nil
	case float32:
		writeFloat(buf, float64(t), 32)
		return nil
	case int:
		buf.WriteString(strconv.FormatInt(int64(t), 10))
