// Datasource - read and parse a datasource
func (r *Reader) Datasource(ctx context.Context, alias string, args ...string) (interface{}, error) {
	s, err := r.lookup(alias)
	if err != nil {
		return nil, err
	}
	u, err := resolveURL(s.URL, args...)
	if err != nil {
		return nil, err
	}
	e, err := r.read(ctx, s, u)
	if err != nil {
		return nil, fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, stripTypeParam(u), err)
	}
	if e.hasParsed {
		return e.parsed, nil
	}
	v, err := parseData(e.mediaType, e.data)
	if err != nil {
		return nil, err
	}
	e.parsed = v
	e.hasParsed = true
	return v, nil
}

// Include - read a datasource as a string
func (r *Reader) Include(ctx context.Context, alias string, args ...string) (string, error) {
	s, err := r.lookup(alias)
	if err != nil {
		return "", err
	}
	u, err := resolveURL(s.URL, args...)
	if err != nil {
		return "", err
	}
	e, err := r.read(ctx, s, u)
	if err != nil {
		return "", fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, stripTypeParam(u), err)
	}
	return string(e.data), nil
}

// Reachable - whether the datasource can be read
func (r *Reader) Reachable(ctx context.Context, alias string, args ...string) bool {
	s, err := r.lookup(alias)
	if err != nil {
		return false
	}
	u, err := resolveURL(s.URL, args...)
	if err != nil {
		return false
	}
	_, err = r.read(ctx, s, u)
	return err == nil
}

// ReadRaw - read a URL directly (not through an alias)
func (r *Reader) ReadRaw(ctx context.Context, u *url.URL, hdr http.Header) ([]byte, string, error) {
	e, err := r.read(ctx, &Source{URL: u, Header: hdr}, u)
	if err != nil {
		return nil, "", err
	}
	return e.data, e.mediaType, nil
}

func resolveURL(base *url.URL, args ...string) (*url.URL, error) {
	if len(args) == 0 {
		return base, nil
	}
	if len(args) > 1 {
		return nil, fmt.Errorf("maximum two arguments to datasource function (%d given)", len(args)+1)
	}
	ref, err := url.Parse(args[0])
	if err != nil {
		return nil, err
	}
	if base.Opaque != "" {
		// opaque URIs can't really be resolved against
		u := *base
		return &u, nil
	}
	u := base.ResolveReference(ref)
	if ref.RawQuery == "" {
		u.RawQuery = base.RawQuery
	}
	return u, nil
}

func typeParamName() string {
	if v := os.Getenv("GOMPLATE_TYPE_PARAM"); v != "" {
		return v
	}
	return "type"
}

func stripTypeParam(u *url.URL) string {
	cp := *u
	q := cp.Query()
	if q.Has(typeParamName()) {
		q.Del(typeParamName())
		cp.RawQuery = q.Encode()
	}
	return cp.String()
}

// read - read the data for the given (resolved) URL, with caching
func (r *Reader) read(ctx context.Context, s *Source, u *url.URL) (*cacheEntry, error) {
	key := u.String()
	r.mu.Lock()
	if e, ok := r.cache[key]; ok {
		r.mu.Unlock()
		return e, e.err
	}
	r.mu.Unlock()

	data, mt, err := r.readURL(ctx, s, u)
	e := &cacheEntry{data: data, mediaType: mt, err: err}
	r.mu.Lock()
	r.cache[key] = e
	r.mu.Unlock()
	return e, err
}

func (r *Reader) readURL(ctx context.Context, s *Source, u *url.URL) ([]byte, string, error) {
	overrideType := u.Query().Get(typeParamName())

	var data []byte
	var mt string
	var err error

	switch u.Scheme {
	case "", "file":
		data, mt, err = r.readFile(u)
	case "env":
		data, mt, err = readEnv(u)
	case "stdin":
		data, mt, err = r.readStdin(u)
	case "http", "https":
		data, mt, err = r.readHTTP(ctx, s, u)
	case "merge":
		data, mt, err = r.readMerge(ctx, u)
	default:
		scheme := u.Scheme
		return nil, "", fmt.Errorf("fsys for path %s:///: filesystem provider for %q unavailable: no filesystem registered for scheme %q", scheme, scheme+":///", scheme)
	}
	if err != nil {
		return nil, "", err
	}
	if overrideType != "" {
		mt = overrideType
	}
	if mt == "" {
		mt = TextMimetype
	}
	return data, mt, nil
}

func mimeByExt(name string) string {
	ext := strings.ToLower(path.Ext(name))
	switch ext {
	case ".json":
		return JSONMimetype
	case ".yml", ".yaml":
		return YAMLMimetype
	case ".csv":
		return CSVMimetype
	case ".toml":
		return TOMLMimetype
	case ".env":
		return EnvMimetype
	case ".cue":
		return CUEMimetype
	case ".txt":
		return "text/plain; charset=utf-8"
	}
	return ""
}

// readFile - read from the local filesystem. Directories are listed.
func (r *Reader) readFile(u *url.URL) ([]byte, string, error) {
	name := u.Path
	baseURL := "/"
	var fullPath string
	if u.Scheme == "file" {
		baseURL = "file:///"
		fullPath = u.Path
	} else {
		cwd, err := os.Getwd()
		if err != nil {
			return nil, "", err
		}
		if u.Path == "" {
			name = "."
		}
		fullPath = filepath.Join(cwd, u.Path)
	}

	rel := strings.TrimPrefix(filepath.ToSlash(filepath.Clean(fullPath)), "/")
	if rel == "" {
		rel = "."
	}
	fsys := os.DirFS("/")

	f, err := fsys.Open(rel)
	if err != nil {
		return nil, "", fmt.Errorf("open (url: %q, name: %q): %w", baseURL, name, err)
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return nil, "", fmt.Errorf("stat (url: %q, name: %q): %w", baseURL, name, err)
	}
	if fi.IsDir() {
		entries, err := fs.ReadDir(fsys, rel)
		if err != nil {
			return nil, "", fmt.Errorf("readdir (url: %q, name: %q): %w", baseURL, name, err)
		}
		names := make([]interface{}, 0, len(entries))
		for _, e := range entries {
			names = append(names, e.Name())
		}
		out, err := parsers.ToJSON(names)
		if err != nil {
			return nil, "", err
		}
		return []byte(out), JSONArrayMimetype, nil
	}

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, "", fmt.Errorf("read (url: %q, name: %q): %w", baseURL, name, err)
	}
	return data, mimeByExt(name), nil
}

func readEnv(u *url.URL) ([]byte, string, error) {
	name := u.Opaque
	if name == "" {
		name = strings.TrimLeft(u.Path, "/")
	}
	v, ok := os.LookupEnv(name)
	if !ok {
		return nil, "", fmt.Errorf("stat (url: %q, name: %q): %w", "env:///", name, fs.ErrNotExist)
	}
	return []byte(v), mimeByExt(name), nil
}

func (r *Reader) readStdin(u *url.URL) ([]byte, string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if !r.stdinR {
		b, err := io.ReadAll(r.stdin)
		if err != nil {
			return nil, "", fmt.Errorf("read (url: %q, name: %q): %w", "stdin:///", strings.TrimLeft(u.Path, "/"), err)
		}
		r.stdinB = b
		r.stdinR = true
	}
	return r.stdinB, mimeByExt(u.Path), nil
}

func (r *Reader) readHTTP(ctx context.Context, s *Source, u *url.URL) ([]byte, string, error) {
	req := *u
	q := req.Query()
	q.Del(typeParamName())
	req.RawQuery = q.Encode()

	name := strings.TrimPrefix(req.Path, "/")
	if name == "" {
		name = "."
	}
	base := url.URL{Scheme: req.Scheme, Host: req.Host, Path: "/", RawQuery: req.RawQuery, User: req.User}

	// HEAD first, to check reachability (and get the content type)
	hreq, err := http.NewRequestWithContext(ctx, http.MethodHead, req.String(), nil)
	if err != nil {
		return nil, "", fmt.Errorf("stat (url: %q, name: %q): %w", base.String(), name, err)
	}
	for k, vs := range s.Header {
		for _, v := range vs {
			hreq.Header.Add(k, v)
		}
	}
	hresp, err := r.client.Do(hreq)
	if err != nil {
		return nil, "", fmt.Errorf("stat (url: %q, name: %q): %w", base.String(), name, err)
	}
	hresp.Body.Close()
	if hresp.StatusCode < 200 || hresp.StatusCode >= 300 {
		return nil, "", fmt.Errorf("stat (url: %q, name: %q): http HEAD failed with status %d", base.String(), name, hresp.StatusCode)
	}

	greq, err := http.NewRequestWithContext(ctx, http.MethodGet, req.String(), nil)
	if err != nil {
		return nil, "", fmt.Errorf("open (url: %q, name: %q): %w", base.String(), name, err)
	}
	for k, vs := range s.Header {
		for _, v := range vs {
			greq.Header.Add(k, v)
		}
	}
	resp, err := r.client.Do(greq)
	if err != nil {
		return nil, "", fmt.Errorf("open (url: %q, name: %q): %w", base.String(), name, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, "", fmt.Errorf("open (url: %q, name: %q): http GET failed with status %d", base.String(), name, resp.StatusCode)
	}
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, "", fmt.Errorf("read (url: %q, name: %q): %w", base.String(), name, err)
	}
	mt := resp.Header.Get("Content-Type")
	if mt == "" {
		mt = mimeByExt(req.Path)
	}
	return data, mt, nil
}

func (r *Reader) readMerge(ctx context.Context, u *url.URL) ([]byte, string, error) {
	p := u.Opaque
	baseURL := "merge:///"
	if p == "" {
		p = u.Path
		if strings.HasPrefix(p, "/") {
			baseURL = "merge:/"
			p = strings.TrimPrefix(p, "/")
		}
	}
	name := p
	if name == "" {
		name = "."
	}
	parts := strings.Split(p, "|")
	if p == "" || len(parts) < 2 {
		return nil, "", fmt.Errorf("open (url: %q, name: %q): open %s: need at least 2 datasources to merge", baseURL, name, name)
	}

	maps := make([]map[string]interface{}, len(parts))
	for i, part := range parts {
		var data []byte
		var mt string
		var err error
		if s, ok := r.getSource(part); ok {
			e, rerr := r.read(ctx, s, s.URL)
			if rerr != nil {
				return nil, "", fmt.Errorf("open (url: %q, name: %q): open %s: opening merge part %q: %w", baseURL, name, name, part, rerr)
			}
			data, mt = e.data, e.mediaType
		} else {
			pu, perr := urlhelpers.ParseSourceURL(part)
			if perr != nil {
				return nil, "", fmt.Errorf("open (url: %q, name: %q): open %s: opening merge part %q: %w", baseURL, name, name, part, perr)
			}
			e, rerr := r.read(ctx, &Source{URL: pu}, pu)
			if rerr != nil {
				return nil, "", fmt.Errorf("open (url: %q, name: %q): open %s: opening merge part %q: %w", baseURL, name, name, part, rerr)
			}
			data, mt = e.data, e.mediaType
			err = nil
		}
		_ = err
		v, perr := parseData(mt, data)
		if perr != nil {
			return nil, "", fmt.Errorf("stat (url: %q, name: %q): read: readSubFile: parsing map with content type %s: %w", baseURL, name, mt, perr)
		}
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil, "", fmt.Errorf("stat (url: %q, name: %q): read: readSubFile: parsing map with content type %s: unexpected data type '%T' for datasource (type %s); merge: can only merge maps", baseURL, name, mt, v, mt)
		}
		maps[i] = m
	}

	// merge right-to-left: the left-most values win
	merged := maps[len(maps)-1]
	for i := len(maps) - 2; i >= 0; i-- {
		merged = mergeMaps(maps[i], merged)
	}
	out, err := parsers.ToYAML(merged)
	if err != nil {
		return nil, "", err
	}
	return []byte(out), YAMLMimetype, nil
}

func (r *Reader) getSource(alias string) (*Source, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	s, ok := r.sources[alias]
	return s, ok
}

// mergeMaps - dst's values take precedence over src's. Nested maps are
// merged recursively.
func mergeMaps(dst, src map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(src))
	for k, v := range src {
		out[k] = v
	}
	for k, v := range dst {
		if existing, ok := out[k]; ok {
			dm, dok := v.(map[string]interface{})
			sm, sok := existing.(map[string]interface{})
			if dok && sok {
				out[k] = mergeMaps(dm, sm)
				continue
			}
		}
		out[k] = v
	}
	return out
}

// parseData - parse the data according to its media type
func parseData(mediaType string, data []byte) (interface{}, error) {
	mt, _, err := mime.ParseMediaType(mediaType)
	if err != nil {
		mt = mediaType
	}
	switch mt {
	case JSONMimetype:
		obj, err := parsers.JSON(string(data))
		if err != nil {
			arr, aerr := parsers.JSONArray(string(data))
			if aerr != nil {
				return nil, aerr
			}
			return arr, nil
		}
		return obj, nil
	case JSONArrayMimetype:
		return parsers.JSONArray(string(data))
	case YAMLMimetype, "application/x-yaml":
		obj, err := parsers.YAML(string(data))
		if err != nil {
			arr, aerr := parsers.YAMLArray(string(data))
			if aerr != nil {
				return nil, aerr
			}
			return arr, nil
		}
		return obj, nil
	case TOMLMimetype:
		return parsers.TOML(string(data))
	case CSVMimetype:
		return parsers.CSV(string(data))
	case EnvMimetype:
		return parsers.DotEnv(string(data))
	case TextMimetype:
		return string(data), nil
	}
	return nil, fmt.Errorf("data of type %q not yet supported", mediaType)
}

// ErrNotExist - exported for callers
var ErrNotExist = errors.New("file does not exist")
