package gomplate

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"text/template"

	"gomplate/internal/config"
	"gomplate/internal/ignore"
)

// Template - a template to be rendered, along with its destination
type Template struct {
	// Writer is the output destination
	Writer io.Writer
	// Name is the template's name (usually the input path)
	Name string
	// Text is the template source
	Text string
	// contents of the destination, if it is a plain copy (exclude-processing)
	copyOnly bool
}

// a template.Template with a known name
type tplate struct {
	Name     string
	Text     string
	Writer   io.Writer
	copyOnly bool
	// a parsed template
	t *template.Template
}

const stdinName = "-"
const argName = "<arg>"

// gatherTemplates - collect the input templates and set up their outputs
func gatherTemplates(ctx context.Context, cfg *config.Config, outFileNamer func(context.Context, string) (string, error)) ([]Template, error) {
	mode, modeOverride, err := cfg.GetMode()
	if err != nil {
		return nil, err
	}

	var templates []Template

	switch {
	case cfg.Input != "":
		templates = []Template{{
			Name: argName,
			Text: cfg.Input,
		}}
		if len(cfg.OutputFiles) == 0 {
			cfg.OutputFiles = []string{stdinName}
		}
		if mode == 0 {
			mode = 0o644
		}
		templates[0].Writer = openOutFile(cfg, cfg.OutputFiles[0], 0o755, mode, modeOverride)
	case cfg.InputDir != "":
		var err error
		templates, err = walkDir(ctx, cfg, cfg.InputDir, outFileNamer, cfg.ExcludeGlob, cfg.ExcludeProcessing, mode, modeOverride)
		if err != nil {
			return nil, err
		}
	case len(cfg.InputFiles) > 0:
		templates = make([]Template, len(cfg.InputFiles))
		for i, name := range cfg.InputFiles {
			t, fmode, err := fileToTemplate(cfg, name)
			if err != nil {
				return nil, err
			}
			if !modeOverride {
				mode = fmode
			}
			var out string
			if len(cfg.OutputFiles) > i {
				out = cfg.OutputFiles[i]
			} else {
				out = cfg.OutputFiles[len(cfg.OutputFiles)-1]
				if i > 0 {
					// mirror the original's behaviour of indexing past the end
					panic(fmt.Sprintf("runtime error: index out of range [%d] with length %d", i, len(cfg.OutputFiles)))
				}
			}
			t.Writer = openOutFile(cfg, out, 0o755, mode, modeOverride)
			templates[i] = t
		}
	}
	return templates, nil
}

// rootFS - a view of the filesystem rooted at "/", used so that error
// messages are consistent
func relToRoot(p string) string {
	abs := p
	if !filepath.IsAbs(abs) {
		cwd, err := os.Getwd()
		if err == nil {
			abs = filepath.Join(cwd, p)
		}
	}
	rel := strings.TrimPrefix(filepath.ToSlash(filepath.Clean(abs)), "/")
	if rel == "" {
		rel = "."
	}
	return rel
}

func fileToTemplate(cfg *config.Config, name string) (Template, os.FileMode, error) {
	var mode os.FileMode
	var text string

	if name == stdinName {
		b, err := io.ReadAll(cfg.Stdin)
		if err != nil {
			return Template{}, 0, fmt.Errorf("fileToTemplate: read stdin: %w", err)
		}
		text = string(b)
		mode = 0
	} else {
		fsys := os.DirFS("/")
		rel := relToRoot(name)
		fi, err := fs.Stat(fsys, rel)
		if err != nil {
			return Template{}, 0, fmt.Errorf("fileToTemplate: stat %q: %w", name, err)
		}
		mode = fi.Mode()
		b, err := fs.ReadFile(fsys, rel)
		if err != nil {
			return Template{}, 0, fmt.Errorf("fileToTemplate: read %q: %w", name, err)
		}
		text = string(b)
	}
	return Template{Name: name, Text: text}, mode, nil
}

// walkDir - process all the files in the input directory
func walkDir(ctx context.Context, cfg *config.Config, dir string, outFileNamer func(context.Context, string) (string, error), excludeGlob, excludeProcessing []string, mode os.FileMode, modeOverride bool) ([]Template, error) {
	dir = filepath.Clean(dir)

	dirStat, err := os.Stat(dir)
	if err != nil {
		return nil, fmt.Errorf("couldn't stat %s: %w", dir, err)
	}
	dirMode := dirStat.Mode()

	templates := make([]Template, 0)
	matcher := ignore.NewMatcher(excludeGlob)
	matcherProc := ignore.NewMatcher(excludeProcessing)

	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("couldn't read directory %s: %w", dir, err)
	}

	// .gomplateignore files in this directory
	ignoreFile := filepath.Join(dir, ".gomplateignore")
	if b, err := os.ReadFile(ignoreFile); err == nil {
		matcher = matcher.WithIgnoreFile(string(b), dir)
	}

	for _, entry := range entries {
		nextInPath := filepath.Join(dir, entry.Name())

		relPath := nextInPath
		if matcher.Match(relPath, entry.IsDir()) {
			continue
		}

		if entry.IsDir() {
			t, err := walkDirRecursive(ctx, cfg, nextInPath, outFileNamer, matcher, matcherProc, mode, modeOverride, dirMode)
			if err != nil {
				return nil, err
			}
			templates = append(templates, t...)
			continue
		}

		t, err := processFile(ctx, cfg, nextInPath, outFileNamer, matcherProc, mode, modeOverride, dirMode)
		if err != nil {
			return nil, err
		}
		templates = append(templates, t)
	}
	return templates, nil
}

func walkDirRecursive(ctx context.Context, cfg *config.Config, dir string, outFileNamer func(context.Context, string) (string, error), matcher *ignore.Matcher, matcherProc *ignore.Matcher, mode os.FileMode, modeOverride bool, dirMode os.FileMode) ([]Template, error) {
	templates := make([]Template, 0)

	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("couldn't read directory %s: %w", dir, err)
	}

	ignoreFile := filepath.Join(dir, ".gomplateignore")
	if b, err := os.ReadFile(ignoreFile); err == nil {
		matcher = matcher.WithIgnoreFile(string(b), dir)
	}

	for _, entry := range entries {
		nextInPath := filepath.Join(dir, entry.Name())
		if matcher.Match(nextInPath, entry.IsDir()) {
			continue
		}
		if entry.IsDir() {
			t, err := walkDirRecursive(ctx, cfg, nextInPath, outFileNamer, matcher, matcherProc, mode, modeOverride, dirMode)
			if err != nil {
				return nil, err
			}
			templates = append(templates, t...)
			continue
		}
		t, err := processFile(ctx, cfg, nextInPath, outFileNamer, matcherProc, mode, modeOverride, dirMode)
		if err != nil {
			return nil, err
		}
		templates = append(templates, t)
	}
	return templates, nil
}

func processFile(ctx context.Context, cfg *config.Config, inPath string, outFileNamer func(context.Context, string) (string, error), matcherProc *ignore.Matcher, mode os.FileMode, modeOverride bool, dirMode os.FileMode) (Template, error) {
	fi, err := os.Stat(inPath)
	if err != nil {
		return Template{}, fmt.Errorf("couldn't stat %s: %w", inPath, err)
	}
	if !modeOverride {
		mode = fi.Mode()
	}

	outPath, err := outFileNamer(ctx, inPath)
	if err != nil {
		return Template{}, err
	}

	b, err := os.ReadFile(inPath)
	if err != nil {
		return Template{}, fmt.Errorf("couldn't read %s: %w", inPath, err)
	}

	copyOnly := matcherProc.Match(inPath, false)

	return Template{
		Name:     inPath,
		Text:     string(b),
