	if dir != "" && dir != "." {
		if err := os.MkdirAll(dir, w.dirMode.Perm()); err != nil {
			return err
		}
	}
	f, err := os.OpenFile(w.filename, os.O_RDWR|os.O_CREATE|os.O_TRUNC, w.mode.Perm())
	if err != nil {
		return rewritePathError(err)
	}
