	base string
}

// Matcher - a list of patterns
type Matcher struct {
	patterns []*Pattern
	root     string
}

// NewMatcher - create a matcher with the given patterns, relative to the root
func NewMatcher(patterns []string) *Matcher {
	m := &Matcher{}
	for _, p := range patterns {
		if pat := compile(p, ""); pat != nil {
			m.patterns = append(m.patterns, pat)
		}
	}
	return m
}

// WithRoot - set the root directory that paths are relative to
func (m *Matcher) WithRoot(root string) *Matcher {
	m2 := *m
	m2.root = root
	return &m2
}

// WithIgnoreFile - returns a new matcher including the patterns in the given
// ignore file content, which are relative to dir. The ignore file patterns
// are evaluated before the matcher's existing patterns.
func (m *Matcher) WithIgnoreFile(content, dir string) *Matcher {
	rel, err := filepath.Rel(m.root, dir)
	if err != nil {
		rel = dir
	}
	rel = filepath.ToSlash(rel)
	if rel == "." {
		rel = ""
	}
	var pats []*Pattern
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimRight(line, "\r")
		if pat := compile(line, rel); pat != nil {
			pats = append(pats, pat)
		}
	}
	m2 := &Matcher{root: m.root}
	// existing file-derived patterns first (parents), then this file's, then
	// the command-line patterns (which have an empty base and were added
	// at construction time)
	var cli, files []*Pattern
	for _, p := range m.patterns {
		if p.fromFile {
			files = append(files, p)
		} else {
			cli = append(cli, p)
		}
	}
	for _, p := range pats {
		p.fromFile = true
	}
	m2.patterns = append(append(files, pats...), cli...)
	return m2
}

// Match - whether the path (relative to the root) is ignored. Non-negated
// patterns match the path itself or any of its parent directories; negated
// patterns only match the path itself.
func (m *Matcher) Match(p string, isDir bool) bool {
	p = filepath.ToSlash(p)
	if m.root != "" {
		rel, err := filepath.Rel(m.root, p)
		if err == nil {
			p = filepath.ToSlash(rel)
		}
	}
	if p == "." || p == "" {
		return false
	}

	parents := parentPaths(p)
	matched := false
	for _, pat := range m.patterns {
		sub := p
		subParents := parents
		if pat.base != "" {
			if !strings.HasPrefix(p, pat.base+"/") {
				continue
			}
			sub = strings.TrimPrefix(p, pat.base+"/")
			subParents = parentPaths(sub)
		}
		if pat.negate {
			if pat.re.MatchString(sub) {
				matched = false
			}
			continue
		}
		if pat.re.MatchString(sub) {
			matched = true
			continue
		}
		for _, parent := range subParents {
			if pat.re.MatchString(parent) {
				matched = true
				break
			}
		}
	}
	return matched
}

func parentPaths(p string) []string {
	parts := strings.Split(p, "/")
	out := make([]string, 0, len(parts)-1)
	for i := 1; i < len(parts); i++ {
		out = append(out, strings.Join(parts[:i], "/"))
	}
	return out
}

// compile a gitignore-style pattern into a regular expression
func compile(value, base string) *Pattern {
	if value == "" || strings.HasPrefix(value, "#") {
		return nil
	}
	p := &Pattern{value: value, base: base}
	pattern := value
	if strings.HasPrefix(pattern, "!") {
		p.negate = true
		pattern = pattern[1:]
	}
	if pattern == "" {
		return nil
	}
	anchored := false
	if strings.HasPrefix(pattern, "/") {
		anchored = true
		pattern = strings.TrimLeft(pattern, "/")
	}
	if pattern == "" {
		return nil
	}

	regStr := "^"
	if !anchored && !strings.Contains(pattern, "/") {
		regStr += "(.*/)?"
	}

	var scan scanner.Scanner
	scan.Init(strings.NewReader(pattern))
	for scan.Peek() != scanner.EOF {
		ch := scan.Next()
		switch {
		case ch == '*':
			if scan.Peek() == '*' {
				scan.Next()
				// treat **/ as **
				if scan.Peek() == '/' {
					scan.Next()
				}
				if scan.Peek() == scanner.EOF {
					regStr += ".*"
				} else {
					regStr += "(.*/)?"
				}
			} else {
				regStr += "[^/]*"
			}
		case ch == '?':
			regStr += "[^/]"
		case ch == '.' || ch == '$' || ch == '(' || ch == ')' || ch == '+' || ch == '|' || ch == '{' || ch == '}' || ch == '^':
			regStr += `\` + string(ch)
		case ch == '\\':
			if scan.Peek() != scanner.EOF {
				regStr += regexp.QuoteMeta(string(scan.Next()))
			} else {
				regStr += `\\`
			}
		default:
			regStr += string(ch)
		}
	}
	regStr += "$"

	re, err := regexp.Compile(regStr)
	if err != nil {
		return nil
	}
	p.re = re
	return p
}
