func newRenderer(ctx context.Context, cfg *config.Config, metrics *Metrics) (*Renderer, error) {
	sr := datafs.NewReader(cfg.Stdin)
	for alias, ds := range cfg.DataSources {
		sr.Register(alias, ds.URL, ds.Header)
	}
	for alias, ds := range cfg.Context {
		sr.Register(alias, ds.URL, ds.Header)
	}

