func (r *Renderer) outFileNamer(cfg *config.Config) func(context.Context, string) (string, error) {
	inputDir := filepath.Clean(cfg.InputDir)
	if cfg.OutputMap == "" {
		outputDir := cfg.OutputDir
		return func(_ context.Context, inPath string) (string, error) {
