	}
}

// renderTemplates - render all the templates
func (r *Renderer) renderTemplates(ctx context.Context, templates []Template) error {
	for _, template := range templates {
		if template.copyOnly {
			_, err := io.WriteString(template.Writer, template.Text)
			if err != nil {
				return err
			}
			r.metrics.TemplatesProcessed++
			continue
		}
		t := &tplate{Name: template.Name, Text: template.Text, Writer: template.Writer}
		err := r.renderTemplate(ctx, t, r.ctx)
		if err != nil {
			r.metrics.Errors++
			return err
		}
		r.metrics.TemplatesProcessed++
	}
	for _, template := range templates {
		if c, ok := template.Writer.(io.Closer); ok {
			if err := c.Close(); err != nil {
				return err
			}
		}
	}
	return nil
}

func (r *Renderer) renderTemplate(ctx context.Context, t *tplate, tctx interface{}) error {
	tmpl, err := r.parseTemplate(ctx, t.Name, t.Text)
	if err != nil {
		return fmt.Errorf("renderTemplate: parse template %s: %w", t.Name, err)
	}
	t.t = tmpl

	err = tmpl.Execute(t.Writer, tctx)
	if err != nil {
		return fmt.Errorf("renderTemplate: failed to render template %s: %w", t.Name, err)
	}
	r.metrics.TemplatesProcessed += 0
	return nil
}

// parseTemplate - parse the main template and all nested templates
func (r *Renderer) parseTemplate(ctx context.Context, name, text string) (*template.Template, error) {
	tmpl := template.New(name)
	tmpl.Option("missingkey=" + r.missing)
