	"gomplate/internal/config"
)

// parseNestedTemplates - parse all the nested templates (from --template)
// into the given template set
func (r *Renderer) parseNestedTemplates(ctx context.Context, tmpl *template.Template) error {
	aliases := make([]string, 0, len(r.nested))
	for a := range r.nested {
		aliases = append(aliases, a)
	}
	sort.Strings(aliases)

	for _, alias := range aliases {
		ds := r.nested[alias]
		if err := r.parseNestedTemplate(ctx, tmpl, alias, ds); err != nil {
			return err
		}
	}
	return nil
}

func (r *Renderer) parseNestedTemplate(ctx context.Context, tmpl *template.Template, alias string, ds config.DataSource) error {
	u := ds.URL
	if u == nil {
		return fmt.Errorf("stat %q: %w", ".", fs.ErrNotExist)
	}

	switch u.Scheme {
	case "", "file":
		return r.parseFileTemplates(tmpl, alias, u)
	default:
		data, _, err := r.data.ReadRaw(ctx, u, ds.Header)
		if err != nil {
			name := strings.TrimPrefix(u.Path, "/")
			if name == "" {
				name = "."
			}
			// unwrap the "stat (url: ..., name: ...)" prefix to the short form
			msg := err.Error()
			if idx := strings.Index(msg, "): "); idx >= 0 && (strings.HasPrefix(msg, "stat (") || strings.HasPrefix(msg, "open (")) {
				return fmt.Errorf("stat %q: %s", name, msg[idx+3:])
			}
			return fmt.Errorf("stat %q: %w", name, err)
		}
		_, err = tmpl.New(alias).Parse(string(data))
		if err != nil {
			return fmt.Errorf("parse nested template %q: %w", path.Base(name(u)), err)
		}
		return nil
	}
}

func name(u *url.URL) string {
	if u.Opaque != "" {
		return u.Opaque
	}
	return u.Path
}

func (r *Renderer) parseFileTemplates(tmpl *template.Template, alias string, u *url.URL) error {
	p := u.Path
	if p == "" {
		p = "."
	}
	fullPath := p
	if !filepath.IsAbs(fullPath) {
		cwd, err := os.Getwd()
		if err != nil {
			return err
		}
		fullPath = filepath.Join(cwd, p)
	}

	// the filesystem is rooted at the parent directory, so that error
	// messages only mention the base name
	dir, base := filepath.Split(filepath.Clean(fullPath))
	if strings.HasSuffix(p, "/") || base == "" {
		dir = filepath.Clean(fullPath)
		base = "."
	}
	fsys := os.DirFS(dir)

	fi, err := fs.Stat(fsys, base)
	if err != nil {
		return fmt.Errorf("stat %q: %w", base, err)
	}

	if fi.IsDir() {
		return r.parseDirTemplates(tmpl, alias, fsys, base, "")
	}

	b, err := fs.ReadFile(fsys, base)
	if err != nil {
		return fmt.Errorf("read %q: %w", base, err)
	}
	_, err = tmpl.New(alias).Parse(string(b))
	if err != nil {
		return fmt.Errorf("parse nested template %q: %w", base, err)
	}
	return nil
}

func (r *Renderer) parseDirTemplates(tmpl *template.Template, alias string, fsys fs.FS, dir, prefix string) error {
	entries, err := fs.ReadDir(fsys, dir)
	if err != nil {
		return fmt.Errorf("readdir %q: %w", dir, err)
	}
	for _, e := range entries {
		rel := e.Name()
		if prefix != "" {
			rel = prefix + "/" + e.Name()
		}
		full := path.Join(dir, e.Name())
		if e.IsDir() {
			if err := r.parseDirTemplates(tmpl, alias, fsys, full, rel); err != nil {
				return err
			}
			continue
		}
		b, err := fs.ReadFile(fsys, full)
		if err != nil {
			return fmt.Errorf("read %q: %w", rel, err)
		}
		tname := alias + "/" + rel
		if strings.HasSuffix(alias, "/") {
			tname = alias + rel
		}
		_, err = tmpl.New(tname).Parse(string(b))
		if err != nil {
			return fmt.Errorf("parse nested template %q: %w", rel, err)
		}
	}
	return nil
}
