// CreateStringFuncs -
func CreateStringFuncs(ctx context.Context) template.FuncMap {
	ns := &StringFuncs{ctx: ctx}
	return template.FuncMap{
		"strings":    func() interface{} { return ns },
		"replaceAll": ns.ReplaceAll,
		"title":      ns.Title,
		"toUpper":    ns.ToUpper,
		"toLower":    ns.ToLower,
		"trimSpace":  ns.TrimSpace,
		"indent":     ns.Indent,
		"quote":      ns.Quote,
		"shellQuote": ns.ShellQuote,
		"squote":     ns.Squote,
	}
}

// StringFuncs -
type StringFuncs struct {
	ctx context.Context
}

// Abbrev -
func (StringFuncs) Abbrev(args ...interface{}) (string, error) {
	str := ""
	offset := 0
	maxWidth := 0
	var err error
	if len(args) < 2 {
		return "", fmt.Errorf("abbrev requires a 'width' and 'input' argument")
	}
	if len(args) == 2 {
		maxWidth, err = conv.ToInt(args[0])
		if err != nil {
			return "", err
		}
		str = conv.ToString(args[1])
	}
	if len(args) == 3 {
		offset, err = conv.ToInt(args[0])
		if err != nil {
			return "", err
		}
		maxWidth, err = conv.ToInt(args[1])
		if err != nil {
			return "", err
		}
		str = conv.ToString(args[2])
	}
	if len(args) > 3 {
		return "", fmt.Errorf("abbrev requires a 'width' and 'input' argument")
	}
	if len(str) <= maxWidth {
		return str, nil
	}
	return abbreviateFull(str, offset, maxWidth)
}

func abbreviateFull(str string, offset, maxWidth int) (string, error) {
	if str == "" {
		return "", nil
	}
	if maxWidth < 4 {
		return "", fmt.Errorf("stringutils illegal argument: Minimum abbreviation width is 4")
	}
	if len(str) <= maxWidth {
		return str, nil
	}
	if offset > len(str) {
		offset = len(str)
	}
	if len(str)-offset < (maxWidth - 3) {
		offset = len(str) - (maxWidth - 3)
	}
	abrevMarker := "..."
	if offset <= 4 {
		return str[0:maxWidth-3] + abrevMarker, nil
	}
	if maxWidth < 7 {
		return "", fmt.Errorf("stringutils illegal argument: Minimum abbreviation width with offset is 7")
	}
	if (offset + maxWidth - 3) < len(str) {
		abrevStr, _ := abbreviateFull(str[offset:], 0, maxWidth-3)
		return abrevMarker + abrevStr, nil
	}
	return abrevMarker + str[(len(str)-(maxWidth-3)):], nil
}

// ReplaceAll -
func (StringFuncs) ReplaceAll(old, new string, s interface{}) string {
	return strings.ReplaceAll(conv.ToString(s), old, new)
}

// Contains -
func (StringFuncs) Contains(substr string, s interface{}) bool {
	return strings.Contains(conv.ToString(s), substr)
}

// HasPrefix -
func (StringFuncs) HasPrefix(prefix string, s interface{}) bool {
	return strings.HasPrefix(conv.ToString(s), prefix)
