		end := wl + offset + 1
		spaceToWrapAt := strings.LastIndex(str[offset:end], " ") + offset
		if spaceToWrapAt >= offset {
			out.WriteString(str[offset:spaceToWrapAt])
			out.WriteString(newLineStr)
			offset = spaceToWrapAt + 1
		} else {
			// long word: extend beyond the limit, up to the next space
			index := strings.IndexRune(str[offset:], ' ')
			if index == -1 {
				out.WriteString(str[offset:])
				offset = inputLineLength
			} else {
				spaceToWrapAt = index + offset
				out.WriteString(str[offset:spaceToWrapAt])
				out.WriteString(newLineStr)
				offset = spaceToWrapAt + 1
			}
		}
	}
	out.WriteString(str[offset:])
	return out.String()
}

