			fn, err := conv.ToFloat64(n)
			if err != nil {
				return nil, fmt.Errorf("expected a number: %w", err)
			}
			m = gmath.Min(m, fn)
		}
		return m, nil
	}
	m, err := conv.ToInt64(a)
	if err != nil {
		return nil, fmt.Errorf("expected a number: %w", err)
	}
	for _, n := range b {
		in, err := conv.ToInt64(n)
		if err != nil {
			return nil, fmt.Errorf("expected a number: %w", err)
		}
		if in < m {
			m = in
		}
	}
	return m, nil
}

// Ceil -
func (f MathFuncs) Ceil(n interface{}) (float64, error) {
	fn, err := conv.ToFloat64(n)
	if err != nil {
		return 0, fmt.Errorf("n must be a number: %w", err)
	}
	return gmath.Ceil(fn), nil
}

// Floor -
func (f MathFuncs) Floor(n interface{}) (float64, error) {
	fn, err := conv.ToFloat64(n)
	if err != nil {
		return 0, fmt.Errorf("n must be a number: %w", err)
