		if err != nil {
			return nil, fmt.Errorf("expected a number: %w", err)
		}
		if in > m {
			m = in
		}
	}
	return m, nil
}

// Min -
func (f MathFuncs) Min(a interface{}, b ...interface{}) (interface{}, error) {
	if f.containsFloat(a) || f.containsFloat(b...) {
