{"command":"cd /workspace && cat > internal/funcs/coll.go <<'EOF'
package funcs

import (
	"context"
	"fmt"
	"reflect"
	"sort"
	"strings"
	"text/template"

	"gomplate/internal/conv"
)

// CreateCollFuncs -
func CreateCollFuncs(ctx context.Context) template.FuncMap {
	ns := &CollFuncs{ctx: ctx}
	return template.FuncMap{
		"coll":     func() interface{} { return ns },
		"has":      ns.Has,
		"dict":     ns.Dict,
		"keys":     ns.Keys,
		"values":   ns.Values,
		"append":   ns.Append,
		"prepend":  ns.Prepend,
		"uniq":     ns.Uniq,
		"reverse":  ns.Reverse,
		"merge":    ns.Merge,
		"sort":     ns.Sort,
		"jsonpath": ns.JSONPath,
		"jq":       ns.JQ,
		"flatten":  ns.Flatten,
		"set":      ns.Set,
		"unset":    ns.Unset,
	}
}

// CollFuncs -
type CollFuncs struct {
	ctx context.Context
}

// Slice -
func (CollFuncs) Slice(args ...interface{}) []interface{} {
	return args
}

// GoSlice - same as the built-in slice function
func (CollFuncs) GoSlice(item reflect.Value, indexes ...reflect.Value) (reflect.Value, error) {
	return goSlice(item, indexes...)
}

// Has -
func (CollFuncs) Has(in interface{}, key string) bool {
	av := reflect.ValueOf(in)
	switch av.Kind() {
	case reflect.Map:
		kv := reflect.ValueOf(key)
		return av.MapIndex(kv).IsValid()
	case reflect.Slice, reflect.Array:
		l := av.Len()
		for i := 0; i < l; i++ {
			v := av.Index(i).Interface()
			if v == key {
				return true
			}
		}
	}
	return false
}

// Dict -
func (CollFuncs) Dict(v ...interface{}) (map[string]interface{}, error) {
	dict := map[string]interface{}{}
	lenv := len(v)
	for i := 0; i < lenv; i += 2 {
		key := conv.ToString(v[i])
		if i+1 >= lenv {
			dict[key] = ""
			continue
		}
		dict[key] = v[i+1]
	}
	return dict, nil
}

// Keys -
func (CollFuncs) Keys(in ...map[string]interface{}) ([]string, error) {
	if len(in) == 0 {
		return nil, fmt.Errorf("need at least one argument")
	}
	keys := []string{}
	for _, m := range in {
		k := make([]string, 0, len(m))
		for key := range m {
			k = append(k, key)
		}
		sort.Strings(k)
		keys = append(keys, k...)
	}
	return keys, nil
}

// Values -
func (CollFuncs) Values(in ...map[string]interface{}) ([]interface{}, error) {
	if len(in) == 0 {
		return nil, fmt.Errorf("need at least one argument")
	}
	values := []interface{}{}
	for _, m := range in {
		k := make([]string, 0, len(m))
		for key := range m {
			k = append(k, key)
		}
		sort.Strings(k)
		for _, key := range k {
			values = append(values, m[key])
		}
	}
	return values, nil
}

// Append -
func (CollFuncs) Append(v interface{}, list interface{}) ([]interface{}, error) {
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	return append(l, v), nil
}

// Prepend -
func (CollFuncs) Prepend(v interface{}, list interface{}) ([]interface{}, error) {
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	return append([]interface{}{v}, l...), nil
}

// Uniq -
func (CollFuncs) Uniq(list interface{}) ([]interface{}, error) {
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, v := range l {
		if !containsValue(out, v) {
			out = append(out, v)
		}
	}
	return out, nil
}

func containsValue(list []interface{}, v interface{}) bool {
	for _, item := range list {
		if reflect.DeepEqual(item, v) {
			return true
		}
	}
	return false
}

// Reverse -
func (CollFuncs) Reverse(list interface{}) ([]interface{}, error) {
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, len(l))
	for i, v := range l {
		out[len(l)-1-i] = v
	}
	return out, nil
}

// Merge -
func (CollFuncs) Merge(dst map[string]interface{}, src ...map[string]interface{}) (map[string]interface{}, error) {
	for _, s := range src {
		dst = mergeMaps(dst, s)
	}
	return dst, nil
}

// mergeMaps - dst's values take precedence
func mergeMaps(dst, src map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(src))
	for k, v := range src {
		out[k] = v
	}
	for k, v := range dst {
		if existing, ok := out[k]; ok {
			dm, dok := v.(map[string]interface{})
			sm, sok := existing.(map[string]interface{})
			if dok && sok {
				out[k] = mergeMaps(dm, sm)
				continue
			}
		}
		out[k] = v
	}
	return out
}

// Sort -
func (f CollFuncs) Sort(args ...interface{}) (interface{}, error) {
	var (
		key  string
		list interface{}
	)
	if len(args) == 0 || len(args) > 2 {
		return nil, fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}
	if len(args) == 1 {
		list = args[0]
	}
	if len(args) == 2 {
		k, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("wrong type for key; expected string, got %T", args[0])
		}
		key = k
		list = args[1]
	}
	return sortList(key, list)
}

func sortList(key string, list interface{}) (interface{}, error) {
	switch l := list.(type) {
	case []string:
		out := make([]string, len(l))
		copy(out, l)
		sort.Strings(out)
		return out, nil
	case []int64:
		out := make([]int64, len(l))
		copy(out, l)
		sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
		return out, nil
	case []int:
		out := make([]int, len(l))
		copy(out, l)
		sort.Ints(out)
		return out, nil
	case []float64:
		out := make([]float64, len(l))
		copy(out, l)
		sort.Float64s(out)
		return out, nil
	}
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, len(l))
	copy(out, l)
	if len(out) == 0 {
		return out, nil
	}

	if key != "" {
		// sort maps by key
		sort.SliceStable(out, func(i, j int) bool {
			mi, iok := out[i].(map[string]interface{})
			mj, jok := out[j].(map[string]interface{})
			if !iok || !jok {
				return false
			}
			return lessValue(mi[key], mj[key])
		})
		return out, nil
	}

	// all elements must be the same type
	t := reflect.TypeOf(out[0])
	if t == nil {
		return nil, fmt.Errorf("runtime error: invalid memory address or nil pointer dereference")
	}
	for _, v := range out {
		if reflect.TypeOf(v) != t {
			return out, nil
		}
	}
	switch t.Kind() {
	case reflect.String, reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		sort.SliceStable(out, func(i, j int) bool {
			return lessValue(out[i], out[j])
		})
	}
	return out, nil
}

func lessValue(a, b interface{}) bool {
	av, bv := reflect.ValueOf(a), reflect.ValueOf(b)
	if !av.IsValid() || !bv.IsValid() {
		return false
	}
	if av.Kind() != bv.Kind() {
		return conv.ToString(a) < conv.ToString(b)
	}
	switch av.Kind() {
	case reflect.String:
		return av.String() < bv.String()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return av.Int() < bv.Int()
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return av.Uint() < bv.Uint()
	case reflect.Float32, reflect.Float64:
		return av.Float() < bv.Float()
	}
	return false
}

// Flatten -
func (f CollFuncs) Flatten(args ...interface{}) ([]interface{}, error) {
	if len(args) == 0 || len(args) > 2 {
		return nil, fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}
	list := args[0]
	depth := -1
	if len(args) == 2 {
		d, err := conv.ToInt(args[0])
		if err != nil {
			return nil, err
		}
		depth = d
		list = args[1]
	}
	return flatten(list, depth)
}

func flatten(list interface{}, depth int) ([]interface{}, error) {
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, v := range l {
		if depth == 0 {
			out = append(out, v)
			continue
		}
		rv := reflect.ValueOf(v)
		if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
			sub, err := flatten(v, depth-1)
			if err != nil {
				return nil, err
			}
			out = append(out, sub...)
		} else {
			out = append(out, v)
		}
	}
	return out, nil
}

// Pick -
func (CollFuncs) Pick(args ...interface{}) (map[string]interface{}, error) {
	if len(args) <= 1 {
		return nil, fmt.Errorf("wrong number of args: wanted 2 or more, got %d", len(args))
	}
	m, ok := args[len(args)-1].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("wrong map type: must be map[string]any, got %T", args[len(args)-1])
	}
	out := map[string]interface{}{}
	for _, k := range args[:len(args)-1] {
		key, ok := k.(string)
		if !ok {
			return nil, fmt.Errorf("wrong key type: must be string, got %T", k)
		}
		if v, ok := m[key]; ok {
			out[key] = v
		}
	}
	return out, nil
}

// Omit -
func (CollFuncs) Omit(args ...interface{}) (map[string]interface{}, error) {
	if len(args) <= 1 {
		return nil, fmt.Errorf("wrong number of args: wanted 2 or more, got %d", len(args))
	}
	m, ok := args[len(args)-1].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("wrong map type: must be map[string]any, got %T", args[len(args)-1])
	}
	omit := map[string]bool{}
	for _, k := range args[:len(args)-1] {
		key, ok := k.(string)
		if !ok {
			return nil, fmt.Errorf("wrong key type: must be string, got %T", k)
		}
		omit[key] = true
	}
	out := map[string]interface{}{}
	for k, v := range m {
		if !omit[k] {
			out[k] = v
		}
	}
	return out, nil
}

// Set -
func (CollFuncs) Set(key string, value interface{}, m map[string]interface{}) (map[string]interface{}, error) {
	if m == nil {
		m = map[string]interface{}{}
	}
	m[key] = value
	return m, nil
}

// Unset -
func (CollFuncs) Unset(key string, m map[string]interface{}) (map[string]interface{}, error) {
	delete(m, key)
	return m, nil
}

// Index - strict indexing
func (CollFuncs) Index(args ...interface{}) (interface{}, error) {
