				v = x
			} else {
				return nil, fmt.Errorf("map has no key %v", index.Interface())
			}
		case reflect.Invalid:
			panic("unreachable")
		default:
			return nil, fmt.Errorf("can't index item of type %s", v.Type())
		}
	}
