// Has -
func (CollFuncs) Has(in interface{}, key string) bool {
	av := reflect.ValueOf(in)
	switch av.Kind() {
	case reflect.Map:
		kv := reflect.ValueOf(key)
		return av.MapIndex(kv).IsValid()
	case reflect.Slice, reflect.Array:
		l := av.Len()
		for i := 0; i < l; i++ {
			v := av.Index(i).Interface()
			if v == key {
