func (f CollFuncs) Sort(args ...interface{}) (interface{}, error) {
	var (
		key  string
		list interface{}
	)
	if len(args) == 0 || len(args) > 2 {
		return nil, fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}
	if len(args) == 1 {
		list = args[0]
	}
	if len(args) == 2 {
		k, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("wrong type for key; expected string, got %T", args[0])
