	case []int:
		out := make([]int, len(l))
		copy(out, l)
		sort.Ints(out)
		return out, nil
	case []float64:
		out := make([]float64, len(l))
		copy(out, l)
		sort.Float64s(out)
		return out, nil
	}
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, len(l))
	copy(out, l)
	if len(out) == 0 {
		return out, nil
	}

	if key != "" {
		// sort maps by key
		sort.SliceStable(out, func(i, j int) bool {
			mi, iok := out[i].(map[string]interface{})
			mj, jok := out[j].(map[string]interface{})
			if !iok || !jok {
				return false
			}
			return lessValue(mi[key], mj[key])
		})
