package funcs

import (
	"context"
	"os"
	"strings"
	"text/template"

	"gomplate/internal/conv"
)

// CreateEnvFuncs -
func CreateEnvFuncs(ctx context.Context) template.FuncMap {
	ns := &EnvFuncs{ctx: ctx}
	return template.FuncMap{
		"env":    func() interface{} { return ns },
		"getenv": ns.Getenv,
	}
}

// EnvFuncs -
type EnvFuncs struct {
	ctx context.Context
}

// Getenv -
func (EnvFuncs) Getenv(key interface{}, def ...string) string {
	return getenv(conv.ToString(key), def...)
}

// ExpandEnv -
func (EnvFuncs) ExpandEnv(s interface{}) string {
	return os.ExpandEnv(conv.ToString(s))
}

// Env - all environment variables
func (EnvFuncs) Env() map[string]string {
	env := map[string]string{}
	for _, i := range os.Environ() {
		sep := strings.Index(i, "=")
		env[i[0:sep]] = i[sep+1:]
	}
	return env
}

// HasEnv -
func (EnvFuncs) HasEnv(key interface{}) bool {
	_, ok := lookupEnv(conv.ToString(key))
	return ok
}

// getenv - like os.Getenv, but with support for _FILE suffixed variables, and
// default values
func getenv(key string, def ...string) string {
	val, ok := lookupEnv(key)
	if !ok || val == "" {
		if len(def) > 0 {
			return def[0]
		}
	}
	return val
}

func lookupEnv(key string) (string, bool) {
	val, ok := os.LookupEnv(key)
	if ok && val != "" {
		return val, true
	}
	p, ok := os.LookupEnv(key + "_FILE")
	if ok && p != "" {
		fi, err := os.Stat(p)
		if err != nil || fi.IsDir() {
			return "", false
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return "", false
		}
		return strings.TrimSpace(string(b)), true
	}
	return val, ok && val != ""
}
