	return template.FuncMap{
		"test":     func() interface{} { return ns },
		"assert":   ns.Assert,
		"fail":     ns.Fail,
		"required": ns.Required,
		"ternary":  ns.Ternary,
		"kind":     ns.Kind,
		"isKind":   ns.IsKind,
	}
}

// TestFuncs -
type TestFuncs struct {
	ctx context.Context
}

// Assert -
func (TestFuncs) Assert(args ...interface{}) (string, error) {
	input := conv.ToBool(args[len(args)-1])
	switch len(args) {
	case 1:
		if !input {
			return "", errors.New("assertion failed")
		}
		return "", nil
	case 2:
		message, ok := args[0].(string)
		if !ok {
			return "", fmt.Errorf("at <1>: expected string; found %T", args[0])
		}
		if !input {
			return "", fmt.Errorf("assertion failed: %s", message)
		}
		return "", nil
	default:
		return "", fmt.Errorf("wrong number of args: want 1 or 2, got %d", len(args))
	}
}

// Fail -
func (TestFuncs) Fail(args ...interface{}) (string, error) {
	switch len(args) {
	case 0:
		return "", errors.New("template generation failed")
	case 1:
		return "", fmt.Errorf("template generation failed: %s", conv.ToString(args[0]))
	default:
		return "", fmt.Errorf("wrong number of args: want 0 or 1, got %d", len(args))
	}
}

// Required -
func (TestFuncs) Required(args ...interface{}) (interface{}, error) {
	if len(args) == 0 || len(args) > 2 {
		return nil, fmt.Errorf("wrong number of args: want 1 or 2, got %d", len(args))
	}

	message := "can not render template: a required value was not set"
	val := args[0]
	if len(args) == 2 {
		m, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("at <1>: expected string; found %T", args[0])
		}
		if m != "" {
			message = m
		}
		val = args[1]
	}

	if val == nil {
		return nil, errors.New(message)
	}
	if s, ok := val.(string); ok && s == "" {
		return nil, errors.New(message)
	}
	return val, nil
}

// Ternary -
func (TestFuncs) Ternary(tval, fval, b interface{}) interface{} {
	if conv.ToBool(b) {
		return tval
	}
	return fval
}

