// parseNum - parses a number (or a numeric string) into seconds and
// nanoseconds. Strings may contain a fractional part.
func parseNum(in interface{}) (integer, fraction int64, err error) {
	if s, ok := in.(string); ok {
		ss := strings.Split(s, ".")
		if len(ss) > 2 {
			return 0, 0, fmt.Errorf("can not parse '%s' as a number - too many decimal points", s)
		}
		if len(ss) == 1 {
			integer, err = strconv.ParseInt(s, 0, 64)
			return integer, 0, err
		}
		integer, err = strconv.ParseInt(ss[0], 0, 64)
		if err != nil {
			return integer, 0, err
		}
		fraction, err = strconv.ParseInt(padRight(ss[1], "0", 9), 0, 64)
		return integer, fraction, err
	}
	if s, ok := in.(fmt.Stringer); ok {
		return parseNum(s.String())
	}
	if i, ok := in.(int); ok {
		return int64(i), 0, nil
	}
	if u, ok := in.(uint64); ok {
		return int64(u), 0, nil
	}
	if f, ok := in.(float64); ok {
		return 0, 0, fmt.Errorf("can not parse floating point number (%f) - use a string instead", f)
	}
	if in == nil {
		return 0, 0, nil
	}
	i, err := conv.ToInt64(in)
	return i, 0, err
}

func padRight(in, pad string, length int) string {
	for {
		in += pad
		if len(in) > length {
			return in[0:length]
		}
	}
}
