func ed25519PrivPEM(priv ed25519.PrivateKey) (string, error) {
	b, err := x509.MarshalPKCS8PrivateKey(priv)
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: b})), nil
}

// Ed25519GenerateKeyFromSeed -
func (f CryptoFuncs) Ed25519GenerateKeyFromSeed(encoding, seed string) (string, error) {
	if err := f.checkExperimental(); err != nil {
		return "", err
	}
	var seedB []byte
	var err error
	switch encoding {
	case "base64":
		seedB, err = base64.StdEncoding.DecodeString(seed)
	case "hex":
		seedB, err = hex.DecodeString(seed)
	default:
		return "", fmt.Errorf("invalid encoding given: %s - only 'hex' or 'base64' are valid options", encoding)
	}
	if err != nil {
		return "", fmt.Errorf("could not decode given seed: %w", err)
	}
	if len(seedB) != ed25519.SeedSize {
		return "", fmt.Errorf("ed25519: bad seed length: %d", len(seedB))
	}
	priv := ed25519.NewKeyFromSeed(seedB)
	return ed25519PrivPEM(priv)
}

// Ed25519DerivePublicKey -
func (f CryptoFuncs) Ed25519DerivePublicKey(privateKey string) (string, error) {
	if err := f.checkExperimental(); err != nil {
		return "", err
	}
	block, _ := pem.Decode([]byte(privateKey))
	if block == nil {
		return "", fmt.Errorf("failed to read key %q: no key found", privateKey)
	}
	k, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return "", err
	}
	priv, ok := k.(ed25519.PrivateKey)
	if !ok {
		return "", fmt.Errorf("unsupported private key type %T", k)
	}
	b, err := x509.MarshalPKIXPublicKey(priv.Public())
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: b})), nil
}

func parseAESArgs(args ...interface{}) (key []byte, keyBits int, msg []byte, err error) {
	switch len(args) {
	case 2:
		keyBits = 256
		key = toBytes(args[0])
		msg = toBytes(args[1])
	case 3:
		key = toBytes(args[0])
		keyBits, err = conv.ToInt(args[1])
		if err != nil {
			return nil, 0, nil, err
		}
		msg = toBytes(args[2])
	default:
		return nil, 0, nil, fmt.Errorf("wrong number of args: want 2 or 3, got %d", len(args))
	}
	return key, keyBits, msg, nil
}

func aesKey(key []byte, keyBits int) []byte {
	size := keyBits / 8
	k := make([]byte, size)
	copy(k, key)
	return k
}

// EncryptAES -
func (f CryptoFuncs) EncryptAES(args ...interface{}) ([]byte, error) {
	if err := f.checkExperimental(); err != nil {
		return nil, err
	}
	key, keyBits, msg, err := parseAESArgs(args...)
	if err != nil {
		return nil, err
	}
	if len(msg) == 0 {
		return []byte{}, nil
	}
	block, err := aes.NewCipher(aesKey(key, keyBits))
	if err != nil {
		return nil, err
	}
	padded := pkcs7Pad(msg, block.BlockSize())
	out := make([]byte, aes.BlockSize+len(padded))
	iv := out[:aes.BlockSize]
	if _, err := rand.Read(iv); err != nil {
		return nil, err
	}
	mode := cipher.NewCBCEncrypter(block, iv)
	mode.CryptBlocks(out[aes.BlockSize:], padded)
	return out, nil
}

// DecryptAES -
func (f CryptoFuncs) DecryptAES(args ...interface{}) (string, error) {
	out, err := f.DecryptAESBytes(args...)
	return string(out), err
}

// DecryptAESBytes -
func (f CryptoFuncs) DecryptAESBytes(args ...interface{}) ([]byte, error) {
	if err := f.checkExperimental(); err != nil {
		return nil, err
	}
	key, keyBits, msg, err := parseAESArgs(args...)
	if err != nil {
		return nil, err
	}
	if len(msg) == 0 {
		return []byte{}, nil
	}
	block, err := aes.NewCipher(aesKey(key, keyBits))
	if err != nil {
		return nil, err
	}
	iv := msg[:aes.BlockSize]
	data := msg[aes.BlockSize:]
	if len(data)%aes.BlockSize != 0 {
		return nil, fmt.Errorf("crypto/cipher: input not full blocks")
	}
	out := make([]byte, len(data))
	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(out, data)
	return pkcs7Unpad(out), nil
}

func pkcs7Pad(data []byte, blockSize int) []byte {
	n := blockSize - len(data)%blockSize
	out := make([]byte, len(data)+n)
	copy(out, data)
	for i := len(data); i < len(out); i++ {
		out[i] = byte(n)
	}
	return out
}

func pkcs7Unpad(data []byte) []byte {
	if len(data) == 0 {
		return data
	}
	n := int(data[len(data)-1])
	return data[:len(data)-n]
}
