package funcs

import (
	"context"
	"fmt"
	"math/rand/v2"
	"regexp"
	"strconv"
	"text/template"
	"unicode"
	"unicode/utf8"

	"gomplate/internal/conv"
)

// CreateRandomFuncs -
func CreateRandomFuncs(ctx context.Context) template.FuncMap {
	ns := &RandomFuncs{ctx: ctx}
	return template.FuncMap{
		"random": func() interface{} { return ns },
	}
}

// RandomFuncs -
type RandomFuncs struct {
	ctx context.Context
}

const (
	defaultSet  = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-"
	alphaSet    = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
	alphaNumSet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
)

var asciiSet = func() []rune {
	out := []rune{}
	for r := rune(0x21); r <= 0x7E; r++ {
		out = append(out, r)
	}
	return out
}()

func randomString(count int, chars []rune) string {
	out := make([]rune, count)
	for i := range out {
		out[i] = chars[rand.IntN(len(chars))]
	}
	return string(out)
}

// ASCII -
func (RandomFuncs) ASCII(count interface{}) (string, error) {
	c, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if c < 0 {
		return "", fmt.Errorf("runtime error: makeslice: len out of range")
	}
	return randomString(c, asciiSet), nil
}

// Alpha -
func (RandomFuncs) Alpha(count interface{}) (string, error) {
	c, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if c < 0 {
		return "", fmt.Errorf("runtime error: makeslice: len out of range")
	}
	return randomString(c, []rune(alphaSet)), nil
}

// AlphaNum -
func (RandomFuncs) AlphaNum(count interface{}) (string, error) {
	c, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if c < 0 {
		return "", fmt.Errorf("runtime error: makeslice: len out of range")
	}
	return randomString(c, []rune(alphaNumSet)), nil
}

// String -
func (RandomFuncs) String(count interface{}, args ...interface{}) (string, error) {
	c, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if c < 0 {
		return "", fmt.Errorf("runtime error: makeslice: len out of range")
	}
	var chars []rune
	switch len(args) {
	case 0:
		chars = []rune(defaultSet)
	case 1:
		re, err := regexp.Compile(conv.ToString(args[0]))
		if err != nil {
			return "", err
		}
		chars = []rune{}
		for r := rune(0); r <= unicode.MaxRune; r++ {
			if !unicode.IsPrint(r) {
				continue
			}
			if re.MatchString(string(r)) {
				chars = append(chars, r)
			}
		}
	case 2:
		lower, err := toCodePoint(args[0])
		if err != nil {
			return "", err
		}
		upper, err := toCodePoint(args[1])
		if err != nil {
			return "", err
		}
		chars = []rune{}
		for r := lower; r <= upper; r++ {
			if unicode.IsPrint(r) {
				chars = append(chars, r)
			}
		}
		if len(chars) == 0 {
			return "", fmt.Errorf("no printable codepoints found between U'%c' and U'%c'", lower, upper)
		}
	default:
		return "", fmt.Errorf("wrong number of args: want 1, 2, or 3, got %d", len(args)+1)
	}
	if len(chars) == 0 {
		return "", fmt.Errorf("invalid argument to IntN")
	}
	return randomString(c, chars), nil
}

func toCodePoint(in interface{}) (rune, error) {
	switch v := in.(type) {
	case string:
		if utf8.RuneCountInString(v) == 1 {
			r, _ := utf8.DecodeRuneInString(v)
