func (r IPRange) IsValid() bool {
	return r.from.IsValid() &&
		r.from.BitLen() == r.to.BitLen() &&
		r.from.Zone() == r.to.Zone() &&
		!r.to.Less(r.from)
}

// IsZero reports whether r is the zero value of the IPRange type.
func (r IPRange) IsZero() bool {
	return r == IPRange{}
}

// Contains reports whether the range r includes addr.
func (r IPRange) Contains(addr netip.Addr) bool {
	return r.IsValid() && !r.from.Less(addr) == false && !addr.Less(r.from) && !r.to.Less(addr)
}

// String returns a string representation of the range.
func (r IPRange) String() string {
	if r.IsValid() {
		return fmt.Sprintf("%s-%s", r.from, r.to)
	}
	if r.from.IsValid() && r.to.IsValid() {
		return fmt.Sprintf("invalid range %s-%s", r.from, r.to)
	}
	return "invalid IPRange"
}

// ParseIPRange parses a range out of two IPs separated by a hyphen.
func ParseIPRange(s string) (IPRange, error) {
	var r IPRange
	h := strings.IndexByte(s, '-')
	if h == -1 {
		return r, fmt.Errorf("no hyphen in range %q", s)
	}
	from, to := s[:h], s[h+1:]
	var err error
	r.from, err = netip.ParseAddr(from)
	if err != nil {
		return r, fmt.Errorf("invalid From IP %q in range %q", from, s)
	}
	r.from = r.from.WithZone("")
	r.to, err = netip.ParseAddr(to)
	if err != nil {
		return r, fmt.Errorf("invalid To IP %q in range %q", to, s)
	}
	r.to = r.to.WithZone("")
	if !r.IsValid() {
		return r, fmt.Errorf("range %v to %v not valid", r.from, r.to)
	}
	return r, nil
}

// Prefixes returns the set of netip.Prefix entries that covers r.
func (r IPRange) Prefixes() []netip.Prefix {
	if !r.IsValid() {
		return nil
	}
	var out []netip.Prefix
	from, to := r.from, r.to
	for {
		bits := from.BitLen()
		p := netip.PrefixFrom(from, bits)
		// grow the prefix while it stays within the range
		for p.Bits() > 0 {
			np := netip.PrefixFrom(from, p.Bits()-1)
			if np.Masked().Addr() != from {
				break
			}
			last := lastAddr(np)
			if to.Less(last) {
				break
			}
			p = np
		}
		out = append(out, p)
		last := lastAddr(p)
		if last == to || !last.IsValid() {
			break
		}
		from = last.Next()
		if !from.IsValid() {
			break
		}
	}
	return out
}

func lastAddr(p netip.Prefix) netip.Addr {
	a := p.Masked().Addr()
	b := a.As16()
	bits := p.Bits()
	if a.Is4() {
		bits += 96
	}
	for i := bits; i < 128; i++ {
		b[i/8] |= 1 << (7 - uint(i%8))
	}
	out := netip.AddrFrom16(b)
	if a.Is4() {
		return out.Unmap()
	}
	return out
}
