		return netip.Addr{}, err
	}
	hostNum, err := conv.ToInt64(hostnum)
	if err != nil {
		return netip.Addr{}, err
	}
	return cidrHost(network, big.NewInt(hostNum))
}

func addrToBig(a netip.Addr) *big.Int {
	if a.Is4() {
		b := a.As4()
		return new(big.Int).SetBytes(b[:])
	}
	b := a.As16()
	return new(big.Int).SetBytes(b[:])
}

func bigToAddr(n *big.Int, is4 bool) netip.Addr {
	if is4 {
		b := make([]byte, 4)
		n.FillBytes(b)
		return netip.AddrFrom4([4]byte(b))
	}
	b := make([]byte, 16)
	n.FillBytes(b)
	return netip.AddrFrom16([16]byte(b))
}

func cidrHost(network netip.Prefix, num *big.Int) (netip.Addr, error) {
	addr := network.Addr()
	parentLen := network.Bits()
	addrLen := addr.BitLen()
	hostLen := addrLen - parentLen

	maxHostNum := big.NewInt(1)
	maxHostNum.Lsh(maxHostNum, uint(hostLen))
	maxHostNum.Sub(maxHostNum, big.NewInt(1))

	numUint64 := big.NewInt(int64(num.Uint64()))
	if num.Cmp(big.NewInt(0)) == -1 {
		numUint64.Neg(num)
		numUint64.Sub(numUint64, big.NewInt(1))
		num.Sub(maxHostNum, numUint64)
	}
	if numUint64.Cmp(maxHostNum) == 1 {
		return netip.Addr{}, fmt.Errorf("prefix of %d does not accommodate a host numbered %d", parentLen, num)
	}

	ipInt := addrToBig(addr)
	ipInt.Or(ipInt, num)
	return bigToAddr(ipInt, addr.Is4()), nil
}

// CIDRNetmask -
func (f NetFuncs) CIDRNetmask(prefix interface{}) (netip.Addr, error) {
	if !experimentalEnabled(f.ctx) {
		return netip.Addr{}, errExperimental
	}
	network, err := f.parseNetipPrefix(prefix)
	if err != nil {
		return netip.Addr{}, err
	}
	bits := network.Addr().BitLen()
	mask := stdnet.CIDRMask(network.Bits(), bits)
	addr, _ := netip.AddrFromSlice(mask)
	return addr, nil
}

// CIDRSubnets -
func (f NetFuncs) CIDRSubnets(newbits interface{}, prefix interface{}) ([]netip.Prefix, error) {
	if !experimentalEnabled(f.ctx) {
		return nil, errExperimental
	}
	network, err := f.parseNetipPrefix(prefix)
	if err != nil {
		return nil, err
	}
	nBits, err := conv.ToInt(newbits)
	if err != nil {
		return nil, err
	}
	if nBits < 1 {
		return nil, fmt.Errorf("must extend prefix by at least one bit")
	}
	parentLen := network.Bits()
	addrLen := network.Addr().BitLen()
	if parentLen+nBits > addrLen {
		return nil, fmt.Errorf("insufficient address space to extend prefix of %d by %d", parentLen, nBits)
	}
	maxNetNum := int64(1) << uint64(nBits)
	out := make([]netip.Prefix, maxNetNum)
	for i := int64(0); i < maxNetNum; i++ {
		out[i] = subnetBig(network, nBits, big.NewInt(i))
	}
	return out, nil
}

func subnetBig(base netip.Prefix, newBits int, num *big.Int) netip.Prefix {
	addr := base.Masked().Addr()
	newPrefixLen := base.Bits() + newBits
	addrLen := addr.BitLen()
	ipInt := addrToBig(addr)
	n := new(big.Int).Set(num)
	n.Lsh(n, uint(addrLen-newPrefixLen))
	ipInt.Or(ipInt, n)
	return netip.PrefixFrom(bigToAddr(ipInt, addr.Is4()), newPrefixLen)
}

// CIDRSubnetSizes -
func (f NetFuncs) CIDRSubnetSizes(args ...interface{}) ([]netip.Prefix, error) {
	if !experimentalEnabled(f.ctx) {
		return nil, errExperimental
	}
	if len(args) < 2 {
		return nil, fmt.Errorf("wrong number of args: want 2 or more, got %d", len(args))
	}
	network, err := f.parseNetipPrefix(args[len(args)-1])
	if err != nil {
		return nil, err
	}
	newbits, err := conv.ToInts(args[:len(args)-1]...)
	if err != nil {
		return nil, err
	}

	startPrefixLen := network.Bits()
	addrLen := network.Addr().BitLen()

	firstLength := newbits[0]
	firstLength += startPrefixLen
	current, _ := previousSubnet(network, firstLength)

	retValues := make([]netip.Prefix, 0, len(newbits))
	for _, length := range newbits {
		if length < 1 {
			return nil, fmt.Errorf("must extend prefix by at least one bit")
		}
		if length > 32 {
			return nil, fmt.Errorf("may not extend prefix by more than 32 bits")
		}
		length += startPrefixLen
		if length > addrLen {
			protocol := "IP"
			switch addrLen {
			case 32:
				protocol = "IPv4"
			case 128:
				protocol = "IPv6"
			}
			return nil, fmt.Errorf("would extend prefix to %d bits, which is too long for an %s address", length, protocol)
		}
		next, rollover := nextSubnet(current, length)
		if rollover || !network.Contains(next.Addr()) {
			return nil, fmt.Errorf("not enough remaining address space for a subnet with a prefix of %d bits after %s", length, current.String())
		}
		current = next
		retValues = append(retValues, current)
	}
	return retValues, nil
}

func addrInc(a netip.Addr) (netip.Addr, bool) {
	n := a.Next()
	if !n.IsValid() {
		// wrapped around to zero
		if a.Is4() {
			return netip.AddrFrom4([4]byte{}), true
		}
		return netip.AddrFrom16([16]byte{}), true
	}
	return n, false
}

func addrDec(a netip.Addr) netip.Addr {
	p := a.Prev()
	if !p.IsValid() {
		// wrapped to all-ones
		if a.Is4() {
			return netip.AddrFrom4([4]byte{255, 255, 255, 255})
		}
		b := [16]byte{}
		for i := range b {
			b[i] = 255
		}
		return netip.AddrFrom16(b)
	}
	return p
}

func lastAddr(p netip.Prefix) netip.Addr {
	a := p.Masked().Addr()
	ipInt := addrToBig(a)
	hostLen := a.BitLen() - p.Bits()
	hostMask := big.NewInt(1)
	hostMask.Lsh(hostMask, uint(hostLen))
	hostMask.Sub(hostMask, big.NewInt(1))
	ipInt.Or(ipInt, hostMask)
	return bigToAddr(ipInt, a.Is4())
}

func nextSubnet(network netip.Prefix, prefixLen int) (netip.Prefix, bool) {
	currentLast := lastAddr(network)
	currentSubnet := netip.PrefixFrom(currentLast, prefixLen).Masked()
	last := lastAddr(currentSubnet)
	last, wrapped := addrInc(last)
	next := netip.PrefixFrom(last, prefixLen).Masked()
	isZero := wrapped || last == netip.AddrFrom4([4]byte{}) || last == netip.AddrFrom16([16]byte{})
	return next, isZero
}

func previousSubnet(network netip.Prefix, prefixLen int) (netip.Prefix, bool) {
	startIP := network.Addr()
	previousIP := addrDec(startIP)
	previous := netip.PrefixFrom(previousIP, prefixLen).Masked()
	isZero := startIP == netip.AddrFrom4([4]byte{}) || startIP == netip.AddrFrom16([16]byte{})
	return previous, isZero
}
