// CreateSemverFuncs -
func CreateSemverFuncs(ctx context.Context) template.FuncMap {
	ns := &SemverFuncs{ctx: ctx}
	return template.FuncMap{
		"semver": func() interface{} { return ns },
	}
}

// SemverFuncs -
type SemverFuncs struct {
	ctx context.Context
}

// Semver -
func (SemverFuncs) Semver(in interface{}) (*semver.Version, error) {
	return semver.NewVersion(conv.ToString(in))
}

