	"gomplate/internal/semver"
)

// CreateSemverFuncs -
func CreateSemverFuncs(ctx context.Context) template.FuncMap {
	ns := &SemverFuncs{ctx: ctx}
	return template.FuncMap{
		"semver": func() interface{} { return ns },
	}
}

// SemverFuncs -
type SemverFuncs struct {
	ctx context.Context
}

// Semver -
func (SemverFuncs) Semver(in interface{}) (*semver.Version, error) {
	return semver.NewVersion(conv.ToString(in))
}

// CheckConstraint -
func (SemverFuncs) CheckConstraint(constraint, in interface{}) (bool, error) {
	c, err := semver.NewConstraint(conv.ToString(constraint))
	if err != nil {
		return false, err
	}
	v, err := semver.NewVersion(conv.ToString(in))
	if err != nil {
		return false, err
	}
	return c.Check(v), nil
}
