package funcs

import (
	"context"
	"encoding/base64"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"strconv"
	"text/template"
	"time"

	"gomplate/internal/conv"
)

// CreateAWSFuncs -
func CreateAWSFuncs(ctx context.Context) template.FuncMap {
	ns := &AWSFuncs{ctx: ctx}
	return template.FuncMap{
		"aws":        func() interface{} { return ns },
		"ec2meta":    ns.EC2Meta,
		"ec2dynamic": ns.EC2Dynamic,
		"ec2tag":     ns.EC2Tag,
		"ec2tags":    ns.EC2Tags,
		"ec2region":  ns.EC2Region,
	}
}

// AWSFuncs -
type AWSFuncs struct {
	ctx context.Context
}

const imdsEndpoint = "http://169.254.169.254"

func awsTimeout() time.Duration {
	if v := os.Getenv("AWS_TIMEOUT"); v != "" {
		if ms, err := strconv.Atoi(v); err == nil {
			return time.Duration(ms) * time.Millisecond
		}
	}
	return 500 * time.Millisecond
}

func imdsGet(ctx context.Context, path string) (string, error) {
	client := &http.Client{Timeout: awsTimeout()}
	ep := imdsEndpoint
	if v := os.Getenv("AWS_META_ENDPOINT"); v != "" {
		ep = v
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, ep+"/latest/"+path, nil)
	if err != nil {
		return "", err
	}
	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status %d", resp.StatusCode)
	}
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func withDefault(def []string) string {
	if len(def) > 0 {
		return def[0]
	}
	return ""
}

// EC2Meta -
func (a *AWSFuncs) EC2Meta(key string, def ...string) (string, error) {
	v, err := imdsGet(a.ctx, "meta-data/"+key)
	if err != nil {
		return withDefault(def), nil
	}
	return v, nil
}

// EC2Dynamic -
func (a *AWSFuncs) EC2Dynamic(key string, def ...string) (string, error) {
	v, err := imdsGet(a.ctx, "dynamic/"+key)
	if err != nil {
		return withDefault(def), nil
	}
	return v, nil
}

