package funcs

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"text/template"
	"time"

	"gomplate/internal/config"
	"gomplate/internal/conv"
)

// CreatePluginFuncs - create template functions for the configured plugins
func CreatePluginFuncs(ctx context.Context, opts *Options) template.FuncMap {
	f := template.FuncMap{}
	if opts == nil {
		return f
	}
	for name, pc := range opts.Plugins {
		timeout := pc.Timeout
		if timeout == 0 {
			timeout = opts.PluginTimeout
		}
		if timeout == 0 {
			timeout = 5 * time.Second
		}
		p := &plugin{
			ctx:     ctx,
			name:    name,
			path:    pc.Cmd,
			args:    pc.Args,
			pipe:    pc.Pipe,
			timeout: timeout,
			stderr:  opts.Stderr,
		}
		f[name] = p.run
	}
	return f
}

type plugin struct {
	ctx     context.Context
	name    string
	path    string
	args    []string
	pipe    bool
	timeout time.Duration
	stderr  io.Writer
}

func (p *plugin) run(args ...interface{}) (interface{}, error) {
	a := make([]string, 0, len(p.args)+len(args))
	a = append(a, p.args...)
	for _, arg := range args {
		a = append(a, conv.ToString(arg))
	}

	var stdin io.Reader
	if p.pipe && len(a) > 0 {
		stdin = strings.NewReader(a[len(a)-1])
		a = a[:len(a)-1]
	}

	ctx, cancel := context.WithTimeout(p.ctx, p.timeout)
	defer cancel()

	start := time.Now()
	c := exec.CommandContext(ctx, p.path, a...)
	c.Stdin = stdin
	stderr := p.stderr
	if stderr == nil {
		stderr = os.Stderr
	}
	c.Stderr = stderr
	outBuf := &bytes.Buffer{}
	c.Stdout = outBuf

	err := c.Start()
	if err != nil {
		return nil, fmt.Errorf("starting command: %w", err)
	}

	err = c.Wait()
	if ctx.Err() != nil {
		return nil, fmt.Errorf("plugin timed out after %v: %w", time.Since(start), ctx.Err())
	}
	if err != nil {
		return nil, err
	}
	return outBuf.String(), nil
}

var _ config.PluginConfig
EOF
echo ok"}

