				sb.WriteByte('\\')
			case '"':
				sb.WriteByte('"')
			case 'u':
				if l.pos+4 > len(l.src) {
					return nil, fmt.Errorf("invalid escape")
				}
				var r rune
				for i := 0; i < 4; i++ {
					h := l.src[l.pos+i]
					var v byte
					switch {
					case h >= '0' && h <= '9':
						v = h - '0'
					case h >= 'a' && h <= 'f':
						v = h - 'a' + 10
					case h >= 'A' && h <= 'F':
						v = h - 'A' + 10
					default:
						return nil, fmt.Errorf("invalid escape")
					}
					r = r*16 + rune(v)
				}
				l.pos += 4
				sb.WriteRune(r)
			case '(':
				// interpolation: find matching paren
				depth := 1
				s := l.pos
				inStr := false
				for l.pos < len(l.src) && depth > 0 {
					ch := l.src[l.pos]
					if inStr {
						if ch == '\\' {
							l.pos++
						} else if ch == '"' {
							inStr = false
						}
					} else {
						switch ch {
						case '"':
							inStr = true
						case '(':
							depth++
						case ')':
							depth--
						}
					}
					l.pos++
				}
				if depth != 0 {
					return nil, fmt.Errorf("unterminated string interpolation")
				}
				parts = append(parts, stringPart{lit: sb.String()})
				sb.Reset()
				parts = append(parts, stringPart{query: l.src[s : l.pos-1], isExpr: true})
			default:
				return nil, fmt.Errorf("invalid escape \\%c", e)
			}
		default:
			sb.WriteByte(c)
			l.pos++
		}
	}
}

func tokenize(src string) ([]token, error) {
	l := &lexer{src: src}
	var toks []token
	for {
		t, err := l.next()
		if err != nil {
			return nil, err
		}
		toks = append(toks, t)
		if t.kind == tEOF {
			return toks, nil
		}
	}
}
