// Package jq implements a subset of the jq query language.
package jq

import (
	"fmt"
	"strings"
	"unicode"
)

type tokenKind int

const (
	tEOF tokenKind = iota
	tIdent
	tField    // .foo
	tVar      // $foo
	tNumber
	tString   // string literal (raw, may contain interpolation parts)
	tFormat   // @base64
	tOp       // punctuation / operators
	tKeyword
)

type token struct {
	kind tokenKind
	val  string
	pos  int
	// for strings: the parsed parts (literal strings and interpolated sub-queries)
	parts []stringPart
}

type stringPart struct {
	lit    string
	query  string
	isExpr bool
}

var keywords = map[string]bool{
	"if": true, "then": true, "elif": true, "else": true, "end": true,
	"as": true, "reduce": true, "foreach": true, "def": true, "try": true,
	"catch": true, "and": true, "or": true, "not": false, "label": true, "break": true,
	"import": true, "include": true, "__loc__": true,
}

type lexer struct {
	src string
	pos int
}

func (l *lexer) peekByte() byte {
	if l.pos >= len(l.src) {
		return 0
	}
	return l.src[l.pos]
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func (l *lexer) skipSpace() {
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == '#' {
			for l.pos < len(l.src) && l.src[l.pos] != '\n' {
				l.pos++
			}
			continue
		}
		if unicode.IsSpace(rune(c)) {
			l.pos++
			continue
		}
		break
	}
}

var ops3 = []string{"?//", "//="}
var ops2 = []string{"|=", "+=", "-=", "*=", "/=", "%=", "==", "!=", "<=", ">=", "//", ".."}

func (l *lexer) next() (token, error) {
	l.skipSpace()
	start := l.pos
	if l.pos >= len(l.src) {
		return token{kind: tEOF, pos: start}, nil
	}
	c := l.src[l.pos]

	// field access .foo or ."foo" handled in parser; here "." followed by ident
	if c == '.' {
		if l.pos+1 < len(l.src) && isIdentStart(l.src[l.pos+1]) {
			l.pos++
			s := l.pos
			for l.pos < len(l.src) && isIdentChar(l.src[l.pos]) {
				l.pos++
			}
			return token{kind: tField, val: l.src[s:l.pos], pos: start}, nil
		}
	}
	if c == '$' {
		l.pos++
		if l.pos < len(l.src) && l.src[l.pos] == '_' && strings.HasPrefix(l.src[l.pos:], "__loc__") {
			l.pos += len("__loc__")
			return token{kind: tVar, val: "__loc__", pos: start}, nil
		}
		s := l.pos
		for l.pos < len(l.src) && (isIdentChar(l.src[l.pos]) || l.src[l.pos] == ':') {
			l.pos++
		}
		if s == l.pos {
			return token{}, fmt.Errorf("unexpected token \"$\"")
		}
		return token{kind: tVar, val: l.src[s:l.pos], pos: start}, nil
	}
	if c == '@' {
		l.pos++
		s := l.pos
		for l.pos < len(l.src) && isIdentChar(l.src[l.pos]) {
			l.pos++
		}
		return token{kind: tFormat, val: l.src[s:l.pos], pos: start}, nil
	}
	if isIdentStart(c) {
		s := l.pos
		for l.pos < len(l.src) && (isIdentChar(l.src[l.pos]) || (l.src[l.pos] == ':' && l.pos+1 < len(l.src) && l.src[l.pos+1] == ':')) {
			if l.src[l.pos] == ':' {
				l.pos += 2
				continue
			}
			l.pos++
		}
		word := l.src[s:l.pos]
		if kw, ok := keywords[word]; ok && kw {
			return token{kind: tKeyword, val: word, pos: start}, nil
		}
		return token{kind: tIdent, val: word, pos: start}, nil
	}
	if (c >= '0' && c <= '9') || (c == '.' && l.pos+1 < len(l.src) && l.src[l.pos+1] >= '0' && l.src[l.pos+1] <= '9') {
		s := l.pos
		for l.pos < len(l.src) && ((l.src[l.pos] >= '0' && l.src[l.pos] <= '9') || l.src[l.pos] == '.') {
			l.pos++
		}
		if l.pos < len(l.src) && (l.src[l.pos] == 'e' || l.src[l.pos] == 'E') {
			l.pos++
			if l.pos < len(l.src) && (l.src[l.pos] == '+' || l.src[l.pos] == '-') {
				l.pos++
			}
			for l.pos < len(l.src) && l.src[l.pos] >= '0' && l.src[l.pos] <= '9' {
				l.pos++
			}
		}
		return token{kind: tNumber, val: l.src[s:l.pos], pos: start}, nil
	}
	if c == '"' {
		parts, err := l.lexString()
		if err != nil {
			return token{}, err
		}
		return token{kind: tString, parts: parts, pos: start}, nil
	}
	for _, op := range ops3 {
		if strings.HasPrefix(l.src[l.pos:], op) {
			l.pos += 3
			return token{kind: tOp, val: op, pos: start}, nil
		}
	}
	for _, op := range ops2 {
		if strings.HasPrefix(l.src[l.pos:], op) {
			l.pos += 2
			return token{kind: tOp, val: op, pos: start}, nil
		}
	}
	l.pos++
	switch c {
	case '.', '[', ']', '{', '}', '(', ')', ',', '|', ':', ';', '=', '<', '>', '+', '-', '*', '/', '%', '?':
		return token{kind: tOp, val: string(c), pos: start}, nil
	}
	return token{}, fmt.Errorf("unexpected token %q", string(c))
}

// lexString lexes a string literal starting at the opening quote
func (l *lexer) lexString() ([]stringPart, error) {
	l.pos++ // opening quote
	parts := []stringPart{}
	var sb strings.Builder
	for {
		if l.pos >= len(l.src) {
			return nil, fmt.Errorf("unterminated string")
		}
		c := l.src[l.pos]
		switch c {
		case '"':
			l.pos++
			parts = append(parts, stringPart{lit: sb.String()})
			return parts, nil
		case '\\':
			l.pos++
			if l.pos >= len(l.src) {
				return nil, fmt.Errorf("unterminated string")
			}
			e := l.src[l.pos]
			l.pos++
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case '/':
				sb.WriteByte('/')
			case '\\':
				sb.WriteByte('\\')
			case '"':
				sb.WriteByte('"')
			case 'u':
				if l.pos+4 > len(l.src) {
					return nil, fmt.Errorf("invalid escape")
				}
				var r rune
				for i := 0; i < 4; i++ {
					h := l.src[l.pos+i]
					var v byte
					switch {
					case h >= '0' && h <= '9':
						v = h - '0'
					case h >= 'a' && h <= 'f':
						v = h - 'a' + 10
					case h >= 'A' && h <= 'F':
						v = h - 'A' + 10
					default:
						return nil, fmt.Errorf("invalid escape")
					}
					r = r*16 + rune(v)
				}
				l.pos += 4
				sb.WriteRune(r)
			case '(':
				// interpolation: find matching paren
				depth := 1
				s := l.pos
				inStr := false
				for l.pos < len(l.src) && depth > 0 {
					ch := l.src[l.pos]
					if inStr {
						if ch == '\\' {
							l.pos++
						} else if ch == '"' {
							inStr = false
						}
					} else {
						switch ch {
						case '"':
							inStr = true
						case '(':
							depth++
						case ')':
							depth--
						}
					}
					l.pos++
				}
				if depth != 0 {
					return nil, fmt.Errorf("unterminated string interpolation")
				}
				parts = append(parts, stringPart{lit: sb.String()})
				sb.Reset()
				parts = append(parts, stringPart{query: l.src[s : l.pos-1], isExpr: true})
			default:
				return nil, fmt.Errorf("invalid escape \\%c", e)
			}
		default:
			sb.WriteByte(c)
			l.pos++
		}
	}
}

func tokenize(src string) ([]token, error) {
	l := &lexer{src: src}
	var toks []token
	for {
		t, err := l.next()
		if err != nil {
			return nil, err
		}
		toks = append(toks, t)
		if t.kind == tEOF {
			return toks, nil
		}
	}
}
