{"command":"cd /workspace && cat > internal/jq/parser.go <<'EOF'
package jq

import (
	"fmt"
	"strconv"
)

type node interface{}

type (
	identityNode struct{}
	recurseNode  struct{}
	fieldNode    struct {
		target node
		name   node // string literal or expression
		opt    bool
	}
	indexNode struct {
		target node
		index  node
		opt    bool
	}
	sliceNode struct {
		target   node
		from, to node
		opt      bool
	}
	iterateNode struct {
		target node
		opt    bool
	}
	literalNode struct{ value interface{} }
	stringNode  struct {
		parts  []stringPart
		format string
	}
	formatNode struct{ name string }
	arrayNode  struct{ elem node }
	objectNode struct{ entries []objEntry }
	objEntry   struct {
		key   node // evaluates to string(s)
		value node // may be nil for shorthand
	}
	pipeNode  struct{ left, right node }
	commaNode struct{ left, right node }
	altNode   struct{ left, right node }
	binopNode struct {
		op          string
		left, right node
	}
	andNode    struct{ left, right node }
	orNode     struct{ left, right node }
	negNode    struct{ expr node }
	assignNode struct {
		op          string
		left, right node
	}
	ifNode struct {
		cond, then node
		elifs      []ifBranch
		els        node
	}
	ifBranch struct{ cond, then node }
	tryNode  struct{ body, catch node }
	reduceNode struct {
		source  node
		pattern pattern
		init    node
		update  node
	}
	foreachNode struct {
		source  node
		pattern pattern
		init    node
		update  node
		extract node
	}
	funcDefNode struct {
		name   string
		params []string
		body   node
		rest   node
	}
	funcCallNode struct {
		name string
		args []node
	}
	varNode  struct{ name string }
	bindNode struct {
		source   node
		patterns []pattern
		body     node
	}
	optionalNode struct{ expr node }
	labelNode    struct {
		name string
		body node
	}
	breakNode struct{ name string }
)

// pattern - destructuring pattern
type pattern struct {
	name   string         // $name
	array  []pattern      // [p1, p2]
	object []objPattern   // {key: p, $name, (expr): p}
	isArr  bool
	isObj  bool
}

type objPattern struct {
	keyVar  string  // $name shorthand
	key     node    // key expression (string or (expr))
	val     *pattern
}

type parser struct {
	toks []token
	pos  int
}

func (p *parser) peek() token { return p.toks[p.pos] }
func (p *parser) next() token {
	t := p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}

func (p *parser) isOp(val string) bool {
	t := p.peek()
	return t.kind == tOp && t.val == val
}

func (p *parser) isKw(val string) bool {
	t := p.peek()
	return t.kind == tKeyword && t.val == val
}

func (p *parser) expectOp(val string) error {
	t := p.next()
	if t.kind != tOp || t.val != val {
		return fmt.Errorf("syntax error: expected %q but got %q", val, tokStr(t))
	}
	return nil
}

func (p *parser) expectKw(val string) error {
	t := p.next()
	if t.kind != tKeyword || t.val != val {
		return fmt.Errorf("syntax error: expected %q but got %q", val, tokStr(t))
	}
	return nil
}

func tokStr(t token) string {
	switch t.kind {
	case tEOF:
		return "EOF"
	case tField:
		return "." + t.val
	case tVar:
		return "$" + t.val
	case tString:
		return "string"
	case tFormat:
		return "@" + t.val
	}
	return t.val
}

// Parse parses a jq query
func Parse(src string) (node, error) {
	toks, err := tokenize(src)
	if err != nil {
		return nil, err
	}
	p := &parser{toks: toks}
	n, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tEOF {
		return nil, fmt.Errorf("syntax error: unexpected token %q", tokStr(p.peek()))
	}
	return n, nil
}

// pipe: comma ('|' pipe)?  also handles 'def' and 'term as $x | pipe'
func (p *parser) parsePipe() (node, error) {
	if p.isKw("def") {
		return p.parseFuncDef()
	}
	left, err := p.parseComma()
	if err != nil {
		return nil, err
	}
	if p.isKw("as") {
		p.next()
		pats := []pattern{}
		for {
			pat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			pats = append(pats, pat)
			if p.isOp("?//") {
				p.next()
				continue
			}
			break
		}
		if err := p.expectOp("|"); err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &bindNode{source: left, patterns: pats, body: body}, nil
	}
	if p.isOp("|") {
		p.next()
		right, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &pipeNode{left: left, right: right}, nil
	}
	return left, nil
}

func (p *parser) parseFuncDef() (node, error) {
	p.next() // def
	name := p.next()
	if name.kind != tIdent {
		return nil, fmt.Errorf("syntax error: expected function name")
	}
	params := []string{}
	if p.isOp("(") {
		p.next()
		for {
			t := p.next()
			switch t.kind {
			case tIdent:
				params = append(params, t.val)
			case tVar:
				params = append(params, "$"+t.val)
			default:
				return nil, fmt.Errorf("syntax error: bad parameter")
			}
			if p.isOp(";") {
				p.next()
				continue
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			break
		}
	}
	if err := p.expectOp(":"); err != nil {
		return nil, err
	}
	body, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectOp(";"); err != nil {
		return nil, err
	}
	rest, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	return &funcDefNode{name: name.val, params: params, body: body, rest: rest}, nil
}

func (p *parser) parsePattern() (pattern, error) {
	t := p.peek()
	switch {
	case t.kind == tVar:
		p.next()
		return pattern{name: t.val}, nil
	case t.kind == tOp && t.val == "[":
		p.next()
		pat := pattern{isArr: true}
		for {
			sub, err := p.parsePattern()
			if err != nil {
				return pat, err
			}
			pat.array = append(pat.array, sub)
			if p.isOp(",") {
				p.next()
				continue
			}
			if err := p.expectOp("]"); err != nil {
				return pat, err
			}
			return pat, nil
		}
	case t.kind == tOp && t.val == "{":
		p.next()
		pat := pattern{isObj: true}
		for {
			var op objPattern
			kt := p.peek()
			switch {
			case kt.kind == tVar:
				p.next()
				op.keyVar = kt.val
				if p.isOp(":") {
					p.next()
					sub, err := p.parsePattern()
					if err != nil {
						return pat, err
					}
					op.val = &sub
				}
			case kt.kind == tIdent || kt.kind == tKeyword:
				p.next()
				op.key = &literalNode{value: kt.val}
				if err := p.expectOp(":"); err != nil {
					return pat, err
				}
				sub, err := p.parsePattern()
				if err != nil {
					return pat, err
				}
				op.val = &sub
			case kt.kind == tString:
				p.next()
				op.key = &stringNode{parts: kt.parts}
				if err := p.expectOp(":"); err != nil {
					return pat, err
				}
				sub, err := p.parsePattern()
				if err != nil {
					return pat, err
				}
				op.val = &sub
			case kt.kind == tOp && kt.val == "(":
				p.next()
				k, err := p.parsePipe()
				if err != nil {
					return pat, err
				}
				if err := p.expectOp(")"); err != nil {
					return pat, err
				}
				op.key = k
				if err := p.expectOp(":"); err != nil {
					return pat, err
				}
				sub, err := p.parsePattern()
				if err != nil {
					return pat, err
				}
				op.val = &sub
			default:
				return pat, fmt.Errorf("syntax error: bad object pattern")
			}
			pat.object = append(pat.object, op)
			if p.isOp(",") {
				p.next()
				continue
			}
			if err := p.expectOp("}"); err != nil {
				return pat, err
			}
			return pat, nil
		}
	}
	return pattern{}, fmt.Errorf("syntax error: bad pattern")
}

func (p *parser) parseComma() (node, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	for p.isOp(",") {
		p.next()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		left = &commaNode{left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseAlt() (node, error) {
	left, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	if p.isOp("//") {
		p.next()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		return &altNode{left: left, right: right}, nil
	}
	return left, nil
}

var assignOps = map[string]bool{"=": true, "|=": true, "+=": true, "-=": true, "*=": true, "/=": true, "%=": true, "//=": true}

func (p *parser) parseAssign() (node, error) {
	left, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	if t := p.peek(); t.kind == tOp && assignOps[t.val] {
		p.next()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		return &assignNode{op: t.val, left: left, right: right}, nil
	}
	return left, nil
}

func (p *parser) parseOr() (node, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.isKw("or") {
		p.next()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &orNode{left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseAnd() (node, error) {
	left, err := p.parseCompare()
	if err != nil {
		return nil, err
	}
	for p.isKw("and") {
		p.next()
		right, err := p.parseCompare()
		if err != nil {
			return nil, err
		}
		left = &andNode{left: left, right: right}
	}
	return left, nil
}

var cmpOps = map[string]bool{"==": true, "!=": true, "<": true, "<=": true, ">": true, ">=": true}

func (p *parser) parseCompare() (node, error) {
	left, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	if t := p.peek(); t.kind == tOp && cmpOps[t.val] {
		p.next()
		right, err := p.parseAdditive()
		if err != nil {
			return nil, err
		}
		return &binopNode{op: t.val, left: left, right: right}, nil
	}
	return left, nil
}

func (p *parser) parseAdditive() (node, error) {
	left, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t.kind == tOp && (t.val == "+" || t.val == "-") {
			p.next()
			right, err := p.parseMultiplicative()
			if err != nil {
				return nil, err
			}
			left = &binopNode{op: t.val, left: left, right: right}
			continue
		}
		return left, nil
	}
}

func (p *parser) parseMultiplicative() (node, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t.kind == tOp && (t.val == "*" || t.val == "/" || t.val == "%") {
			p.next()
			right, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			left = &binopNode{op: t.val, left: left, right: right}
			continue
		}
		return left, nil
	}
}

func (p *parser) parseUnary() (node, error) {
	if p.isOp("-") {
		p.next()
		e, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &negNode{expr: e}, nil
	}
	return p.parsePostfix()
}

// postfix: term followed by .foo, [..], ?, etc.
func (p *parser) parsePostfix() (node, error) {
	term, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		switch {
		case t.kind == tField:
			p.next()
			term = &fieldNode{target: term, name: &literalNode{value: t.val}}
		case t.kind == tOp && t.val == ".":
			// ."foo" or .[...]
			p.next()
			nt := p.peek()
			if nt.kind == tString {
				p.next()
				term = &fieldNode{target: term, name: &stringNode{parts: nt.parts}}
			} else if nt.kind == tOp && nt.val == "[" {
				term, err = p.parseBracketSuffix(term)
				if err != nil {
					return nil, err
				}
			} else {
				return nil, fmt.Errorf("syntax error: unexpected token %q", tokStr(nt))
			}
		case t.kind == tOp && t.val == "[":
			term, err = p.parseBracketSuffix(term)
			if err != nil {
				return nil, err
			}
		case t.kind == tOp && t.val == "?":
			p.next()
			switch tt := term.(type) {
			case *fieldNode:
				tt.opt = true
			case *indexNode:
				tt.opt = true
			case *sliceNode:
				tt.opt = true
			case *iterateNode:
				tt.opt = true
			default:
				term = &optionalNode{expr: term}
			}
		default:
			return term, nil
		}
	}
}

// parseBracketSuffix parses [..] after a term: iterate, index or slice
func (p *parser) parseBracketSuffix(target node) (node, error) {
	p.next() // [
	if p.isOp("]") {
		p.next()
		return &iterateNode{target: target}, nil
	}
	var from, to node
	var err error
	if !p.isOp(":") {
		from, err = p.parsePipe()
		if err != nil {
			return nil, err
		}
	}
	if p.isOp(":") {
		p.next()
		if !p.isOp("]") {
			to, err = p.parsePipe()
			if err != nil {
				return nil, err
			}
		}
		if err := p.expectOp("]"); err != nil {
			return nil, err
		}
		return &sliceNode{target: target, from: from, to: to}, nil
	}
	if err := p.expectOp("]"); err != nil {
		return nil, err
	}
	return &indexNode{target: target, index: from}, nil
}

func (p *parser) parseTerm() (node, error) {
	t := p.next()
	switch t.kind {
	case tField:
		return &fieldNode{target: &identityNode{}, name: &literalNode{value: t.val}}, nil
	case tVar:
		return &varNode{name: t.val}, nil
	case tNumber:
		if i, err := strconv.ParseInt(t.val, 10, 64); err == nil {
			return &literalNode{value: int(i)}, nil
		}
		f, err := strconv.ParseFloat(t.val, 64)
		if err != nil {
			return nil, fmt.Errorf("invalid number %q", t.val)
		}
		return &literalNode{value: f}, nil
	case tString:
		return &stringNode{parts: t.parts}, nil
	case tFormat:
		if p.peek().kind == tString {
			st := p.next()
			return &stringNode{parts: st.parts, format: t.val}, nil
		}
		return &formatNode{name: t.val}, nil
	case tKeyword:
		switch t.val {
		case "if":
			return p.parseIf()
		case "try":
			body, err := p.parsePostfixTerm()
			if err != nil {
				return nil, err
			}
			var catch node
			if p.isKw("catch") {
				p.next()
				catch, err = p.parsePostfixTerm()
				if err != nil {
					return nil, err
				}
			}
			return &tryNode{body: body, catch: catch}, nil
		case "reduce":
			src, err := p.parsePostfixTerm()
			if err != nil {
				return nil, err
			}
			if err := p.expectKw("as"); err != nil {
				return nil, err
			}
			pat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp("("); err != nil {
				return nil, err
			}
			init, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(";"); err != nil {
				return nil, err
			}
			update, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return &reduceNode{source: src, pattern: pat, init: init, update: update}, nil
		case "foreach":
			src, err := p.parsePostfixTerm()
			if err != nil {
				return nil, err
			}
			if err := p.expectKw("as"); err != nil {
				return nil, err
			}
			pat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp("("); err != nil {
				return nil, err
			}
			init, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(";"); err != nil {
				return nil, err
			}
			update, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			var extract node
			if p.isOp(";") {
				p.next()
				extract, err = p.parsePipe()
				if err != nil {
					return nil, err
				}
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return &foreachNode{source: src, pattern: pat, init: init, update: update, extract: extract}, nil
		case "def":
			p.pos--
			return p.parseFuncDef()
		case "label":
			v := p.next()
			if v.kind != tVar {
				return nil, fmt.Errorf("syntax error: expected label name")
			}
			if err := p.expectOp("|"); err != nil {
				return nil, err
			}
			body, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			return &labelNode{name: v.val, body: body}, nil
		case "break":
			v := p.next()
			if v.kind != tVar {
				return nil, fmt.Errorf("syntax error: expected label name")
			}
			return &breakNode{name: v.val}, nil
		}
		return nil, fmt.Errorf("syntax error: unexpected keyword %q", t.val)
	case tIdent:
		// function call
		if p.isOp("(") {
			p.next()
			args := []node{}
			for {
				a, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				args = append(args, a)
				if p.isOp(";") {
					p.next()
					continue
				}
				if err := p.expectOp(")"); err != nil {
					return nil, err
				}
				break
			}
			return &funcCallNode{name: t.val, args: args}, nil
		}
		switch t.val {
		case "true":
			return &literalNode{value: true}, nil
		case "false":
			return &literalNode{value: false}, nil
		case "null":
			return &literalNode{value: nil}, nil
		}
		return &funcCallNode{name: t.val}, nil
	case tOp:
		switch t.val {
		case ".":
			// . or ."foo" or .[...]
			nt := p.peek()
			if nt.kind == tString {
				p.next()
				return &fieldNode{target: &identityNode{}, name: &stringNode{parts: nt.parts}}, nil
			}
			if nt.kind == tOp && nt.val == "[" {
				return p.parseBracketSuffix(&identityNode{})
			}
			return &identityNode{}, nil
		case "..":
			return &recurseNode{}, nil
		case "(":
			e, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return e, nil
		case "[":
			if p.isOp("]") {
				p.next()
				return &arrayNode{}, nil
			}
			e, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp("]"); err != nil {
				return nil, err
			}
			return &arrayNode{elem: e}, nil
		case "{":
			return p.parseObject()
		case "-":
			e, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			return &negNode{expr: e}, nil
		}
	}
	return nil, fmt.Errorf("syntax error: unexpected token %q", tokStr(t))
}

// parsePostfixTerm - a term with postfix operators (used after try/reduce/foreach)
func (p *parser) parsePostfixTerm() (node, error) {
	return p.parsePostfix()
}

func (p *parser) parseIf() (node, error) {
	cond, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectKw("then"); err != nil {
		return nil, err
	}
	then, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	n := &ifNode{cond: cond, then: then}
	for p.isKw("elif") {
		p.next()
		c, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if err := p.expectKw("then"); err != nil {
			return nil, err
		}
		t, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		n.elifs = append(n.elifs, ifBranch{cond: c, then: t})
	}
	if p.isKw("else") {
		p.next()
		n.els, err = p.parsePipe()
		if err != nil {
			return nil, err
		}
	}
	if err := p.expectKw("end"); err != nil {
		return nil, err
	}
	return n, nil
}

func (p *parser) parseObject() (node, error) {
	obj := &objectNode{}
	if p.isOp("}") {
		p.next()
		return obj, nil
	}
	for {
		var e objEntry
		t := p.peek()
		switch {
		case t.kind == tVar:
			p.next()
			e.key = &literalNode{value: t.val}
			e.value = &varNode{name: t.val}
			if t.val == "__loc__" {
				e.value = &funcCallNode{name: "$__loc__"}
			}
		case t.kind == tIdent || t.kind == tKeyword:
			p.next()
			e.key = &literalNode{value: t.val}
		case t.kind == tNumber:
			p.next()
			e.key = &literalNode{value: t.val}
		case t.kind == tString:
			p.next()
			e.key = &stringNode{parts: t.parts}
		case t.kind == tFormat:
			p.next()
			if p.peek().kind == tString {
				st := p.next()
				e.key = &stringNode{parts: st.parts, format: t.val}
			} else {
				e.key = &formatNode{name: t.val}
			}
		case t.kind == tOp && t.val == "(":
			p.next()
			k, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			e.key = k
		default:
			return nil, fmt.Errorf("syntax error: unexpected token %q in object", tokStr(t))
		}
		if p.isOp(":") {
			p.next()
			v, err := p.parseObjectValue()
			if err != nil {
				return nil, err
			}
			e.value = v
		} else if e.value == nil {
			// shorthand {foo} == {foo: .foo}
			if lit, ok := e.key.(*literalNode); ok {
				e.value = &fieldNode{target: &identityNode{}, name: &literalNode{value: lit.value}}
			} else if sn, ok := e.key.(*stringNode); ok {
				e.value = &fieldNode{target: &identityNode{}, name: sn}
			} else {
				return nil, fmt.Errorf("syntax error: object key needs a value")
			}
		}
		obj.entries = append(obj.entries, e)
		if p.isOp(",") {
			p.next()
			continue
		}
		if err := p.expectOp("}"); err != nil {
			return nil, err
		}
		return obj, nil
	}
}

// object values can't contain unparenthesised commas or pipes at the top level
// (jq allows "a: 1 | 2"? no - values are ExpD: alternatives/arithmetic, with
// '|' allowed between terms).
func (p *parser) parseObjectValue() (node, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	for p.isOp("|") {
		p.next()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		left = &pipeNode{left: left, right: right}
	}
	return left, nil
}
