package jq

import (
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"sort"
	"strings"
)

// jqError - an error raised by the query (e.g. via error/1)
type jqError struct {
	value interface{}
}

func (e *jqError) Error() string {
	switch v := e.value.(type) {
	case string:
		return v
	case nil:
		return "null (null)"
	default:
		b, _ := json.Marshal(v)
		return fmt.Sprintf("%s (%s)", string(b), typeOf(v))
	}
}

type breakError struct{ label string }

func (e *breakError) Error() string { return "break" }

// function closure
type funcDef struct {
	params []string
	body   node
	env    *env
}

// closure argument (a filter passed to a function)
type closure struct {
	body node
	env  *env
}

type env struct {
	parent *env
	vars   map[string]interface{}
	funcs  map[string]*funcDef    // "name/arity"
	cls    map[string]*closure    // filter params by name
	labels map[string]bool
}

func newEnv(parent *env) *env {
	return &env{parent: parent}
}

func (e *env) lookupVar(name string) (interface{}, bool) {
	for c := e; c != nil; c = c.parent {
		if c.vars != nil {
			if v, ok := c.vars[name]; ok {
				return v, true
			}
		}
	}
	return nil, false
}

func (e *env) setVar(name string, v interface{}) {
	if e.vars == nil {
		e.vars = map[string]interface{}{}
	}
	e.vars[name] = v
}

func (e *env) lookupFunc(name string, arity int) (*funcDef, bool) {
	key := fmt.Sprintf("%s/%d", name, arity)
	for c := e; c != nil; c = c.parent {
		if c.funcs != nil {
			if f, ok := c.funcs[key]; ok {
				return f, true
			}
		}
	}
	return nil, false
}

func (e *env) lookupClosure(name string) (*closure, bool) {
	for c := e; c != nil; c = c.parent {
		if c.cls != nil {
			if f, ok := c.cls[name]; ok {
				return f, true
			}
		}
	}
	return nil, false
}

// Run - run the query against the input, returning all outputs
func Run(query string, input interface{}) ([]interface{}, error) {
	n, err := Parse(query)
	if err != nil {
		return nil, err
	}
	in := normalize(input)
	e := newEnv(nil)
	e.setVar("ENV", envMap())
	e.setVar("__prog_args", nil)
	return eval(n, in, e)
}

func envMap() interface{} {
	return nil
}

// normalize converts arbitrary Go values into jq's value model
func normalize(v interface{}) interface{} {
	switch t := v.(type) {
	case nil, bool, string, int, float64:
		return t
	case int8:
		return int(t)
	case int16:
		return int(t)
	case int32:
		return int(t)
	case int64:
		return int(t)
	case uint:
		return int(t)
	case uint8:
		return int(t)
	case uint16:
		return int(t)
	case uint32:
		return int(t)
	case uint64:
		if t > math.MaxInt64 {
			return float64(t)
		}
		return int(t)
	case float32:
		return float64(t)
	case json.Number:
		if i, err := t.Int64(); err == nil {
			return int(i)
		}
		f, _ := t.Float64()
		return f
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, e := range t {
			out[i] = normalize(e)
		}
		return out
	case map[string]interface{}:
		out := make(map[string]interface{}, len(t))
		for k, e := range t {
			out[k] = normalize(e)
		}
		return out
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Slice, reflect.Array:
		out := make([]interface{}, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = normalize(rv.Index(i).Interface())
		}
		return out
	case reflect.Map:
		out := make(map[string]interface{}, rv.Len())
		iter := rv.MapRange()
		for iter.Next() {
			out[fmt.Sprint(iter.Key().Interface())] = normalize(iter.Value().Interface())
		}
		return out
	case reflect.Pointer, reflect.Interface:
		if rv.IsNil() {
			return nil
		}
		return normalize(rv.Elem().Interface())
	}
	// fall back to a JSON round-trip
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	var out interface{}
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.UseNumber()
	if err := dec.Decode(&out); err != nil {
		return string(b)
	}
	return normalize(out)
}

func typeOf(v interface{}) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case int, float64:
		return "number"
	case string:
		return "string"
	case []interface{}:
		return "array"
	case map[string]interface{}:
		return "object"
	}
	return "unknown"
}

func truthy(v interface{}) bool {
	switch t := v.(type) {
	case nil:
		return false
	case bool:
		return t
	}
	return true
}

func eval(n node, in interface{}, e *env) ([]interface{}, error) {
	switch t := n.(type) {
	case *identityNode:
		return []interface{}{in}, nil
	case *recurseNode:
		return recurseAll(in), nil
	case *literalNode:
		return []interface{}{t.value}, nil
	case *stringNode:
		return evalString(t, in, e)
	case *formatNode:
		s, err := applyFormat(t.name, in)
		if err != nil {
			return nil, err
		}
		return []interface{}{s}, nil
	case *varNode:
		if t.name == "__loc__" {
			return []interface{}{map[string]interface{}{"file": "<stdin>", "line": 1}}, nil
		}
		v, ok := e.lookupVar(t.name)
		if !ok {
			return nil, fmt.Errorf("$%s is not defined", t.name)
		}
		return []interface{}{v}, nil
	case *fieldNode:
		return evalField(t, in, e)
	case *indexNode:
		return evalIndex(t, in, e)
	case *sliceNode:
		return evalSlice(t, in, e)
	case *iterateNode:
		return evalIterate(t, in, e)
	case *arrayNode:
		if t.elem == nil {
			return []interface{}{[]interface{}{}}, nil
		}
		vals, err := eval(t.elem, in, e)
		if err != nil {
			return nil, err
		}
		if vals == nil {
			vals = []interface{}{}
		}
		return []interface{}{vals}, nil
	case *objectNode:
		return evalObject(t, in, e)
	case *pipeNode:
		lefts, err := eval(t.left, in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, l := range lefts {
			rs, err := eval(t.right, l, e)
			if err != nil {
				return nil, err
			}
			out = append(out, rs...)
		}
		return out, nil
	case *commaNode:
		lefts, err := eval(t.left, in, e)
		if err != nil {
			return nil, err
		}
		rights, err := eval(t.right, in, e)
		if err != nil {
			return nil, err
		}
		return append(lefts, rights...), nil
	case *altNode:
		lefts, err := eval(t.left, in, e)
		out := []interface{}{}
		if err == nil {
			for _, l := range lefts {
				if truthy(l) {
					out = append(out, l)
				}
			}
		} else if _, ok := err.(*breakError); ok {
			return nil, err
		}
		if len(out) > 0 {
			return out, nil
		}
		return eval(t.right, in, e)
	case *binopNode:
		return evalBinop(t, in, e)
	case *andNode:
		lefts, err := eval(t.left, in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, l := range lefts {
			if !truthy(l) {
				out = append(out, false)
				continue
			}
			rights, err := eval(t.right, in, e)
			if err != nil {
				return nil, err
			}
			for _, r := range rights {
				out = append(out, truthy(r))
			}
		}
		return out, nil
	case *orNode:
		lefts, err := eval(t.left, in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, l := range lefts {
			if truthy(l) {
				out = append(out, true)
				continue
			}
			rights, err := eval(t.right, in, e)
			if err != nil {
				return nil, err
			}
			for _, r := range rights {
				out = append(out, truthy(r))
			}
		}
		return out, nil
	case *negNode:
		vals, err := eval(t.expr, in, e)
		if err != nil {
			return nil, err
		}
		out := make([]interface{}, 0, len(vals))
		for _, v := range vals {
			switch x := v.(type) {
			case int:
				out = append(out, -x)
			case float64:
				out = append(out, -x)
			default:
				return nil, &jqError{value: fmt.Sprintf("%s (%s) cannot be negated", jsonStr(v), typeOf(v))}
			}
		}
		return out, nil
	case *assignNode:
		return evalAssign(t, in, e)
	case *ifNode:
		return evalIf(t, in, e)
	case *tryNode:
		vals, err := eval(t.body, in, e)
		if err != nil {
			if _, ok := err.(*breakError); ok {
				return nil, err
			}
			if t.catch == nil {
				return []interface{}{}, nil
			}
			var ev interface{}
			if je, ok := err.(*jqError); ok {
				ev = je.value
			} else {
				ev = err.Error()
			}
			return eval(t.catch, ev, e)
		}
		return vals, nil
	case *reduceNode:
		srcs, err := eval(t.source, in, e)
		if err != nil {
			return nil, err
		}
		accs, err := eval(t.init, in, e)
		if err != nil {
			return nil, err
		}
		for _, item := range srcs {
			envs, err := bindPattern(t.pattern, item, e)
			if err != nil {
				return nil, err
			}
			newAccs := []interface{}{}
			for _, acc := range accs {
				for _, ne := range envs {
					rs, err := eval(t.update, acc, ne)
					if err != nil {
						return nil, err
					}
					if len(rs) > 0 {
						newAccs = append(newAccs, rs[len(rs)-1])
					} else {
						newAccs = append(newAccs, nil)
					}
				}
			}
			accs = newAccs
		}
		return accs, nil
	case *foreachNode:
		srcs, err := eval(t.source, in, e)
		if err != nil {
			return nil, err
		}
		accs, err := eval(t.init, in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, acc := range accs {
			state := acc
			for _, item := range srcs {
				envs, err := bindPattern(t.pattern, item, e)
				if err != nil {
					return nil, err
				}
				for _, ne := range envs {
					rs, err := eval(t.update, state, ne)
					if err != nil {
						return nil, err
					}
					for _, r := range rs {
						state = r
						if t.extract != nil {
							ex, err := eval(t.extract, r, ne)
							if err != nil {
								return nil, err
							}
							out = append(out, ex...)
						} else {
							out = append(out, r)
						}
					}
				}
			}
		}
		return out, nil
	case *funcDefNode:
		ne := newEnv(e)
		ne.funcs = map[string]*funcDef{}
		fd := &funcDef{params: t.params, body: t.body, env: ne}
		ne.funcs[fmt.Sprintf("%s/%d", t.name, len(t.params))] = fd
		return eval(t.rest, in, ne)
	case *funcCallNode:
		return evalFuncCall(t, in, e)
	case *bindNode:
		srcs, err := eval(t.source, in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, s := range srcs {
			var envs []*env
			var berr error
			for _, pat := range t.patterns {
				envs, berr = bindPattern(pat, s, e)
				if berr == nil {
					break
				}
			}
			if berr != nil {
				return nil, berr
			}
			for _, ne := range envs {
				rs, err := eval(t.body, in, ne)
				if err != nil {
					return nil, err
				}
				out = append(out, rs...)
			}
		}
		return out, nil
	case *optionalNode:
		vals, err := eval(t.expr, in, e)
		if err != nil {
			if _, ok := err.(*breakError); ok {
				return nil, err
			}
			return []interface{}{}, nil
		}
		return vals, nil
	case *labelNode:
		ne := newEnv(e)
		ne.labels = map[string]bool{t.name: true}
		vals, err := eval(t.body, in, ne)
		if err != nil {
			if be, ok := err.(*breakError); ok && be.label == t.name {
				return vals, nil
			}
			return nil, err
		}
		return vals, nil
	case *breakNode:
		return nil, &breakError{label: t.name}
	}
	return nil, fmt.Errorf("unsupported expression %T", n)
}

func jsonStr(v interface{}) string {
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	return string(b)
}

func evalString(t *stringNode, in interface{}, e *env) ([]interface{}, error) {
	// cartesian product of interpolated parts
	results := []string{""}
	for _, part := range t.parts {
		if !part.isExpr {
			for i := range results {
				results[i] += part.lit
			}
			continue
		}
		sub, err := Parse(part.query)
		if err != nil {
			return nil, err
		}
		vals, err := eval(sub, in, e)
		if err != nil {
			return nil, err
		}
		next := []string{}
		for _, r := range results {
			for _, v := range vals {
				var s string
				if t.format != "" {
					fs, err := applyFormat(t.format, v)
					if err != nil {
						return nil, err
					}
					s = fs
				} else if str, ok := v.(string); ok {
					s = str
				} else {
					s = jsonStr(v)
				}
				next = append(next, r+s)
			}
		}
		results = next
	}
	out := make([]interface{}, len(results))
	for i, r := range results {
		out[i] = r
	}
	return out, nil
}

func evalField(t *fieldNode, in interface{}, e *env) ([]interface{}, error) {
	targets, err := eval(t.target, in, e)
	if err != nil {
		return nil, err
	}
	names, err := eval(t.name, in, e)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, tgt := range targets {
		for _, name := range names {
			v, err := indexValue(tgt, name)
			if err != nil {
				if t.opt {
					continue
				}
				return nil, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

func evalIndex(t *indexNode, in interface{}, e *env) ([]interface{}, error) {
	targets, err := eval(t.target, in, e)
	if err != nil {
		return nil, err
	}
	idxs, err := eval(t.index, in, e)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, tgt := range targets {
		for _, idx := range idxs {
			v, err := indexValue(tgt, idx)
			if err != nil {
				if t.opt {
					continue
				}
				return nil, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

// indexValue - .[idx]
func indexValue(tgt, idx interface{}) (interface{}, error) {
	switch c := tgt.(type) {
	case nil:
		switch idx.(type) {
		case string, int, float64, nil:
			return nil, nil
		case map[string]interface{}:
			return nil, nil
		}
		return nil, &jqError{value: fmt.Sprintf("Cannot index null with %s", typeOf(idx))}
	case map[string]interface{}:
		k, ok := idx.(string)
		if !ok {
			return nil, &jqError{value: fmt.Sprintf("Cannot index object with %s", typeOf(idx))}
		}
		return c[k], nil
	case []interface{}:
		switch i := idx.(type) {
		case int:
			if i < 0 {
				i += len(c)
			}
			if i < 0 || i >= len(c) {
				return nil, nil
			}
			return c[i], nil
		case float64:
			ii := int(math.Floor(i))
			if ii < 0 {
				ii += len(c)
			}
			if ii < 0 || ii >= len(c) {
				return nil, nil
			}
			return c[ii], nil
		case []interface{}:
			return indicesOf(c, i), nil
		case map[string]interface{}:
			return sliceValue(c, i["start"], i["end"])
		}
		return nil, &jqError{value: fmt.Sprintf("Cannot index array with %s", typeOf(idx))}
	case string:
		if m, ok := idx.(map[string]interface{}); ok {
			return sliceValue(c, m["start"], m["end"])
		}
		return nil, &jqError{value: fmt.Sprintf("Cannot index string with %s", typeOf(idx))}
	}
	return nil, &jqError{value: fmt.Sprintf("Cannot index %s with %s", typeOf(tgt), typeOf(idx))}
}

func indicesOf(arr []interface{}, sub []interface{}) interface{} {
	if len(sub) == 0 {
		return nil
	}
	out := []interface{}{}
	for i := 0; i+len(sub) <= len(arr); i++ {
		match := true
		for j := range sub {
			if compare(arr[i+j], sub[j]) != 0 {
				match = false
				break
			}
		}
		if match {
			out = append(out, i)
		}
	}
	return out
}

func toIndex(v interface{}, def int) (int, bool) {
	switch i := v.(type) {
	case nil:
		return def, true
	case int:
		return i, true
	case float64:
		return int(math.Floor(i)), true
	}
	return 0, false
}

func sliceValue(tgt interface{}, from, to interface{}) (interface{}, error) {
	var length int
	switch c := tgt.(type) {
	case nil:
		return nil, nil
	case []interface{}:
		length = len(c)
	case string:
		length = len([]rune(c))
	default:
		return nil, &jqError{value: fmt.Sprintf("Cannot index %s with object", typeOf(tgt))}
	}
	f, ok := toIndex(from, 0)
	if !ok {
		return nil, &jqError{value: "Start and end indices of an array slice must be numbers"}
	}
	t, ok := toIndex(to, length)
	if !ok {
		return nil, &jqError{value: "Start and end indices of an array slice must be numbers"}
	}
	if f < 0 {
		f += length
	}
	if t < 0 {
		t += length
	}
	if f < 0 {
		f = 0
	}
	if t > length {
		t = length
	}
	if f > length {
		f = length
	}
	if t < f {
		t = f
	}
	switch c := tgt.(type) {
	case []interface{}:
		out := make([]interface{}, t-f)
		copy(out, c[f:t])
		return out, nil
	case string:
		return string([]rune(c)[f:t]), nil
	}
	return nil, nil
}

func evalSlice(t *sliceNode, in interface{}, e *env) ([]interface{}, error) {
	targets, err := eval(t.target, in, e)
	if err != nil {
		return nil, err
	}
	froms := []interface{}{nil}
	tos := []interface{}{nil}
	if t.from != nil {
		froms, err = eval(t.from, in, e)
		if err != nil {
			return nil, err
		}
	}
	if t.to != nil {
		tos, err = eval(t.to, in, e)
		if err != nil {
			return nil, err
		}
	}
	out := []interface{}{}
	for _, tgt := range targets {
		for _, f := range froms {
			for _, to := range tos {
				v, err := sliceValue(tgt, f, to)
				if err != nil {
					if t.opt {
						continue
					}
					return nil, err
				}
				out = append(out, v)
			}
		}
	}
	return out, nil
}

func evalIterate(t *iterateNode, in interface{}, e *env) ([]interface{}, error) {
	targets, err := eval(t.target, in, e)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, tgt := range targets {
		vals, err := iterateValue(tgt)
		if err != nil {
			if t.opt {
				continue
			}
			return nil, err
		}
		out = append(out, vals...)
	}
	return out, nil
}

func iterateValue(tgt interface{}) ([]interface{}, error) {
	switch c := tgt.(type) {
	case []interface{}:
		return c, nil
	case map[string]interface{}:
		keys := sortedKeys(c)
		out := make([]interface{}, len(keys))
		for i, k := range keys {
			out[i] = c[k]
		}
		return out, nil
	}
	return nil, &jqError{value: fmt.Sprintf("Cannot iterate over %s", typeOfWithValue(tgt))}
}

func typeOfWithValue(v interface{}) string {
	switch v.(type) {
	case nil:
		return "null"
	case []interface{}, map[string]interface{}:
		return typeOf(v)
	}
	return fmt.Sprintf("%s (%s)", typeOf(v), jsonStr(v))
}

func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func evalObject(t *objectNode, in interface{}, e *env) ([]interface{}, error) {
	results := []map[string]interface{}{{}}
	for _, entry := range t.entries {
		keys, err := eval(entry.key, in, e)
		if err != nil {
			return nil, err
		}
		vals, err := eval(entry.value, in, e)
		if err != nil {
			return nil, err
		}
		next := []map[string]interface{}{}
		for _, r := range results {
			for _, k := range keys {
				ks, ok := k.(string)
				if !ok {
					return nil, &jqError{value: fmt.Sprintf("Object keys must be strings")}
				}
				for _, v := range vals {
					m := make(map[string]interface{}, len(r)+1)
					for kk, vv := range r {
						m[kk] = vv
					}
					m[ks] = v
					next = append(next, m)
				}
			}
		}
		results = next
	}
	out := make([]interface{}, len(results))
	for i, r := range results {
		out[i] = r
	}
	return out, nil
}

func evalIf(t *ifNode, in interface{}, e *env) ([]interface{}, error) {
	conds, err := eval(t.cond, in, e)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, c := range conds {
		if truthy(c) {
			rs, err := eval(t.then, in, e)
			if err != nil {
				return nil, err
			}
			out = append(out, rs...)
			continue
		}
		// elifs
		var rest node
		if len(t.elifs) > 0 {
			rest = &ifNode{cond: t.elifs[0].cond, then: t.elifs[0].then, elifs: t.elifs[1:], els: t.els}
		} else if t.els != nil {
			rest = t.els
		} else {
			rest = &identityNode{}
		}
		rs, err := eval(rest, in, e)
		if err != nil {
			return nil, err
		}
		out = append(out, rs...)
	}
	return out, nil
}

func evalBinop(t *binopNode, in interface{}, e *env) ([]interface{}, error) {
	rights, err := eval(t.right, in, e)
	if err != nil {
		return nil, err
	}
	lefts, err := eval(t.left, in, e)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, r := range rights {
		for _, l := range lefts {
			v, err := binop(t.op, l, r)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

func binop(op string, l, r interface{}) (interface{}, error) {
	switch op {
	case "==":
		return compare(l, r) == 0, nil
	case "!=":
		return compare(l, r) != 0, nil
	case "<":
		return compare(l, r) < 0, nil
	case "<=":
		return compare(l, r) <= 0, nil
	case ">":
		return compare(l, r) > 0, nil
	case ">=":
		return compare(l, r) >= 0, nil
	case "+":
		return add(l, r)
	case "-":
		return subtract(l, r)
	case "*":
		return multiply(l, r)
	case "/":
		return divide(l, r)
	case "%":
		return modulo(l, r)
	}
	return nil, fmt.Errorf("unknown operator %s", op)
}

func numOp(l, r interface{}, iop func(a, b int) (interface{}, bool), fop func(a, b float64) interface{}) (interface{}, bool) {
	li, lok := l.(int)
	ri, rok := r.(int)
	if lok && rok {
		if v, ok := iop(li, ri); ok {
			return v, true
		}
	}
	lf, lok := toFloat(l)
	rf, rok := toFloat(r)
	if lok && rok {
		return normNum(fop(lf, rf)), true
	}
	return nil, false
}

func toFloat(v interface{}) (float64, bool) {
	switch t := v.(type) {
	case int:
		return float64(t), true
	case float64:
		return t, true
	}
	return 0, false
}

// normNum converts whole-number floats back to ints when they're exact
func normNum(v interface{}) interface{} {
	if f, ok := v.(float64); ok {
		if f == math.Trunc(f) && math.Abs(f) < 1e15 && !math.IsInf(f, 0) {
			return int(f)
		}
	}
	return v
}

func add(l, r interface{}) (interface{}, error) {
	if l == nil {
		return r, nil
	}
	if r == nil {
		return l, nil
	}
	if v, ok := numOp(l, r, func(a, b int) (interface{}, bool) {
		s := a + b
		if (s > a) == (b > 0) {
			return s, true
		}
		return nil, false
	}, func(a, b float64) interface{} { return a + b }); ok {
		return v, nil
	}
	switch lt := l.(type) {
	case string:
		if rs, ok := r.(string); ok {
			return lt + rs, nil
		}
	case []interface{}:
		if ra, ok := r.([]interface{}); ok {
			out := make([]interface{}, 0, len(lt)+len(ra))
			out = append(out, lt...)
			return append(out, ra...), nil
		}
	case map[string]interface{}:
		if rm, ok := r.(map[string]interface{}); ok {
			out := make(map[string]interface{}, len(lt)+len(rm))
			for k, v := range lt {
				out[k] = v
			}
			for k, v := range rm {
				out[k] = v
			}
			return out, nil
		}
	}
	return nil, &jqError{value: fmt.Sprintf("%s and %s cannot be added", typeOfWithValue(l), typeOfWithValue(r))}
}

func subtract(l, r interface{}) (interface{}, error) {
	if v, ok := numOp(l, r, func(a, b int) (interface{}, bool) {
		s := a - b
		if (s < a) == (b > 0) {
			return s, true
		}
		return nil, false
	}, func(a, b float64) interface{} { return a - b }); ok {
		return v, nil
	}
	if la, ok := l.([]interface{}); ok {
		if ra, ok := r.([]interface{}); ok {
			out := []interface{}{}
			for _, x := range la {
				found := false
				for _, y := range ra {
					if compare(x, y) == 0 {
						found = true
						break
					}
				}
				if !found {
					out = append(out, x)
				}
			}
			return out, nil
		}
	}
	return nil, &jqError{value: fmt.Sprintf("%s and %s cannot be subtracted", typeOfWithValue(l), typeOfWithValue(r))}
}

func multiply(l, r interface{}) (interface{}, error) {
	if v, ok := numOp(l, r, func(a, b int) (interface{}, bool) {
		if a == 0 || b == 0 {
			return 0, true
		}
		p := a * b
		if p/b == a {
			return p, true
		}
		return nil, false
	}, func(a, b float64) interface{} { return a * b }); ok {
		return v, nil
	}
	// string repetition
	if s, ok := l.(string); ok {
		if n, ok := toFloat(r); ok {
			return repeatString(s, n), nil
		}
	}
	if s, ok := r.(string); ok {
		if n, ok := toFloat(l); ok {
			return repeatString(s, n), nil
		}
	}
	// deep merge
	if lm, ok := l.(map[string]interface{}); ok {
		if rm, ok := r.(map[string]interface{}); ok {
			return deepMerge(lm, rm), nil
		}
	}
	return nil, &jqError{value: fmt.Sprintf("%s and %s cannot be multiplied", typeOfWithValue(l), typeOfWithValue(r))}
}

func repeatString(s string, n float64) interface{} {
	if n <= 0 {
		return nil
	}
	count := int(n)
	if float64(count) < n {
		count++
	}
	return strings.Repeat(s, count)
}

func deepMerge(l, r map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(l))
	for k, v := range l {
		out[k] = v
	}
	for k, rv := range r {
		if lv, ok := out[k]; ok {
			lm, lok := lv.(map[string]interface{})
			rm, rok := rv.(map[string]interface{})
			if lok && rok {
				out[k] = deepMerge(lm, rm)
				continue
			}
		}
		out[k] = rv
	}
	return out
}

func divide(l, r interface{}) (interface{}, error) {
	lf, lok := toFloat(l)
	rf, rok := toFloat(r)
	if lok && rok {
		if rf == 0 {
			return nil, &jqError{value: fmt.Sprintf("%s and %s cannot be divided because the divisor is zero", typeOfWithValue(l), typeOfWithValue(r))}
		}
		return normNum(lf / rf), nil
	}
	if ls, ok := l.(string); ok {
		if rs, ok := r.(string); ok {
			parts := strings.Split(ls, rs)
			out := make([]interface{}, len(parts))
			for i, p := range parts {
				out[i] = p
			}
			if ls == "" {
				return []interface{}{}, nil
			}
			return out, nil
		}
	}
	return nil, &jqError{value: fmt.Sprintf("%s and %s cannot be divided", typeOfWithValue(l), typeOfWithValue(r))}
}

func modulo(l, r interface{}) (interface{}, error) {
	lf, lok := toFloat(l)
	rf, rok := toFloat(r)
	if lok && rok {
		li, ri := int(lf), int(rf)
		if ri == 0 {
			return nil, &jqError{value: fmt.Sprintf("%s and %s cannot be divided because the divisor is zero", typeOfWithValue(l), typeOfWithValue(r))}
		}
		if ri < 0 {
			ri = -ri
		}
		res := li % ri
		return res, nil
	}
	return nil, &jqError{value: fmt.Sprintf("%s and %s cannot be divided", typeOfWithValue(l), typeOfWithValue(r))}
}

// compare - jq's total ordering: null < false < true < numbers < strings < arrays < objects
func typeOrder(v interface{}) int {
	switch t := v.(type) {
	case nil:
		return 0
	case bool:
		if !t {
			return 1
		}
		return 2
	case int, float64:
		return 3
	case string:
		return 4
	case []interface{}:
		return 5
	case map[string]interface{}:
		return 6
	}
	return 7
}

func compare(l, r interface{}) int {
	lo, ro := typeOrder(l), typeOrder(r)
	if lo != ro {
		if lo < ro {
			return -1
		}
		return 1
	}
	switch lt := l.(type) {
	case int, float64:
		lf, _ := toFloat(l)
		rf, _ := toFloat(r)
		switch {
		case lf < rf:
			return -1
		case lf > rf:
			return 1
		}
		return 0
	case string:
		return strings.Compare(lt, r.(string))
	case []interface{}:
		ra := r.([]interface{})
		for i := 0; i < len(lt) && i < len(ra); i++ {
			if c := compare(lt[i], ra[i]); c != 0 {
				return c
			}
		}
		switch {
		case len(lt) < len(ra):
			return -1
		case len(lt) > len(ra):
			return 1
		}
		return 0
	case map[string]interface{}:
		rm := r.(map[string]interface{})
		lk, rk := sortedKeys(lt), sortedKeys(rm)
		lkv := make([]interface{}, len(lk))
		for i, k := range lk {
			lkv[i] = k
		}
		rkv := make([]interface{}, len(rk))
		for i, k := range rk {
			rkv[i] = k
		}
		if c := compare(lkv, rkv); c != 0 {
			return c
		}
		for _, k := range lk {
			if c := compare(lt[k], rm[k]); c != 0 {
				return c
			}
		}
		return 0
	}
	return 0
}

func recurseAll(v interface{}) []interface{} {
	out := []interface{}{v}
	switch t := v.(type) {
	case []interface{}:
		for _, e := range t {
			out = append(out, recurseAll(e)...)
		}
	case map[string]interface{}:
		for _, k := range sortedKeys(t) {
			out = append(out, recurseAll(t[k])...)
		}
	}
	return out
}

// bindPattern - destructure value into variables, returning the new env(s)
func bindPattern(p pattern, v interface{}, e *env) ([]*env, error) {
	ne := newEnv(e)
	err := bindInto(p, v, ne, e)
	if err != nil {
		return nil, err
	}
	return []*env{ne}, nil
}

func bindInto(p pattern, v interface{}, ne *env, evalEnv *env) error {
	switch {
	case p.name != "":
		ne.setVar(p.name, v)
		return nil
	case p.isArr:
		for i, sub := range p.array {
			var elem interface{}
			switch arr := v.(type) {
			case []interface{}:
				if i < len(arr) {
					elem = arr[i]
				}
			case nil:
			default:
				return &jqError{value: fmt.Sprintf("Cannot index %s with number", typeOf(v))}
			}
			if err := bindInto(sub, elem, ne, evalEnv); err != nil {
				return err
			}
		}
		return nil
	case p.isObj:
		for _, op := range p.object {
			var key string
			if op.keyVar != "" {
				key = op.keyVar
			} else {
				keys, err := eval(op.key, v, ne)
				if err != nil {
					return err
				}
				if len(keys) == 0 {
					continue
				}
				ks, ok := keys[0].(string)
				if !ok {
					return &jqError{value: fmt.Sprintf("Cannot index %s with %s", typeOf(v), typeOf(keys[0]))}
				}
				key = ks
			}
			var elem interface{}
			switch m := v.(type) {
			case map[string]interface{}:
				elem = m[key]
			case nil:
			default:
				return &jqError{value: fmt.Sprintf("Cannot index %s with \"%s\"", typeOf(v), key)}
			}
			if op.keyVar != "" {
				ne.setVar(op.keyVar, elem)
			}
			if op.val != nil {
				if err := bindInto(*op.val, elem, ne, evalEnv); err != nil {
					return err
				}
			}
		}
		return nil
	}
	return fmt.Errorf("invalid pattern")
}
