// prelude - builtins defined in jq itself
const prelude = `
def map(f): [.[] | f];
def select(f): if f then . else empty end;
def recurse(f): def r: ., (f | r); r;
def recurse(f; cond): def r: ., (f | select(cond) | r); r;
def recurse_down: recurse;
def to_entries: [keys_unsorted[] as $k | {key: $k, value: .[$k]}];
def from_entries: reduce .[] as $x ({}; . + { ($x | if type == "object" then (if has("key") then .key elif has("k") then .k elif has("name") then .name elif has("Name") then .Name elif has("Key") then .Key elif has("K") then .K else null end) else . end | if type == "string" then . elif type == "null" then "null" elif type == "boolean" or type == "number" then tojson else error("Cannot use " + type + " as object key") end): ($x | if type == "object" then (if has("value") then .value elif has("v") then .v elif has("Value") then .Value elif has("V") then .V else null end) else null end) });
def with_entries(f): to_entries | map(f) | from_entries;
def values: select(. != null);
def nulls: select(. == null);
def booleans: select(type == "boolean");
def numbers: select(type == "number");
def strings: select(type == "string");
def arrays: select(type == "array");
def objects: select(type == "object");
def iterables: select(type == "array" or type == "object");
def scalars: select(type != "array" and type != "object");
def map_values(f): .[] |= f;
def add(f): reduce f as $x (null; . + $x);
def any: reduce .[] as $x (false; . or $x);
def any(f): reduce (.[] | f) as $x (false; . or $x);
def any(g; cond): isempty(first(g | cond | select(.))) | not;
def all: reduce .[] as $x (true; . and $x);
def all(f): reduce (.[] | f) as $x (true; . and $x);
def all(g; cond): isempty(first(g | cond | select(. | not)));
def isempty(g): label $go | (first(g | false), true) | ., break $go;
def range($x): range(0; $x);
def range($from; $upto; $by): if $by > 0 then $from | while(. < $upto; . + $by) elif $by < 0 then $from | while(. > $upto; . + $by) else empty end;
def while(cond; update): def _while: if cond then ., (update | _while) else empty end; _while;
def until(cond; update): def _until: if cond then . else (update | _until) end; _until;
def repeat(f): def _repeat: ., (f | _repeat); _repeat;
def first: .[0];
def last: .[-1];
def nth($n): .[$n];
def nth($n; f): if $n < 0 then error("Out of bounds negative array index") else last(limit($n + 1; f)) end;
def in(xs): . as $x | xs | has($x);
def inside(xs): . as $x | xs | contains($x);
def combinations: if length == 0 then [] else .[0][] as $x | (.[1:] | combinations) as $w | [$x] + $w end;
def combinations(n): . as $dot | [range(n)] | map($dot) | combinations;
def walk(f): def w: if type == "object" then map_values(w) elif type == "array" then map(w) else . end | f; w;
def env: $ENV;
def ascii: [.] | implode;
def todate: strftime("%Y-%m-%dT%H:%M:%SZ");
def fromdate: fromdateiso8601;
def dateadd(u; n): . + n;
def datesub(u; n): . - n;
def date: todate;
def finites: select(isinfinite or isnan | not);
def normals: select(isnormal);
def join($x): reduce .[] as $i (null; (if . == null then "" else . + $x end) + ($i | if . == null then "" elif type == "string" then . else tojson end)) // "";
def flatten: flatten(1e9);
def ascii_downcase: explode | map(if 65 <= . and . <= 90 then . + 32 else . end) | implode;
def ascii_upcase: explode | map(if 97 <= . and . <= 122 then . - 32 else . end) | implode;
def todate: strftime("%Y-%m-%dT%H:%M:%SZ");
def match(re): match(re; null);
def test(re): test(re; null);
def capture(re): capture(re; null);
def capture(re; mods): match(re; mods) | reduce (.captures | .[] | select(.name != null) | { key: .name, value: .string }) as $pair ({}; . + {($pair.key): $pair.value});
def scan(re): scan(re; null);
def scan(re; $flags): match(re; "g" + $flags) | if (.captures | length > 0) then [ .captures | .[] | .string ] else .string end;
def splits($re): splits($re; null);
def splits($re; flags): split($re; flags) | .[];
def sub(re; str): sub(re; str; "");
def gsub(re; str): sub(re; str; "g");
def gsub(re; str; flags): sub(re; str; flags + "g");
def ltrimstr($x): if type == "string" and ($x | type) == "string" and startswith($x) then .[($x | length):] else . end;
def rtrimstr($x): if type == "string" and ($x | type) == "string" and endswith($x) and ($x | length) > 0 then .[:length - ($x | length)] else . end;
def del(f): delpaths([path(f)]);
def paths: path(..) | select(length > 0);
def paths(node_filter): . as $dot | paths | select(. as $p | $dot | getpath($p) | node_filter);
def leaf_paths: paths(scalars);
def to_array: if type == "array" then . else [.] end;
def tostream: path(def r: (.[]? | r), .; r) as $p | getpath($p) | reduce path(.[]?) as $q ([$p, .]; [$p + $q]);
def fromstream(f): { x: null, e: false } as $init | foreach f as $i ($init; if .e then $init else . end | if $i | length == 2 then setpath(["e"]; $i[0] | length == 0) | setpath(["x"] + $i[0]; $i[1]) else setpath(["e"]; $i[0] | length == 1) end; if .e then .x else empty end);
def truncate_stream(stream): . as $n | null | stream | . as $input | if (.[0] | length) > $n then setpath([0]; .[0][$n:]) else empty end;
def limit($n; f): if $n > 0 then label $out | foreach f as $item (0; . + 1; $item, if . >= $n then break $out else empty end) elif $n == 0 then empty else f end;
def first(f): label $out | (f | ., break $out);
def last(f): reduce f as $x (null; $x);
def min_by(f): _min_by_impl(map([f]));
def max_by(f): _max_by_impl(map([f]));
def unique_by(f): [group_by(f)[] | .[0]];
def group_by(f): _group_by_impl(map([f]));
def sort_by(f): _sort_by_impl(map([f]));
def index($i): indices($i) | .[0];
def rindex($i): indices($i) | .[-1:][0];
def indices($i): if type == "array" and ($i | type) == "array" then .[$i] elif type == "array" then .[[$i]] elif ($i | type) == "string" then _strindices($i) else .[[$i]] end;
def getpath_or_null(p): getpath(p);
def INDEX(stream; idx_expr): reduce stream as $row ({}; .[$row | idx_expr | tostring] |= $row);
def INDEX(idx_expr): INDEX(.[]; idx_expr);
def IN(s): any(s == .; .);
def IN(src; s): any(src == s; .);
def input_line_number: 0;
def halt_error: halt_error(5);
def abs: if type == "number" and . < 0 then -. else . end;
def toarray: if type == "array" then . else [.] end;
def pick(pathexps): . as $top | reduce path(pathexps) as $p (null; setpath($p; $top | getpath($p)));
def debug(msg): (msg | debug | empty), .;
def have_literal_numbers: true;
def have_decnum: false;
def splits($re): splits($re; null);
def ascii(i): [i] | implode;
def getpath_safe(p): try getpath(p) catch null;
def significand: . as $x | if $x == 0 then 0 else ($x | fabs | log2 | floor) as $e | $x / pow(2; $e) end;
def tojson_compact: tojson;
`

var preludeFuncs map[string]*funcDef

func init() {
	n, err := Parse(prelude + " .")
	if err != nil {
		panic("jq prelude failed to parse: " + err.Error())
	}
	// walk the chain of funcDefNodes, registering each one
	preludeFuncs = map[string]*funcDef{}
	e := newEnv(nil)
	e.funcs = preludeFuncs
	for {
		fd, ok := n.(*funcDefNode)
		if !ok {
			break
		}
		preludeFuncs[fmt.Sprintf("%s/%d", fd.name, len(fd.params))] = &funcDef{params: fd.params, body: fd.body, env: e}
		n = fd.rest
	}
}

func evalFuncCall(t *funcCallNode, in interface{}, e *env) ([]interface{}, error) {
	// filter parameter?
	if len(t.args) == 0 {
		if cl, ok := e.lookupClosure(t.name); ok {
			return eval(cl.body, in, cl.env)
		}
	}
	// user-defined function
	if fd, ok := e.lookupFunc(t.name, len(t.args)); ok {
		return callFunc(fd, t.args, in, e)
	}
	// prelude function
	if fd, ok := preludeFuncs[fmt.Sprintf("%s/%d", t.name, len(t.args))]; ok {
		return callFunc(fd, t.args, in, e)
	}
	// native builtin
	if fn, ok := natives[fmt.Sprintf("%s/%d", t.name, len(t.args))]; ok {
		return fn(t.args, in, e)
	}
	return nil, fmt.Errorf("%s/%d is not defined", t.name, len(t.args))
}

func callFunc(fd *funcDef, args []node, in interface{}, callerEnv *env) ([]interface{}, error) {
	ne := newEnv(fd.env)
	// recursive reference to itself
	ne.funcs = map[string]*funcDef{}
	// value params ($x) produce a cartesian product
	type valParam struct {
		name string
		vals []interface{}
	}
	valParams := []valParam{}
	for i, p := range fd.params {
		if strings.HasPrefix(p, "$") {
			vals, err := eval(args[i], in, callerEnv)
			if err != nil {
				return nil, err
			}
			valParams = append(valParams, valParam{name: p[1:], vals: vals})
			// also available as a filter
			if ne.cls == nil {
				ne.cls = map[string]*closure{}
			}
			ne.cls[p[1:]] = &closure{body: args[i], env: callerEnv}
		} else {
			if ne.cls == nil {
				ne.cls = map[string]*closure{}
			}
			ne.cls[p] = &closure{body: args[i], env: callerEnv}
		}
	}
	if len(valParams) == 0 {
		return eval(fd.body, in, ne)
	}
	// cartesian product over value params
	out := []interface{}{}
	var rec func(i int, env *env) error
	rec = func(i int, env *env) error {
		if i == len(valParams) {
			rs, err := eval(fd.body, in, env)
			if err != nil {
				return err
			}
			out = append(out, rs...)
			return nil
		}
		for _, v := range valParams[i].vals {
			sub := newEnv(env)
			sub.setVar(valParams[i].name, v)
			if err := rec(i+1, sub); err != nil {
				return err
			}
		}
		return nil
	}
	if err := rec(0, ne); err != nil {
		return nil, err
	}
	return out, nil
}

type nativeFunc func(args []node, in interface{}, e *env) ([]interface{}, error)

var natives map[string]nativeFunc

// helpers for natives taking evaluated args (cartesian product)
func withArgs(args []node, in interface{}, e *env, fn func(vals []interface{}) (interface{}, error)) ([]interface{}, error) {
	argVals := make([][]interface{}, len(args))
	for i, a := range args {
		vs, err := eval(a, in, e)
		if err != nil {
			return nil, err
		}
		argVals[i] = vs
	}
	out := []interface{}{}
	var rec func(i int, cur []interface{}) error
	rec = func(i int, cur []interface{}) error {
		if i == len(argVals) {
			v, err := fn(cur)
			if err != nil {
				return err
			}
			out = append(out, v)
			return nil
		}
		for _, v := range argVals[i] {
			if err := rec(i+1, append(cur, v)); err != nil {
				return err
			}
		}
		return nil
	}
	if err := rec(0, []interface{}{}); err != nil {
		return nil, err
	}
	return out, nil
}

func single(fn func(in interface{}) (interface{}, error)) nativeFunc {
	return func(_ []node, in interface{}, _ *env) ([]interface{}, error) {
		v, err := fn(in)
		if err != nil {
			return nil, err
		}
		return []interface{}{v}, nil
	}
}

func mathFn(name string, f func(float64) float64) nativeFunc {
	return single(func(in interface{}) (interface{}, error) {
		x, ok := toFloat(in)
		if !ok {
			return nil, &jqError{value: fmt.Sprintf("%s number required", typeOfWithValue(in))}
		}
		return normNum(f(x)), nil
	})
}

func init() {
	natives = map[string]nativeFunc{
		"empty/0": func(_ []node, _ interface{}, _ *env) ([]interface{}, error) { return []interface{}{}, nil },
		"not/0":   single(func(in interface{}) (interface{}, error) { return !truthy(in), nil }),
		"length/0": single(func(in interface{}) (interface{}, error) {
			switch t := in.(type) {
			case nil:
				return 0, nil
			case bool:
				return nil, &jqError{value: fmt.Sprintf("boolean (%v) has no length", t)}
			case int:
				if t < 0 {
					return -t, nil
				}
				return t, nil
			case float64:
				return math.Abs(t), nil
			case string:
				return utf8.RuneCountInString(t), nil
			case []interface{}:
				return len(t), nil
			case map[string]interface{}:
				return len(t), nil
			}
			return nil, &jqError{value: fmt.Sprintf("%s has no length", typeOf(in))}
		}),
		"utf8bytelength/0": single(func(in interface{}) (interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s only strings have UTF-8 byte length", typeOfWithValue(in))}
			}
			return len(s), nil
		}),
		"keys/0": single(func(in interface{}) (interface{}, error) {
			switch t := in.(type) {
			case map[string]interface{}:
				ks := sortedKeys(t)
				out := make([]interface{}, len(ks))
				for i, k := range ks {
					out[i] = k
				}
				return out, nil
			case []interface{}:
				out := make([]interface{}, len(t))
				for i := range t {
					out[i] = i
				}
				return out, nil
			}
			return nil, &jqError{value: fmt.Sprintf("%s has no keys", typeOfWithValue(in))}
		}),
		"type/0": single(func(in interface{}) (interface{}, error) { return typeOf(in), nil }),
		"add/0": single(func(in interface{}) (interface{}, error) {
			vals, err := iterateValue(in)
			if err != nil {
				if in == nil {
					return nil, nil
				}
				return nil, err
			}
			var acc interface{}
			for _, v := range vals {
				acc, err = add(acc, v)
				if err != nil {
					return nil, err
				}
			}
			return acc, nil
		}),
		"tostring/0": single(func(in interface{}) (interface{}, error) {
			if s, ok := in.(string); ok {
				return s, nil
			}
			return jsonStr(in), nil
		}),
		"tonumber/0": single(func(in interface{}) (interface{}, error) {
			switch t := in.(type) {
			case int, float64:
				return t, nil
			case string:
				if i, err := strconv.ParseInt(strings.TrimSpace(t), 10, 64); err == nil {
					return int(i), nil
				}
				f, err := strconv.ParseFloat(strings.TrimSpace(t), 64)
				if err != nil {
					return nil, &jqError{value: fmt.Sprintf("%s cannot be parsed as a number", typeOfWithValue(in))}
				}
				return normNum(f), nil
			}
			return nil, &jqError{value: fmt.Sprintf("%s cannot be parsed as a number", typeOfWithValue(in))}
		}),
		"tojson/0": single(func(in interface{}) (interface{}, error) { return jsonStr(in), nil }),
		"fromjson/0": single(func(in interface{}) (interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be parsed as JSON", typeOfWithValue(in))}
			}
			var v interface{}
			dec := json.NewDecoder(strings.NewReader(s))
			dec.UseNumber()
			if err := dec.Decode(&v); err != nil {
				return nil, &jqError{value: fmt.Sprintf("%s (while parsing '%s')", err.Error(), s)}
			}
			return normalize(v), nil
		}),
		"ascii_downcase/0": single(func(in interface{}) (interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be lowercased", typeOfWithValue(in))}
			}
			return strings.Map(func(r rune) rune {
				if r >= 'A' && r <= 'Z' {
					return r + 32
				}
				return r
			}, s), nil
		}),
		"ascii_upcase/0": single(func(in interface{}) (interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be uppercased", typeOfWithValue(in))}
			}
			return strings.Map(func(r rune) rune {
				if r >= 'a' && r <= 'z' {
					return r - 32
				}
				return r
			}, s), nil
		}),
		"explode/0": single(func(in interface{}) (interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be exploded", typeOfWithValue(in))}
			}
			out := []interface{}{}
			for _, r := range s {
				out = append(out, int(r))
			}
			return out, nil
		}),
		"implode/0": single(func(in interface{}) (interface{}, error) {
			arr, ok := in.([]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be imploded", typeOfWithValue(in))}
			}
			var sb strings.Builder
			for _, v := range arr {
				f, ok := toFloat(v)
				if !ok {
					return nil, &jqError{value: "Unicode codepoint must be numeric"}
				}
				sb.WriteRune(rune(int(f)))
			}
			return sb.String(), nil
		}),
		"reverse/0": single(func(in interface{}) (interface{}, error) {
			switch t := in.(type) {
			case nil:
				return []interface{}{}, nil
			case string:
				r := []rune(t)
				for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
					r[i], r[j] = r[j], r[i]
				}
				return string(r), nil
			case []interface{}:
				out := make([]interface{}, len(t))
				for i, v := range t {
					out[len(t)-1-i] = v
				}
				return out, nil
			}
			return nil, &jqError{value: fmt.Sprintf("Cannot reverse %s", typeOfWithValue(in))}
		}),
		"sort/0": single(func(in interface{}) (interface{}, error) {
			arr, ok := in.([]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be sorted, as it is not an array", typeOfWithValue(in))}
			}
			out := make([]interface{}, len(arr))
			copy(out, arr)
			sort.SliceStable(out, func(i, j int) bool { return compare(out[i], out[j]) < 0 })
			return out, nil
		}),
		"_sort_by_impl/1": byImpl(func(arr []interface{}, keys []interface{}) (interface{}, error) {
			idx := make([]int, len(arr))
			for i := range idx {
				idx[i] = i
			}
			sort.SliceStable(idx, func(a, b int) bool { return compare(keys[idx[a]], keys[idx[b]]) < 0 })
			out := make([]interface{}, len(arr))
			for i, j := range idx {
				out[i] = arr[j]
			}
			return out, nil
		}),
		"_group_by_impl/1": byImpl(func(arr []interface{}, keys []interface{}) (interface{}, error) {
			idx := make([]int, len(arr))
			for i := range idx {
				idx[i] = i
			}
			sort.SliceStable(idx, func(a, b int) bool { return compare(keys[idx[a]], keys[idx[b]]) < 0 })
			out := []interface{}{}
			var cur []interface{}
			var curKey interface{}
			for n, j := range idx {
				if n == 0 || compare(keys[j], curKey) != 0 {
					if cur != nil {
						out = append(out, cur)
					}
					cur = []interface{}{}
					curKey = keys[j]
				}
				cur = append(cur, arr[j])
			}
			if cur != nil {
				out = append(out, cur)
			}
			return out, nil
		}),
		"_min_by_impl/1": byImpl(func(arr []interface{}, keys []interface{}) (interface{}, error) {
			if len(arr) == 0 {
				return nil, nil
			}
			best := 0
			for i := range arr {
				if compare(keys[i], keys[best]) < 0 {
					best = i
				}
			}
			return arr[best], nil
		}),
		"_max_by_impl/1": byImpl(func(arr []interface{}, keys []interface{}) (interface{}, error) {
			if len(arr) == 0 {
				return nil, nil
			}
			best := 0
			for i := range arr {
				if compare(keys[i], keys[best]) >= 0 {
					best = i
				}
			}
			return arr[best], nil
		}),
		"min/0": single(func(in interface{}) (interface{}, error) {
			arr, ok := in.([]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be iterated over", typeOfWithValue(in))}
			}
			if len(arr) == 0 {
				return nil, nil
			}
			best := arr[0]
			for _, v := range arr[1:] {
				if compare(v, best) < 0 {
					best = v
				}
			}
			return best, nil
		}),
		"max/0": single(func(in interface{}) (interface{}, error) {
			arr, ok := in.([]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be iterated over", typeOfWithValue(in))}
			}
			if len(arr) == 0 {
				return nil, nil
			}
			best := arr[0]
			for _, v := range arr[1:] {
				if compare(v, best) >= 0 {
					best = v
				}
			}
			return best, nil
		}),
		"unique/0": single(func(in interface{}) (interface{}, error) {
			arr, ok := in.([]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be sorted, as it is not an array", typeOfWithValue(in))}
			}
			out := make([]interface{}, len(arr))
			copy(out, arr)
			sort.SliceStable(out, func(i, j int) bool { return compare(out[i], out[j]) < 0 })
			res := []interface{}{}
			for i, v := range out {
				if i == 0 || compare(v, out[i-1]) != 0 {
					res = append(res, v)
				}
			}
			return res, nil
		}),
		"keys_unsorted/0": single(func(in interface{}) (interface{}, error) {
			switch t := in.(type) {
			case map[string]interface{}:
				ks := sortedKeys(t)
