var preludeFuncs map[string]*funcDef

func init() {
	n, err := Parse(prelude + " .")
	if err != nil {
		panic("jq prelude failed to parse: " + err.Error())
	}
	// walk the chain of funcDefNodes, registering each one
	preludeFuncs = map[string]*funcDef{}
	e := newEnv(nil)
	e.funcs = preludeFuncs
	for {
		fd, ok := n.(*funcDefNode)
		if !ok {
			break
		}
		preludeFuncs[fmt.Sprintf("%s/%d", fd.name, len(fd.params))] = &funcDef{params: fd.params, body: fd.body, env: e}
		n = fd.rest
	}
}

func evalFuncCall(t *funcCallNode, in interface{}, e *env) ([]interface{}, error) {
	// filter parameter?
	if len(t.args) == 0 {
		if cl, ok := e.lookupClosure(t.name); ok {
			return eval(cl.body, in, cl.env)
		}
	}
	// user-defined function
	if fd, ok := e.lookupFunc(t.name, len(t.args)); ok {
		return callFunc(fd, t.args, in, e)
	}
	// prelude function
	if fd, ok := preludeFuncs[fmt.Sprintf("%s/%d", t.name, len(t.args))]; ok {
		return callFunc(fd, t.args, in, e)
	}
	// native builtin
	if fn, ok := natives[fmt.Sprintf("%s/%d", t.name, len(t.args))]; ok {
		return fn(t.args, in, e)
	}
	return nil, fmt.Errorf("%s/%d is not defined", t.name, len(t.args))
}

func callFunc(fd *funcDef, args []node, in interface{}, callerEnv *env) ([]interface{}, error) {
	ne := newEnv(fd.env)
	// recursive reference to itself
	ne.funcs = map[string]*funcDef{}
	// value params ($x) produce a cartesian product
	type valParam struct {
		name string
		vals []interface{}
	}
	valParams := []valParam{}
	for i, p := range fd.params {
		if strings.HasPrefix(p, "$") {
			vals, err := eval(args[i], in, callerEnv)
			if err != nil {
				return nil, err
			}
			valParams = append(valParams, valParam{name: p[1:], vals: vals})
			// also available as a filter
			if ne.cls == nil {
				ne.cls = map[string]*closure{}
			}
			ne.cls[p[1:]] = &closure{body: args[i], env: callerEnv}
		} else {
			if ne.cls == nil {
				ne.cls = map[string]*closure{}
			}
			ne.cls[p] = &closure{body: args[i], env: callerEnv}
		}
	}
	if len(valParams) == 0 {
		return eval(fd.body, in, ne)
	}
	// cartesian product over value params
	out := []interface{}{}
	var rec func(i int, env *env) error
	rec = func(i int, env *env) error {
		if i == len(valParams) {
			rs, err := eval(fd.body, in, env)
			if err != nil {
				return err
			}
			out = append(out, rs...)
			return nil
		}
		for _, v := range valParams[i].vals {
			sub := newEnv(env)
			sub.setVar(valParams[i].name, v)
			if err := rec(i+1, sub); err != nil {
				return err
			}
		}
		return nil
	}
	if err := rec(0, ne); err != nil {
		return nil, err
	}
	return out, nil
}

type nativeFunc func(args []node, in interface{}, e *env) ([]interface{}, error)

var natives map[string]nativeFunc

// helpers for natives taking evaluated args (cartesian product)
func withArgs(args []node, in interface{}, e *env, fn func(vals []interface{}) (interface{}, error)) ([]interface{}, error) {
	argVals := make([][]interface{}, len(args))
	for i, a := range args {
		vs, err := eval(a, in, e)
		if err != nil {
			return nil, err
		}
		argVals[i] = vs
	}
	out := []interface{}{}
	var rec func(i int, cur []interface{}) error
	rec = func(i int, cur []interface{}) error {
		if i == len(argVals) {
			v, err := fn(cur)
			if err != nil {
				return err
			}
			out = append(out, v)
			return nil
		}
		for _, v := range argVals[i] {
			if err := rec(i+1, append(cur, v)); err != nil {
				return err
			}
		}
		return nil
	}
	if err := rec(0, []interface{}{}); err != nil {
		return nil, err
	}
	return out, nil
}

func single(fn func(in interface{}) (interface{}, error)) nativeFunc {
	return func(_ []node, in interface{}, _ *env) ([]interface{}, error) {
		v, err := fn(in)
		if err != nil {
			return nil, err
		}
		return []interface{}{v}, nil
	}
}

func mathFn(name string, f func(float64) float64) nativeFunc {
	return single(func(in interface{}) (interface{}, error) {
		x, ok := toFloat(in)
		if !ok {
			return nil, &jqError{value: fmt.Sprintf("%s number required", typeOfWithValue(in))}
		}
		return normNum(f(x)), nil
	})
}

func init() {
	natives = map[string]nativeFunc{
		"empty/0": func(_ []node, _ interface{}, _ *env) ([]interface{}, error) { return []interface{}{}, nil },
		"not/0":   single(func(in interface{}) (interface{}, error) { return !truthy(in), nil }),
		"length/0": single(func(in interface{}) (interface{}, error) {
			switch t := in.(type) {
			case nil:
				return 0, nil
			case bool:
				return nil, &jqError{value: fmt.Sprintf("boolean (%v) has no length", t)}
			case int:
				if t < 0 {
					return -t, nil
				}
				return t, nil
			case float64:
				return math.Abs(t), nil
			case string:
				return utf8.RuneCountInString(t), nil
			case []interface{}:
				return len(t), nil
			case map[string]interface{}:
				return len(t), nil
			}
			return nil, &jqError{value: fmt.Sprintf("%s has no length", typeOf(in))}
		}),
		"utf8bytelength/0": single(func(in interface{}) (interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s only strings have UTF-8 byte length", typeOfWithValue(in))}
			}
			return len(s), nil
