		"sub/3": func(args []node, in interface{}, e *env) ([]interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("%s cannot be matched, as it is not a string", typeOfWithValue(in))}
			}
			res, err := eval(args[0], in, e)
			if err != nil {
				return nil, err
			}
			flagsV, err := eval(args[2], in, e)
			if err != nil {
				return nil, err
			}
			out := []interface{}{}
			for _, re := range res {
				for _, flags := range flagsV {
					fs, _ := flags.(string)
					ms, err := regexMatch(s, re, flags)
					if err != nil {
						return nil, err
					}
					if !strings.Contains(fs, "g") && len(ms) > 1 {
						ms = ms[:1]
					}
					results := []string{""}
					last := 0
					for _, m := range ms {
						mm := m.(map[string]interface{})
						off := byteOffset(s, mm["offset"].(int))
						capMap := map[string]interface{}{}
						for _, c := range mm["captures"].([]interface{}) {
							cm := c.(map[string]interface{})
							if n, ok := cm["name"].(string); ok && n != "" {
								capMap[n] = cm["string"]
							}
						}
						repls, err := eval(args[1], capMap, e)
						if err != nil {
							return nil, err
						}
						next := []string{}
						for _, r := range results {
							for _, rp := range repls {
								rs, ok := rp.(string)
								if !ok {
									return nil, &jqError{value: fmt.Sprintf("%s cannot be added to a string", typeOfWithValue(rp))}
								}
								next = append(next, r+s[last:off]+rs)
							}
						}
						results = next
						last = off + len(mm["string"].(string))
					}
					for _, r := range results {
						out = append(out, r+s[last:])
					}
				}
			}
			return out, nil
		},
