func osEnv() interface{} {
	m := map[string]interface{}{}
	for _, kv := range os.Environ() {
		if i := strings.Index(kv, "="); i >= 0 {
			m[kv[:i]] = kv[i+1:]
		}
	}
	return m
}

func formatNative(name string) nativeFunc {
	return single(func(in interface{}) (interface{}, error) {
		return applyFormat(name, in)
	})
}

func byImpl(fn func(arr []interface{}, keys []interface{}) (interface{}, error)) nativeFunc {
	return func(args []node, in interface{}, e *env) ([]interface{}, error) {
		arr, ok := in.([]interface{})
		if !ok {
			return nil, &jqError{value: fmt.Sprintf("Cannot index %s with number", typeOf(in))}
		}
		keyVals, err := eval(args[0], in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, kv := range keyVals {
			keys, ok := kv.([]interface{})
			if !ok || len(keys) != len(arr) {
				return nil, &jqError{value: "sort_by/group_by key mismatch"}
			}
			v, err := fn(arr, keys)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	}
}

func strPred(name string, fn func(s, x string) bool) nativeFunc {
	return func(args []node, in interface{}, e *env) ([]interface{}, error) {
		return withArgs(args, in, e, func(vals []interface{}) (interface{}, error) {
			s, ok := in.(string)
			x, ok2 := vals[0].(string)
			if !ok || !ok2 {
				return nil, &jqError{value: fmt.Sprintf("%s() requires string inputs", name)}
			}
			return fn(s, x), nil
		})
	}
}

func contains(a, b interface{}) bool {
	switch bt := b.(type) {
	case map[string]interface{}:
		am, ok := a.(map[string]interface{})
		if !ok {
			return false
		}
		for k, bv := range bt {
			av, ok := am[k]
			if !ok || !contains(av, bv) {
				return false
			}
		}
		return true
	case []interface{}:
		aa, ok := a.([]interface{})
		if !ok {
			return false
		}
		for _, bv := range bt {
			found := false
			for _, av := range aa {
				if contains(av, bv) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	case string:
		as, ok := a.(string)
		return ok && strings.Contains(as, bt)
	}
	return compare(a, b) == 0
}

func flattenDepth(arr []interface{}, depth int) []interface{} {
	out := []interface{}{}
	for _, v := range arr {
		if sub, ok := v.([]interface{}); ok && depth > 0 {
			out = append(out, flattenDepth(sub, depth-1)...)
		} else {
			out = append(out, v)
		}
	}
	return out
}

func compileRe(reV, flagsV interface{}, _ bool) (*regexp.Regexp, error) {
	re, ok := reV.(string)
	if !ok {
		return nil, &jqError{value: fmt.Sprintf("%s cannot be matched, as it is not a string", typeOfWithValue(reV))}
	}
	flags := ""
	if flagsV != nil {
		fs, ok := flagsV.(string)
		if !ok {
			return nil, &jqError{value: fmt.Sprintf("%s is not a string", typeOfWithValue(flagsV))}
		}
		flags = fs
	}
	prefix := ""
	for _, f := range flags {
		switch f {
		case 'i':
			prefix += "i"
		case 'x':
			// extended mode isn't supported; ignore
		case 's':
			prefix += "s"
		case 'n', 'g', 'l', 'p':
		default:
			return nil, &jqError{value: fmt.Sprintf("%s is not a valid modifier string", flags)}
		}
	}
	if prefix != "" {
		re = "(?" + prefix + ")" + re
	}
	r, err := regexp.Compile(re)
	if err != nil {
		return nil, &jqError{value: fmt.Sprintf("%s (at offset 0) is not a valid regex: %s", re, err.Error())}
	}
	return r, nil
}

func regexMatch(s string, reV, flagsV interface{}) ([]interface{}, error) {
	re, err := compileRe(reV, flagsV, false)
	if err != nil {
		return nil, err
	}
	global := false
	if fs, ok := flagsV.(string); ok && strings.Contains(fs, "g") {
		global = true
	}
	var locs [][]int
	if global {
		locs = re.FindAllStringSubmatchIndex(s, -1)
	} else {
		l := re.FindStringSubmatchIndex(s)
		if l != nil {
			locs = [][]int{l}
		}
	}
	names := re.SubexpNames()
	out := []interface{}{}
	for _, loc := range locs {
		m := map[string]interface{}{
			"offset": utf8.RuneCountInString(s[:loc[0]]),
			"length": utf8.RuneCountInString(s[loc[0]:loc[1]]),
			"string": s[loc[0]:loc[1]],
		}
		caps := []interface{}{}
		for i := 1; i < len(loc)/2; i++ {
			c := map[string]interface{}{}
			if loc[2*i] < 0 {
				c["offset"] = -1
				c["length"] = 0
				c["string"] = nil
			} else {
				c["offset"] = utf8.RuneCountInString(s[:loc[2*i]])
				c["length"] = utf8.RuneCountInString(s[loc[2*i]:loc[2*i+1]])
				c["string"] = s[loc[2*i]:loc[2*i+1]]
			}
			if names[i] != "" {
				c["name"] = names[i]
			} else {
				c["name"] = nil
			}
			caps = append(caps, c)
		}
		m["captures"] = caps
		out = append(out, m)
	}
	return out, nil
}

// byteOffset converts a rune offset to a byte offset
func byteOffset(s string, runeOff int) int {
	n := 0
	for i := range s {
		if n == runeOff {
			return i
		}
		n++
	}
	return len(s)
}

func applyFormat(name string, in interface{}) (string, error) {
	switch name {
	case "text":
		if s, ok := in.(string); ok {
			return s, nil
		}
		return jsonStr(in), nil
	case "json":
		return jsonStr(in), nil
	case "html":
		s := toStr(in)
		return html.EscapeString(s), nil
	case "uri":
		s := toStr(in)
		var sb strings.Builder
		for _, b := range []byte(s) {
			if (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') || (b >= '0' && b <= '9') || b == '-' || b == '_' || b == '.' || b == '~' {
				sb.WriteByte(b)
			} else {
				fmt.Fprintf(&sb, "%%%02X", b)
			}
		}
		return sb.String(), nil
	case "csv", "tsv":
		arr, ok := in.([]interface{})
		if !ok {
			return "", &jqError{value: fmt.Sprintf("%s cannot be %s-formatted, only an array can be", typeOfWithValue(in), name)}
		}
		fields := make([]string, len(arr))
		for i, v := range arr {
			switch t := v.(type) {
			case string:
				if name == "csv" {
					fields[i] = `"` + strings.ReplaceAll(t, `"`, `""`) + `"`
				} else {
					r := strings.NewReplacer("\\", "\\\\", "\t", "\\t", "\n", "\\n", "\r", "\\r")
					fields[i] = r.Replace(t)
				}
			case nil:
				fields[i] = ""
			case bool, int, float64:
				fields[i] = jsonStr(t)
			default:
				return "", &jqError{value: fmt.Sprintf("%s is not valid in a csv row", typeOfWithValue(v))}
			}
		}
		if name == "csv" {
			return strings.Join(fields, ","), nil
		}
		return strings.Join(fields, "\t"), nil
	case "sh":
		quote := func(v interface{}) (string, error) {
			switch t := v.(type) {
			case string:
				return "'" + strings.ReplaceAll(t, "'", `'\''`) + "'", nil
			case []interface{}, map[string]interface{}:
				return "", &jqError{value: fmt.Sprintf("%s can not be escaped for shell", typeOfWithValue(v))}
			}
			return jsonStr(v), nil
		}
		if arr, ok := in.([]interface{}); ok {
			parts := make([]string, len(arr))
			for i, v := range arr {
				q, err := quote(v)
				if err != nil {
					return "", err
				}
				parts[i] = q
			}
			return strings.Join(parts, " "), nil
		}
		return quote(in)
	case "base64":
		return base64.StdEncoding.EncodeToString([]byte(toStr(in))), nil
	case "base64d":
		s := toStr(in)
		b, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
			b, err = base64.RawStdEncoding.DecodeString(s)
			if err != nil {
				return "", &jqError{value: fmt.Sprintf("%s is not valid base64 data", typeOfWithValue(in))}
			}
		}
		return string(b), nil
	}
	return "", &jqError{value: fmt.Sprintf("%s is not a valid format", name)}
}

func toStr(in interface{}) string {
	if s, ok := in.(string); ok {
		return s
	}
	return jsonStr(in)
}

var _ = csv.NewWriter
var _ = url.QueryEscape

func timeToBrokenDown(t time.Time) interface{} {
	return []interface{}{t.Year(), int(t.Month()) - 1, t.Day(), t.Hour(), t.Minute(), float64(t.Second()) + float64(t.Nanosecond())/1e9, int(t.Weekday()), t.YearDay() - 1}
}

func brokenDownToTime(arr []interface{}) time.Time {
	get := func(i int) int {
		if i < len(arr) {
			f, _ := toFloat(arr[i])
			return int(f)
		}
		return 0
	}
	return time.Date(get(0), time.Month(get(1)+1), get(2), get(3), get(4), get(5), 0, time.UTC)
}

func strftime(t time.Time, format string) string {
	var sb strings.Builder
	for i := 0; i < len(format); i++ {
		c := format[i]
		if c != '%' || i+1 >= len(format) {
			sb.WriteByte(c)
			continue
		}
		i++
		switch format[i] {
		case 'Y':
			fmt.Fprintf(&sb, "%04d", t.Year())
		case 'm':
			fmt.Fprintf(&sb, "%02d", int(t.Month()))
		case 'd':
			fmt.Fprintf(&sb, "%02d", t.Day())
		case 'H':
			fmt.Fprintf(&sb, "%02d", t.Hour())
		case 'M':
			fmt.Fprintf(&sb, "%02d", t.Minute())
		case 'S':
			fmt.Fprintf(&sb, "%02d", t.Second())
		case 'Z':
			sb.WriteString("UTC")
		case 'z':
			sb.WriteString("+0000")
		case 'j':
			fmt.Fprintf(&sb, "%03d", t.YearDay())
		case 'a':
			sb.WriteString(t.Weekday().String()[:3])
		case 'A':
			sb.WriteString(t.Weekday().String())
		case 'b':
			sb.WriteString(t.Month().String()[:3])
		case 'B':
			sb.WriteString(t.Month().String())
		case 'e':
			fmt.Fprintf(&sb, "%2d", t.Day())
		case 'y':
			fmt.Fprintf(&sb, "%02d", t.Year()%100)
		case 'T':
			fmt.Fprintf(&sb, "%02d:%02d:%02d", t.Hour(), t.Minute(), t.Second())
		case 'D':
			fmt.Fprintf(&sb, "%02d/%02d/%02d", int(t.Month()), t.Day(), t.Year()%100)
		case 'F':
			fmt.Fprintf(&sb, "%04d-%02d-%02d", t.Year(), int(t.Month()), t.Day())
		case 's':
			fmt.Fprintf(&sb, "%d", t.Unix())
		case 'u':
			wd := int(t.Weekday())
			if wd == 0 {
				wd = 7
			}
			fmt.Fprintf(&sb, "%d", wd)
		case 'w':
			fmt.Fprintf(&sb, "%d", int(t.Weekday()))
		case '%':
			sb.WriteByte('%')
		default:
			sb.WriteByte('%')
			sb.WriteByte(format[i])
		}
	}
	return sb.String()
}
