cd /workspace && cat > internal/jq/paths.go <<'EOF'
package jq

import (
	"fmt"
	"math"
)

type pathValue struct {
	path  []interface{}
	value interface{}
}

func appendPath(p []interface{}, elem interface{}) []interface{} {
	out := make([]interface{}, len(p)+1)
	copy(out, p)
	out[len(p)] = elem
	return out
}

// evalPaths evaluates a path expression, returning (path, value) pairs
func evalPaths(n node, in interface{}, e *env, cur []interface{}) ([]pathValue, error) {
	switch t := n.(type) {
	case *identityNode:
		return []pathValue{{path: cur, value: in}}, nil
	case *recurseNode:
		return recursePaths(in, cur), nil
	case *fieldNode:
		targets, err := evalPaths(t.target, in, e, cur)
		if err != nil {
			return nil, err
		}
		names, err := eval(t.name, in, e)
		if err != nil {
			return nil, err
		}
		out := []pathValue{}
		for _, tg := range targets {
			for _, name := range names {
				v, err := indexValue(tg.value, name)
				if err != nil {
					if t.opt {
						continue
					}
					return nil, err
				}
				out = append(out, pathValue{path: appendPath(tg.path, name), value: v})
			}
		}
		return out, nil
	case *indexNode:
		targets, err := evalPaths(t.target, in, e, cur)
		if err != nil {
			return nil, err
		}
		idxs, err := eval(t.index, in, e)
		if err != nil {
			return nil, err
		}
		out := []pathValue{}
		for _, tg := range targets {
			for _, idx := range idxs {
				v, err := indexValue(tg.value, idx)
				if err != nil {
					if t.opt {
						continue
					}
					return nil, err
				}
				out = append(out, pathValue{path: appendPath(tg.path, idx), value: v})
			}
		}
		return out, nil
	case *sliceNode:
		targets, err := evalPaths(t.target, in, e, cur)
		if err != nil {
			return nil, err
		}
		froms := []interface{}{nil}
		tos := []interface{}{nil}
		if t.from != nil {
			froms, err = eval(t.from, in, e)
			if err != nil {
				return nil, err
			}
		}
		if t.to != nil {
			tos, err = eval(t.to, in, e)
			if err != nil {
				return nil, err
			}
		}
		out := []pathValue{}
		for _, tg := range targets {
			for _, f := range froms {
				for _, to := range tos {
					v, err := sliceValue(tg.value, f, to)
					if err != nil {
						if t.opt {
							continue
						}
						return nil, err
					}
					out = append(out, pathValue{path: appendPath(tg.path, map[string]interface{}{"start": f, "end": to}), value: v})
				}
			}
		}
		return out, nil
	case *iterateNode:
		targets, err := evalPaths(t.target, in, e, cur)
		if err != nil {
			return nil, err
		}
		out := []pathValue{}
		for _, tg := range targets {
			switch c := tg.value.(type) {
			case []interface{}:
				for i, v := range c {
					out = append(out, pathValue{path: appendPath(tg.path, i), value: v})
				}
			case map[string]interface{}:
				for _, k := range sortedKeys(c) {
					out = append(out, pathValue{path: appendPath(tg.path, k), value: c[k]})
				}
			case nil:
			default:
				if t.opt {
					continue
				}
				return nil, &jqError{value: fmt.Sprintf("Cannot iterate over %s", typeOfWithValue(tg.value))}
			}
		}
		return out, nil
	case *pipeNode:
		lefts, err := evalPaths(t.left, in, e, cur)
		if err != nil {
			return nil, err
		}
		out := []pathValue{}
		for _, l := range lefts {
			rs, err := evalPaths(t.right, l.value, e, l.path)
			if err != nil {
				return nil, err
			}
			out = append(out, rs...)
		}
		return out, nil
	case *commaNode:
		lefts, err := evalPaths(t.left, in, e, cur)
		if err != nil {
			return nil, err
		}
		rights, err := evalPaths(t.right, in, e, cur)
		if err != nil {
			return nil, err
		}
		return append(lefts, rights...), nil
	case *ifNode:
		conds, err := eval(t.cond, in, e)
		if err != nil {
			return nil, err
		}
		out := []pathValue{}
		for _, c := range conds {
			var branch node
			if truthy(c) {
				branch = t.then
			} else if len(t.elifs) > 0 {
				branch = &ifNode{cond: t.elifs[0].cond, then: t.elifs[0].then, elifs: t.elifs[1:], els: t.els}
			} else if t.els != nil {
				branch = t.els
			} else {
				branch = &identityNode{}
			}
			rs, err := evalPaths(branch, in, e, cur)
			if err != nil {
				return nil, err
			}
			out = append(out, rs...)
		}
		return out, nil
	case *altNode:
		lefts, err := evalPaths(t.left, in, e, cur)
		out := []pathValue{}
		if err == nil {
			for _, l := range lefts {
				if truthy(l.value) {
					out = append(out, l)
				}
			}
		}
		if len(out) > 0 {
			return out, nil
		}
		return evalPaths(t.right, in, e, cur)
	case *optionalNode:
		rs, err := evalPaths(t.expr, in, e, cur)
		if err != nil {
			if _, ok := err.(*breakError); ok {
				return nil, err
			}
			return []pathValue{}, nil
		}
		return rs, nil
	case *tryNode:
		rs, err := evalPaths(t.body, in, e, cur)
		if err != nil {
			if _, ok := err.(*breakError); ok {
				return nil, err
			}
			if t.catch == nil {
				return []pathValue{}, nil
			}
			return nil, err
		}
		return rs, nil
	case *bindNode:
		srcs, err := eval(t.source, in, e)
		if err != nil {
			return nil, err
		}
		out := []pathValue{}
		for _, s := range srcs {
			var envs []*env
			var berr error
			for _, pat := range t.patterns {
				envs, berr = bindPattern(pat, s, e)
				if berr == nil {
					break
				}
			}
			if berr != nil {
				return nil, berr
			}
			for _, ne := range envs {
				rs, err := evalPaths(t.body, in, ne, cur)
				if err != nil {
					return nil, err
				}
				out = append(out, rs...)
			}
		}
		return out, nil
	case *funcDefNode:
		ne := newEnv(e)
		ne.funcs = map[string]*funcDef{}
		ne.funcs[fmt.Sprintf("%s/%d", t.name, len(t.params))] = &funcDef{params: t.params, body: t.body, env: ne}
		return evalPaths(t.rest, in, ne, cur)
	case *reduceNode:
		srcs, err := eval(t.source, in, e)
		if err != nil {
			return nil, err
		}
		accs, err := evalPaths(t.init, in, e, cur)
		if err != nil {
			return nil, err
		}
		for _, item := range srcs {
			envs, err := bindPattern(t.pattern, item, e)
			if err != nil {
				return nil, err
			}
			next := []pathValue{}
			for _, acc := range accs {
				for _, ne := range envs {
					rs, err := evalPaths(t.update, acc.value, ne, acc.path)
					if err != nil {
						return nil, err
					}
					if len(rs) > 0 {
						next = append(next, rs[len(rs)-1])
					}
				}
			}
			accs = next
		}
		return accs, nil
	case *labelNode:
		ne := newEnv(e)
		rs, err := evalPaths(t.body, in, ne, cur)
		if err != nil {
			if be, ok := err.(*breakError); ok && be.label == t.name {
				return rs, nil
			}
			return nil, err
		}
		return rs, nil
	case *breakNode:
		return nil, &breakError{label: t.name}
	case *literalNode:
		if t.value == nil {
			return []pathValue{{path: cur, value: nil}}, nil
		}
	case *funcCallNode:
		return funcPaths(t, in, e, cur)
	}
	return nil, &jqError{value: fmt.Sprintf("Invalid path expression with result %s", pathExprResult(n, in, e))}
}

func pathExprResult(n node, in interface{}, e *env) string {
	vals, err := eval(n, in, e)
	if err != nil || len(vals) == 0 {
		return "null"
	}
	return jsonStr(vals[0])
}

func recursePaths(v interface{}, cur []interface{}) []pathValue {
	out := []pathValue{{path: cur, value: v}}
	switch t := v.(type) {
	case []interface{}:
		for i, e := range t {
			out = append(out, recursePaths(e, appendPath(cur, i))...)
		}
	case map[string]interface{}:
		for _, k := range sortedKeys(t) {
			out = append(out, recursePaths(t[k], appendPath(cur, k))...)
		}
	}
	return out
}

func funcPaths(t *funcCallNode, in interface{}, e *env, cur []interface{}) ([]pathValue, error) {
	// closure params
	if len(t.args) == 0 {
		if cl, ok := e.lookupClosure(t.name); ok {
			return evalPaths(cl.body, in, cl.env, cur)
		}
	}
	key := fmt.Sprintf("%s/%d", t.name, len(t.args))
	switch key {
	case "empty/0":
		return []pathValue{}, nil
	case "getpath/1":
		ps, err := eval(t.args[0], in, e)
		if err != nil {
			return nil, err
		}
		out := []pathValue{}
		for _, p := range ps {
			pa, ok := p.([]interface{})
			if !ok {
				return nil, &jqError{value: "Path must be specified as an array"}
			}
			v, err := getPath(in, pa)
			if err != nil {
				return nil, err
			}
			np := make([]interface{}, 0, len(cur)+len(pa))
			np = append(np, cur...)
			np = append(np, pa...)
			out = append(out, pathValue{path: np, value: v})
		}
		return out, nil
	case "error/0", "error/1":
		_, err := evalFuncCall(t, in, e)
		return nil, err
	}
	// user-defined / prelude functions: inline them
	fd, ok := e.lookupFunc(t.name, len(t.args))
	if !ok {
		fd, ok = preludeFuncs[key]
	}
	if ok {
		ne := newEnv(fd.env)
		ne.funcs = map[string]*funcDef{}
		type valParam struct {
			name string
			vals []interface{}
		}
		valParams := []valParam{}
		for i, p := range fd.params {
			if ne.cls == nil {
				ne.cls = map[string]*closure{}
			}
			if len(p) > 0 && p[0] == '$' {
				vals, err := eval(t.args[i], in, e)
				if err != nil {
					return nil, err
				}
				valParams = append(valParams, valParam{name: p[1:], vals: vals})
				ne.cls[p[1:]] = &closure{body: t.args[i], env: e}
			} else {
				ne.cls[p] = &closure{body: t.args[i], env: e}
			}
		}
		if len(valParams) == 0 {
			return evalPaths(fd.body, in, ne, cur)
		}
		out := []pathValue{}
		var rec func(i int, env *env) error
		rec = func(i int, env *env) error {
			if i == len(valParams) {
				rs, err := evalPaths(fd.body, in, env, cur)
				if err != nil {
					return err
				}
				out = append(out, rs...)
				return nil
			}
			for _, v := range valParams[i].vals {
				sub := newEnv(env)
				sub.setVar(valParams[i].name, v)
				if err := rec(i+1, sub); err != nil {
					return err
				}
			}
			return nil
		}
		if err := rec(0, ne); err != nil {
			return nil, err
		}
		return out, nil
	}
	return nil, &jqError{value: fmt.Sprintf("Invalid path expression with result %s", pathExprResult(t, in, e))}
}

func getPath(v interface{}, p []interface{}) (interface{}, error) {
	cur := v
	for _, k := range p {
		if cur == nil {
			return nil, nil
		}
		var err error
		cur, err = indexValue(cur, k)
		if err != nil {
			return nil, err
		}
	}
	return cur, nil
}

func setPath(v interface{}, p []interface{}, val interface{}) (interface{}, error) {
	if len(p) == 0 {
		return val, nil
	}
	k := p[0]
	switch key := k.(type) {
	case string:
		m, ok := v.(map[string]interface{})
		if v == nil {
			m = map[string]interface{}{}
		} else if !ok {
			return nil, &jqError{value: fmt.Sprintf("Cannot index %s with \"%s\"", typeOf(v), key)}
		}
		child, err := setPath(m[key], p[1:], val)
		if err != nil {
			return nil, err
		}
		out := make(map[string]interface{}, len(m)+1)
		for kk, vv := range m {
			out[kk] = vv
		}
		out[key] = child
		return out, nil
	case int, float64:
		f, _ := toFloat(key)
		idx := int(f)
		arr, ok := v.([]interface{})
		if v == nil {
			arr = []interface{}{}
		} else if !ok {
			return nil, &jqError{value: fmt.Sprintf("Cannot index %s with number", typeOf(v))}
		}
		if idx < 0 {
			idx += len(arr)
			if idx < 0 {
				return nil, &jqError{value: "Out of bounds negative array index"}
			}
		}
		var existing interface{}
		if idx < len(arr) {
			existing = arr[idx]
		}
		child, err := setPath(existing, p[1:], val)
		if err != nil {
			return nil, err
		}
		n := len(arr)
		if idx >= n {
			n = idx + 1
		}
		out := make([]interface{}, n)
		copy(out, arr)
		out[idx] = child
		return out, nil
	case map[string]interface{}:
		// slice assignment
		arr, ok := v.([]interface{})
		if v == nil {
			arr = []interface{}{}
		} else if !ok {
			return nil, &jqError{value: fmt.Sprintf("Cannot update field at object index of %s", typeOf(v))}
		}
		from, _ := toIndex(key["start"], 0)
		to, _ := toIndex(key["end"], len(arr))
		if from < 0 {
			from += len(arr)
		}
		if to < 0 {
			to += len(arr)
		}
		if from < 0 {
			from = 0
		}
		if to > len(arr) {
			to = len(arr)
		}
		if to < from {
			to = from
		}
		cur, _ := sliceValue(arr, from, to)
		child, err := setPath(cur, p[1:], val)
		if err != nil {
			return nil, err
		}
		repl, ok := child.([]interface{})
		if !ok {
			return nil, &jqError{value: "A slice of an array can only be assigned another array"}
		}
		out := make([]interface{}, 0, len(arr)-(to-from)+len(repl))
		out = append(out, arr[:from]...)
		out = append(out, repl...)
		out = append(out, arr[to:]...)
		return out, nil
	case nil:
		return setPath(v, p[1:], val)
	}
	return nil, &jqError{value: fmt.Sprintf("Invalid path component %s", jsonStr(k))}
}

func delPath(v interface{}, p []interface{}) (interface{}, error) {
	if len(p) == 0 {
		return nil, nil
	}
	if v == nil {
		return nil, nil
	}
	k := p[0]
	if len(p) == 1 {
		switch key := k.(type) {
		case string:
			m, ok := v.(map[string]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("Cannot delete field at object index of %s", typeOf(v))}
			}
			out := make(map[string]interface{}, len(m))
			for kk, vv := range m {
				if kk != key {
					out[kk] = vv
				}
			}
			return out, nil
		case int, float64:
			arr, ok := v.([]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("Cannot delete field at array index of %s", typeOf(v))}
			}
			f, _ := toFloat(key)
			idx := int(f)
			if idx < 0 {
				idx += len(arr)
			}
			if idx < 0 || idx >= len(arr) {
				return v, nil
			}
			out := make([]interface{}, 0, len(arr)-1)
			out = append(out, arr[:idx]...)
			out = append(out, arr[idx+1:]...)
			return out, nil
		case map[string]interface{}:
			arr, ok := v.([]interface{})
			if !ok {
				return nil, &jqError{value: fmt.Sprintf("Cannot delete slice of %s", typeOf(v))}
			}
			from, _ := toIndex(key["start"], 0)
			to, _ := toIndex(key["end"], len(arr))
			if from < 0 {
				from += len(arr)
			}
			if to < 0 {
				to += len(arr)
			}
			if from < 0 {
				from = 0
			}
			if to > len(arr) {
				to = len(arr)
			}
			if to < from {
				to = from
			}
			out := make([]interface{}, 0, len(arr)-(to-from))
			out = append(out, arr[:from]...)
			out = append(out, arr[to:]...)
			return out, nil
		}
		return nil, &jqError{value: fmt.Sprintf("Invalid path component %s", jsonStr(k))}
	}
	child, err := indexValue(v, k)
	if err != nil {
		return nil, err
	}
	if child == nil {
		return v, nil
	}
	newChild, err := delPath(child, p[1:])
	if err != nil {
		return nil, err
	}
	return setPath(v, p[:1], newChild)
}

func evalAssign(t *assignNode, in interface{}, e *env) ([]interface{}, error) {
	switch t.op {
	case "|=":
		paths, err := evalPaths(t.left, in, e, []interface{}{})
		if err != nil {
			return nil, err
		}
		cur := in
		for _, pv := range paths {
			old, err := getPath(cur, pv.path)
			if err != nil {
				return nil, err
			}
			rs, err := eval(t.right, old, e)
			if err != nil {
				return nil, err
			}
			if len(rs) == 0 {
				cur, err = delPath(cur, pv.path)
			} else {
				cur, err = setPath(cur, pv.path, rs[0])
			}
			if err != nil {
				return nil, err
			}
		}
		return []interface{}{cur}, nil
	case "=":
		rights, err := eval(t.right, in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, r := range rights {
			paths, err := evalPaths(t.left, in, e, []interface{}{})
			if err != nil {
				return nil, err
			}
			cur := in
			for _, pv := range paths {
				cur, err = setPath(cur, pv.path, r)
				if err != nil {
					return nil, err
				}
			}
			out = append(out, cur)
		}
		return out, nil
	default:
		// arithmetic update: lhs op= rhs  ==>  rhs as $x | lhs |= . op $x
		op := t.op[:len(t.op)-1]
		rights, err := eval(t.right, in, e)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, r := range rights {
			paths, err := evalPaths(t.left, in, e, []interface{}{})
			if err != nil {
				return nil, err
			}
			cur := in
			for _, pv := range paths {
				old, err := getPath(cur, pv.path)
				if err != nil {
					return nil, err
				}
				var nv interface{}
				if op == "//" {
					if truthy(old) {
						nv = old
					} else {
						nv = r
					}
				} else {
					nv, err = binop(op, old, r)
					if err != nil {
						return nil, err
					}
				}
				cur, err = setPath(cur, pv.path, nv)
				if err != nil {
					return nil, err
				}
			}
			out = append(out, cur)
		}
		return out, nil
	}
}

