package parsers

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// CUE - parse a (simple, concrete) CUE document
func CUE(in string) (interface{}, error) {
	p := &cueParser{src: in}
	v, err := p.parseDocument()
	if err != nil {
		return nil, err
	}
	return v, nil
}

// ToCUE - serialise to CUE
func ToCUE(in interface{}) (string, error) {
	var sb strings.Builder
	if err := cueWrite(&sb, in, 0); err != nil {
		return "", err
	}
	return sb.String(), nil
}

type cueParser struct {
	src string
	pos int
}

func (p *cueParser) peek() byte {
	if p.pos >= len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

func (p *cueParser) skipSpace(newlines bool) {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		switch {
		case c == '/' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '/':
			for p.pos < len(p.src) && p.src[p.pos] != '\n' {
				p.pos++
			}
		case c == '\n':
			if !newlines {
				return
			}
			p.pos++
		case c == ' ' || c == '\t' || c == '\r':
			p.pos++
		default:
			return
		}
	}
}

func (p *cueParser) errorf(format string, args ...interface{}) error {
	return fmt.Errorf(format, args...)
}

func (p *cueParser) parseDocument() (interface{}, error) {
	p.skipSpace(true)
	if p.pos >= len(p.src) {
		return map[string]interface{}{}, nil
	}
	// a document is either a struct body (fields) or a single value
	save := p.pos
	if p.looksLikeField() {
		m, err := p.parseFields(0)
		if err != nil {
			return nil, err
		}
		p.skipSpace(true)
		if p.pos < len(p.src) {
			return nil, p.errorf("expected operand, found '%s'", p.tokenDesc())
		}
		return m, nil
	}
	p.pos = save
	v, err := p.parseValue()
	if err != nil {
		return nil, err
	}
	p.skipSpace(true)
	if p.pos < len(p.src) {
		return nil, p.errorf("expected operand, found '%s'", p.tokenDesc())
	}
	return v, nil
}

func (p *cueParser) tokenDesc() string {
	if p.pos >= len(p.src) {
		return "EOF"
	}
	end := p.pos
	for end < len(p.src) && !unicode.IsSpace(rune(p.src[end])) {
		end++
	}
	return p.src[p.pos:end]
}

// looksLikeField - whether the upcoming token is "label:"
func (p *cueParser) looksLikeField() bool {
	save := p.pos
	defer func() { p.pos = save }()
	if _, ok := p.parseLabel(); !ok {
		return false
	}
	p.skipSpace(false)
	return p.peek() == ':'
}

func (p *cueParser) parseLabel() (string, bool) {
	p.skipSpace(false)
	c := p.peek()
	switch {
	case c == '"':
		s, err := p.parseString()
		if err != nil {
			return "", false
		}
		return s, true
	case c == '_' || c == '#' || c == '$' || unicode.IsLetter(rune(c)):
		start := p.pos
		for p.pos < len(p.src) {
			r, size := utf8.DecodeRuneInString(p.src[p.pos:])
			if r == '_' || r == '#' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) {
				p.pos += size
				continue
			}
			break
		}
		return p.src[start:p.pos], true
	}
	return "", false
}

// parseFields parses "label: value" entries until a closing brace (depth>0)
// or EOF (depth==0)
func (p *cueParser) parseFields(depth int) (map[string]interface{}, error) {
	out := map[string]interface{}{}
	for {
		p.skipSpace(true)
		if p.pos >= len(p.src) {
			if depth > 0 {
				return nil, p.errorf("expected '}', found 'EOF'")
			}
			return out, nil
		}
		if p.peek() == '}' {
			if depth == 0 {
				return nil, p.errorf("expected operand, found '}'")
			}
			return out, nil
		}
		if p.peek() == ',' {
			p.pos++
			continue
		}
		label, ok := p.parseLabel()
		if !ok {
			return nil, p.errorf("expected label or ':', found '%s'", p.tokenDesc())
		}
		// optional/required markers
		if p.peek() == '?' || p.peek() == '!' {
			p.pos++
		}
		p.skipSpace(false)
		if p.peek() != ':' {
			return nil, p.errorf("expected ':', found '%s'", p.tokenDesc())
		}
		p.pos++
		p.skipSpace(false)
		var val interface{}
		var err error
		// nested shorthand: a: b: c: 1
		if p.looksLikeField() {
			val, err = p.parseShorthand(out, label)
			if err != nil {
				return nil, err
			}
		} else {
			val, err = p.parseValue()
			if err != nil {
				return nil, err
			}
			out[label] = cueMerge(out[label], val)
		}
		_ = val
		// field terminator: newline, comma, or closing brace
		p.skipSpace(false)
		switch p.peek() {
		case ',':
			p.pos++
		case '\n', '}', 0:
		default:
			if p.src[p.pos] == '/' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '/' {
				continue
			}
			return nil, p.errorf("expected operand, found '%s'", p.tokenDesc())
		}
	}
}

func (p *cueParser) parseShorthand(out map[string]interface{}, label string) (interface{}, error) {
	inner := map[string]interface{}{}
	sublabel, _ := p.parseLabel()
	p.skipSpace(false)
	p.pos++ // ':'
	p.skipSpace(false)
	if p.looksLikeField() {
		if _, err := p.parseShorthand(inner, sublabel); err != nil {
			return nil, err
		}
	} else {
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		inner[sublabel] = v
	}
	out[label] = cueMerge(out[label], inner)
	return out[label], nil
}

// cueMerge unifies two struct values (later fields are merged in)
func cueMerge(existing, val interface{}) interface{} {
	em, eok := existing.(map[string]interface{})
	vm, vok := val.(map[string]interface{})
	if eok && vok {
		for k, v := range vm {
			em[k] = cueMerge(em[k], v)
		}
		return em
	}
	return val
}

var cueTypes = map[string]bool{
	"int": true, "string": true, "bool": true, "number": true, "float": true, "bytes": true,
	"_": true, "uint": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"uint8": true, "uint16": true, "uint32": true, "uint64": true, "float32": true, "float64": true,
	"rune": true, "_|_": true,
}

func (p *cueParser) parseValue() (interface{}, error) {
	p.skipSpace(false)
	if p.pos >= len(p.src) {
		return nil, p.errorf("expected operand, found 'EOF'")
	}
	c := p.peek()
	var v interface{}
	var err error
	switch {
	case c == '{':
		p.pos++
		m, err := p.parseFields(1)
		if err != nil {
			return nil, err
		}
		p.skipSpace(true)
		if p.peek() != '}' {
			return nil, p.errorf("expected '}', found '%s'", p.tokenDesc())
		}
		p.pos++
		v = m
	case c == '[':
		v, err = p.parseList()
		if err != nil {
			return nil, err
		}
	case c == '"':
		v, err = p.parseString()
		if err != nil {
			return nil, err
		}
	case c == '\'':
		v, err = p.parseBytes()
		if err != nil {
			return nil, err
		}
	case c == '-' || c == '+' || c == '.' || (c >= '0' && c <= '9'):
		v, err = p.parseNumber()
		if err != nil {
			return nil, err
		}
	case c == '_' || c == '#' || unicode.IsLetter(rune(c)):
		start := p.pos
		for p.pos < len(p.src) {
			r, size := utf8.DecodeRuneInString(p.src[p.pos:])
			if r == '_' || r == '#' || r == '.' || r == '|' || unicode.IsLetter(r) || unicode.IsDigit(r) {
				p.pos += size
				continue
			}
			break
		}
		word := p.src[start:p.pos]
		switch word {
		case "true":
			v = true
		case "false":
			v = false
		case "null":
			v = nil
		default:
			// types and references are non-concrete: represented as null
			v = nil
		}
	default:
		return nil, p.errorf("expected operand, found '%s'", p.tokenDesc())
	}
	// binary operators (unification/disjunction/arithmetic) - best effort
	p.skipSpace(false)
	for p.pos < len(p.src) {
		c := p.peek()
		if c == '&' || c == '|' {
			p.pos++
			rhs, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			if c == '&' {
				v = cueMerge(v, rhs)
			} else if v == nil {
				v = rhs
			}
			p.skipSpace(false)
			continue
		}
		if c == '+' || c == '-' || c == '*' || c == '/' {
			p.pos++
			rhs, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			v = cueArith(c, v, rhs)
			p.skipSpace(false)
			continue
		}
		break
	}
	return v, nil
}

func cueArith(op byte, l, r interface{}) interface{} {
	lf, lok := cueFloat(l)
	rf, rok := cueFloat(r)
	if lok && rok {
		var res float64
		switch op {
		case '+':
			res = lf + rf
		case '-':
			res = lf - rf
		case '*':
			res = lf * rf
		case '/':
			if rf == 0 {
				return nil
			}
			res = lf / rf
		}
		_, li := l.(int)
		_, ri := r.(int)
		if li && ri && op != '/' {
			return int(res)
		}
		return res
	}
	if ls, ok := l.(string); ok {
		if rs, ok := r.(string); ok && op == '+' {
			return ls + rs
		}
	}
	return nil
}

func cueFloat(v interface{}) (float64, bool) {
	switch t := v.(type) {
	case int:
		return float64(t), true
	case float64:
		return t, true
	}
	return 0, false
}

func (p *cueParser) parseList() (interface{}, error) {
	p.pos++ // [
	out := []interface{}{}
	for {
		p.skipSpace(true)
		if p.pos >= len(p.src) {
			return nil, p.errorf("expected ']', found 'EOF'")
		}
		if p.peek() == ']' {
			p.pos++
			return out, nil
		}
		if p.peek() == ',' {
			p.pos++
			continue
		}
		if strings.HasPrefix(p.src[p.pos:], "...") {
			p.pos += 3
			p.skipSpace(false)
			if p.peek() != ']' && p.peek() != ',' {
				if _, err := p.parseValue(); err != nil {
					return nil, err
				}
			}
			continue
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out = append(out, v)
	}
}

func (p *cueParser) parseNumber() (interface{}, error) {
	start := p.pos
	if p.peek() == '-' || p.peek() == '+' {
		p.pos++
	}
	isFloat := false
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if (c >= '0' && c <= '9') || c == '_' || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') || c == 'x' || c == 'X' || c == 'o' || c == 'b' {
			p.pos++
			continue
		}
		if c == '.' || c == 'e' || c == 'E' {
			isFloat = true
			p.pos++
			if (c == 'e' || c == 'E') && p.pos < len(p.src) && (p.src[p.pos] == '+' || p.src[p.pos] == '-') {
				p.pos++
			}
			continue
		}
		break
	}
	text := strings.ReplaceAll(p.src[start:p.pos], "_", "")
	// SI multipliers
	mult := 1.0
	if p.pos < len(p.src) {
		rest := p.src[p.pos:]
		for _, suf := range []struct {
			s string
			m float64
		}{{"Ki", 1024}, {"Mi", 1 << 20}, {"Gi", 1 << 30}, {"Ti", 1 << 40}, {"Pi", 1 << 50}, {"K", 1e3}, {"M", 1e6}, {"G", 1e9}, {"T", 1e12}, {"P", 1e15}} {
			if strings.HasPrefix(rest, suf.s) {
				mult = suf.m
				p.pos += len(suf.s)
				break
			}
		}
	}
	if !isFloat {
		if i, err := strconv.ParseInt(text, 0, 64); err == nil {
			if mult != 1 {
				return int(float64(i) * mult), nil
			}
			return int(i), nil
		}
	}
	f, err := strconv.ParseFloat(text, 64)
	if err != nil {
		return nil, p.errorf("invalid number %q", text)
	}
	return f * mult, nil
}

func (p *cueParser) parseString() (string, error) {
	// multi-line string
	if strings.HasPrefix(p.src[p.pos:], `"""`) {
		p.pos += 3
		end := strings.Index(p.src[p.pos:], `"""`)
		if end < 0 {
			return "", p.errorf("unterminated multi-line string")
		}
		body := p.src[p.pos : p.pos+end]
		p.pos += end + 3
		lines := strings.Split(body, "\n")
		if len(lines) < 2 {
			return "", p.errorf("invalid multi-line string")
		}
		// the last line holds the closing indentation
		indent := lines[len(lines)-1]
		lines = lines[1 : len(lines)-1]
		for i, l := range lines {
			lines[i] = strings.TrimPrefix(l, indent)
		}
		return cueUnescape(strings.Join(lines, "\n"))
	}
	p.pos++ // opening quote
	var sb strings.Builder
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		switch c {
		case '"':
			p.pos++
			return cueUnescape(sb.String())
		case '\\':
			if p.pos+1 < len(p.src) {
				sb.WriteByte(c)
				sb.WriteByte(p.src[p.pos+1])
				p.pos += 2
				continue
			}
			p.pos++
		case '\n':
			return "", p.errorf("string literal not terminated")
		default:
			sb.WriteByte(c)
			p.pos++
		}
	}
	return "", p.errorf("string literal not terminated")
}

func cueUnescape(s string) (string, error) {
	if !strings.Contains(s, `\`) {
		return s, nil
	}
	// use Go's quoting rules (a close match to CUE's)
	q := `"` + strings.ReplaceAll(s, "\n", `\n`) + `"`
	out, err := strconv.Unquote(q)
	if err != nil {
		// fall back to a simple replacement
		r := strings.NewReplacer(`\n`, "\n", `\t`, "\t", `\"`, `"`, `\\`, `\`, `\r`, "\r")
		return r.Replace(s), nil
	}
	return out, nil
}

func (p *cueParser) parseBytes() (string, error) {
	p.pos++
	start := p.pos
	for p.pos < len(p.src) && p.src[p.pos] != '\'' {
		p.pos++
	}
	if p.pos >= len(p.src) {
		return "", p.errorf("bytes literal not terminated")
	}
	s := p.src[start:p.pos]
	p.pos++
	return s, nil
}

// --- formatting ---

func cueIsIdent(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if r == '_' || unicode.IsLetter(r) || (i > 0 && unicode.IsDigit(r)) {
			continue
		}
		return false
	}
	return true
}

func cueWrite(sb *strings.Builder, v interface{}, depth int) error {
	indent := strings.Repeat("\t", depth)
	switch t := v.(type) {
	case nil:
		sb.WriteString("null")
	case bool:
		sb.WriteString(strconv.FormatBool(t))
	case string:
		if strings.Contains(t, "\n") {
			inner := strings.Repeat("\t", depth+1)
			sb.WriteString(`"""` + "\n")
			for _, line := range strings.Split(t, "\n") {
				sb.WriteString(inner + line + "\n")
			}
			sb.WriteString(inner + `"""`)
		} else {
			sb.WriteString(strconv.Quote(t))
		}
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		sb.WriteString(fmt.Sprintf("%d", t))
	case float64:
		sb.WriteString(strconv.FormatFloat(t, 'g', -1, 64))
	case float32:
		sb.WriteString(strconv.FormatFloat(float64(t), 'g', -1, 32))
	case []interface{}:
		if len(t) == 0 {
			sb.WriteString("[]")
			return nil
		}
		sb.WriteString("[")
		for i, e := range t {
			if i > 0 {
				sb.WriteString(", ")
			}
			if err := cueWrite(sb, e, depth); err != nil {
				return err
			}
		}
		sb.WriteString("]")
	case []string:
		s := make([]interface{}, len(t))
		for i, e := range t {
			s[i] = e
		}
		return cueWrite(sb, s, depth)
	case map[string]interface{}:
		if len(t) == 0 {
			sb.WriteString("{}")
			return nil
		}
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		sb.WriteString("{\n")
		for _, k := range keys {
			sb.WriteString(indent + "\t")
			if cueIsIdent(k) {
				sb.WriteString(k)
			} else {
				sb.WriteString(strconv.Quote(k))
			}
			sb.WriteString(": ")
			if err := cueWrite(sb, t[k], depth+1); err != nil {
				return err
			}
			sb.WriteString("\n")
		}
		sb.WriteString(indent + "}")
	case map[string]string:
		m := make(map[string]interface{}, len(t))
		for k, e := range t {
			m[k] = e
		}
		return cueWrite(sb, m, depth)
	default:
		return fmt.Errorf("unable to marshal %T to CUE", v)
	}
	return nil
}
